/* Verified against NIARIM/dev_branch d52f027d16c1df05c7429b437a3edc7d5bd4ec09, lib/screens/help/help_screen.dart and lib/l10n/app_*.arb.
 * The web help entries are intentionally exact strings from app localization; do not hand-edit. */
(function(){"use strict";var tables={"ja":{"help.category.tool":"ツール","help.category.brush":"ブラシ","help.category.penInput":"ペン入力","help.category.drawing":"描画","help.category.layer":"レイヤー","help.category.animation":"アニメーション","help.category.save":"保存","help.category.projectManagement":"プロジェクト管理","help.category.export":"書き出し","help.category.community":"コミュニティ","help.category.premium":"プレミアム","help.category.settings":"設定","help.entry0.title":"基本の操作（タップ・長押し・スワイプ）","help.entry0.desc":"ツールバーのアイコンはシングルタップでそのツールに切り替わります。同じアイコンを長押し、または上にスワイプすると詳細設定が開きます。ペンならブラシ・トーン・スタンプ・投げ縄塗りの切り替え、バケツならベタ塗りとトーン塗りの切り替え、選択ツールなら矩形・投げ縄・自動選択の切り替え、指ツールならぼかしとモザイクの切り替え、早替えツールなら登録内容の編集が、それぞれ長押し・上スワイプの先にあります。アイコンのダブルタップでは、そのツールの短い説明が画面下に出ます。\\nキャンバスでは、2本指でつまむと拡大縮小、2本指でなぞると移動、2本指のタップで元に戻す、3本指のタップでやり直しです。画面の左右の端をダブルタップすると、前後のフレームへ移動します。\\nマウスやペンタブレットを繋いでいる場合は、ホイールで拡大縮小、中ボタンのドラッグで移動できます。","help.entry1.title":"ペンツール","help.entry1.desc":"キャンバスに線を描くための基本ツールです。長押しでブラシの種類・太さ・色を変更できます（ダブルタップは簡易説明の表示）。板タブ・液晶タブレットの筆圧・傾きに対応しており、設定画面の「ペン入力」から筆圧カーブを調整すると筆圧の伝わり方（弱い力でどれだけ太さ・不透明度が変化するか）を細かくカスタマイズできます。ペンサブツールを切り替えると、同じペンツールからトーン貼り・スタンプ配置も行えます。","help.entry2.title":"消しゴムツール","help.entry2.desc":"ペンツールと対になる、描いた内容を消すためのツールです。ブラシと同様に太さ・不透明度を調整でき、フェードやストローク減衰などのブラシ設定も共通で反映されます。レイヤーの透明部分を「描き足す」のではなく既存の描画を「消す」処理を行うため、下のレイヤーが透けて見えるようになります。","help.entry3.title":"バケツツール","help.entry3.desc":"囲まれた領域を一括で塗りつぶすツールです。線画で囲まれた範囲内をタップすると、その範囲全体が選択中の色（またはトーン）で塗られます。線画に隙間があると意図しない範囲まで塗り広がってしまうことがあるため、線画がきちんと閉じているか確認してから使うのがコツです。設定でベタ塗り／トーン塗りを切り替えられます。 詳細設定（許容誤差・拡張px・線の下まで潜る）は設定画面の「バケツ塗り」から調整できます。","help.entry4.title":"投げ縄塗り","help.entry4.desc":"囲みたい範囲を指でなぞって多角形の範囲を作り、その内側をまとめて塗るツールです。バケツツールと違い、線画が閉じていない部分があっても自分で囲む範囲を指定できるため、複雑な形や線が途切れている部分の塗りに向いています。「囲って塗る」をオンにすると、囲んだ範囲の中にある線で閉じた領域を、いくつあってもバケツ塗りと同じように一括で塗ります（投げ縄と絵の間の余白は塗りません）。","help.entry5.title":"スポイトツール","help.entry5.desc":"タップした位置の色を拾って、描画色として選択するツールです。画面に実際に表示されている全レイヤーを合成した見た目の色を拾うため、複数レイヤーが重なっている部分でも「見た目通りの色」を正確に取得できます。","help.entry6.title":"選択ツール","help.entry6.desc":"キャンバスの一部分を範囲選択し、選択した範囲だけを移動・回転・拡大縮小できるツールです。長押しすると「矩形選択」「投げ縄選択（自由な形で囲む）」「自動選択（マジックワンド、似た色の範囲を自動でまとめて選択）」の3種類から選択方法を選べます。選択中は選択範囲を示す枠線がキャンバス上に表示され、選択を解除するまで全フレーム・全レイヤーで同じ範囲が固定表示されます。投げ縄選択では「線に吸着」をオンにすると、バケツ塗りと同じように線画で区切られた領域を見て、囲みの内側に大部分が入っている領域だけを選択します。選択範囲の縁は線画の外側の縁にぴったり沿い、領域を囲む線と内側にある線も一緒に選択されます（輪郭から外へ伸びている線は輪郭の所で切れます）。色を塗った面もバケツ塗りと同じく色ごとの領域として扱うので、塗りと線のあるレイヤーでも絵の形どおりに選択できます。「線画の隙間許容」で指定した幅までの線の途切れは、つながっているものとして扱います。囲みの中に線画が無いときは、囲んだ形のまま選択します。線画は選択の参照先（「作業レイヤーのみ」／「表示レイヤーすべて」）から探します。","help.entry7.title":"指ツール（歪みツール）","help.entry7.desc":"指でなぞった方向にピクセルを押し流すように歪ませる、液体絵の具を指でこすったような効果を作るツールです。細かい修正よりも、既に描いた線を有機的に歪ませて表情をつけたい時に使います。","help.entry8.title":"図形ツール","help.entry8.desc":"直線・四角形・円といった正確な図形をワンタップで描くためのツールです。ドラッグで始点から終点まで動かすとその場でプレビューされ、指を離すと確定します。フリーハンドでは描きにくい直線や正円が必要な時に便利です。","help.entry9.title":"テキストツール","help.entry9.desc":"キャンバス上に文字を配置するツールです。フォント・サイズ・色・縦書き/横書きを選べます。縦書きでは半角英数字の自動回転・縦中横（数字を横向きのまま並べる表記）・ルビ（ふりがな）にも対応しています。配置したテキストは書き出し時にもピクセルとして焼き込まれます。 テキストツールで使えるフォントを追加・検索・削除できる画面です。初期同梱フォント以外の追加フリーフォントは、初期インストール容量を抑えるためここからオンデマンドでダウンロードする方式になっています。","help.entry10.title":"早替えツール管理","help.entry10.desc":"よく使うツールの組み合わせを登録し、タップひとつで順番に切り替えられる機能です。長押しまたは上スワイプで管理ポップアップを開き、登録内容や並び順を編集できます。","help.entry11.title":"早替えツール","help.entry11.desc":"よく使うブラシ・ツールの組み合わせをあらかじめ登録しておき、ボタン一つで順番に切り替えられる機能です。キャンバス上の↺ボタンを長押しまたは上スワイプすると、登録・並べ替え・削除ができる管理ポップアップが開きます。ドラッグで並び順を変更できます。","help.entry12.title":"スタンプツール","help.entry12.desc":"キャンバスに登録済み画像をブラシのように配置するツールです。集中線や背景パターン、小物などを毎回描き直さず再利用できます。ピクセルモードでは、ドット絵フィルターと共通のPixel Art処理で透明境界を硬く保ちながらピクセル化・減色します。モザイクは別のエフェクトで、スタンプのピクセルモードには使用しません。スタンプパネルでは配置するスタンプの回転角度とサイズも調整できます。","help.entry13.title":"ペン","help.entry13.desc":"ペンツールを長押しすると、通常の描画に加えてトーン貼り・スタンプ配置のサブツールへ切り替えられます。ツールをいちいち切り替えずに、同じペンから複数の作業を行き来できます。","help.entry14.title":"選択範囲の変形","help.entry14.desc":"選択ツールで囲んだ範囲は、キャンバス左下に出る「移動」「拡大縮小」「回転」のボタンでモードを選び、選択範囲の中をドラッグして変形できます。誤って描いた部分の位置調整や、一部だけを拡大して強調したい時などに使います。同じバーの「全選択」を押せば描画中のレイヤー全体が選択範囲になるので、レイヤーまるごとの移動・回転・拡大縮小も同じ操作でできます（以前あった独立した「変形ツール」はここへ統合しました）。格子点を個別にドラッグしてもっと自由に歪ませたい場合は、同じバーの「自由変形」「メッシュ変形」を使ってください。","help.entry15.title":"自由変形・メッシュ変形","help.entry15.desc":"キャンバス右上の編集・設定メニューから開ける、レイヤー全体を対象にした変形ツールです。範囲選択の変形と異なり選択範囲は不要で、角や格子点を指で個別にドラッグして自由な形に変形できます。コントロールパネルの分割数スライダーでメッシュを最大10×10まで細かくでき、2本の指で別々の点を同時につまめば回転・拡大縮小のような操作も直感的に行えます。","help.entry16.title":"カラーピッカー","help.entry16.desc":"HSVとRGBを1つの画面で切り替えながら色を選べるカラーピッカーです。パレット機能で使用中のカラーセットを保存・呼び出しできます。パレットはファイル書き出しやQRコードで他の端末と共有することもできます。","help.entry17.title":"ブラシのお気に入り","help.entry17.desc":"ブラシ一覧の各ブラシにある星アイコンをタップすると、お気に入り登録・解除ができます（自動塗り設定・スタンプ・フォント・描画フィルターなど、アプリ内の他のお気に入り機能と同じ操作方法です）。一覧上部の星アイコンで、お気に入りのみ表示に絞り込むこともできます。誤って削除しないよう、お気に入り登録中のブラシは削除できません。","help.entry18.title":"カスタムブラシ","help.entry18.desc":"ブラシ一覧でプリインストールのブラシを長押しして「複製」すると、それを元にした自分専用のカスタムブラシが作成されます。複製したブラシは太さ・不透明度・硬さ・回転・密度・散布・ぼかし半径などのパラメータを自由に編集でき、不要になれば削除もできます（プリインストールのブラシ自体は編集・削除できません）。キャンバスのスライダーで変えた太さ・不透明度はブラシごとに覚えます。プリインストールのブラシも同じで、一覧のメニューから既定の値に戻せます。フォルダで分類したり、星アイコンでお気に入り登録することもできます。","help.entry19.title":"ブラシの折り返し","help.entry19.desc":"ブラシ設定で「縁取り」をONにすると「折り畳みモード」を使えます。OFFでは通常の縁取りペンと同じ描画です。ONにすると、描いたストロークの方向と曲がりをもとに、縁取りペンの線そのものが折れたり巻いたりします。波形を自動生成する機能ではありません。曲がり角ごとに、内側の輪郭から分かれてカーブし、すっと消える折り返し線が入ります。同じ向きに回り続けたときは270°ごとに控えめな折り返し線が入ります。折り畳みタイプは5種類です。「ウェーブ俯瞰」は先に描いた側、「ウェーブ煽り」は後に描いた側を手前にします。「右巻き」はストロークの進行方向の右へ、「左巻き」は左へ巻き込むように前後を決めます。基準は画面の向きではなく描いた向きです。「三日月カール」は描いたC字のカーブに沿って三日月がつながる形に整えます。「折り返し長さ」は折り返し線の長さ（ブラシサイズに連動）、「折り返し角度」はストロークのカーブへの追従の強さ（50%で自然に連動）、「折り返し線のカーブ開始位置」は素材の見かけの厚み（0%で分岐位置からすぐにカーブ）を調整します。縁取りペンの筆圧とフェード（入り抜き）は縁取りを含む全体の形だけを変え、縁取り線の太さと色の濃さは変わりません。縁取りの「重なりを維持する」をオフにすると、重なったストロークは境目を縁取らずにつながり（重なった所には折り返し線も描きません）、全体の周りだけを縁取ります。縁取りの「強弱」をオンにすると、ストロークのカーブの頂点に向かって縁取り線が太くなります（カーブの始まりと終わりは縁取り幅のまま、頂点で「頂点の縁取り幅」になるよう徐々に太くなり、ペンを離したときに反映されます）。","help.entry20.title":"レイヤー","help.entry20.desc":"1枚のキャンバスを複数の透明な「層」に分けて描画できる仕組みです。線画・色塗り・背景などを別々のレイヤーに分けて描くことで、後から色だけをやり直したり、線画を消さずに背景を差し替えたりできます。画面上では上に重なっているレイヤーほど手前に表示されます。各レイヤー行のアイコンからワンタップで削除・下のレイヤーとの結合ができ、レイヤーパネル上部のアイコンから表示中の全レイヤーを一括結合することもできます。","help.entry21.title":"ブレンドモード","help.entry21.desc":"レイヤーの合成方法を変更する機能です。トーンやカラー効果をレイヤーとして重ねる時によく使われます。\n通常：そのまま重ねます。\n乗算：下のレイヤーと掛け合わせて暗くします。影・陰影づけの定番です。\nスクリーン：明るさを足し合わせて明るくします。光の表現に向きます。\nオーバーレイ：暗い部分はより暗く、明るい部分はより明るくしてコントラストを強めます。\n加算・発光：色を単純に足し合わせます。光の効果線などに向きます。\n減算：色を差し引き、暗く沈んだ効果になります。\n比較（暗）：上下のレイヤーで暗い方の色を採用します。\n比較（明）：上下のレイヤーで明るい方の色を採用します。\n焼き込みカラー：下の色を暗く沈めながら濃く発色させます。\n覆い焼きカラー：下の色を明るく飛ばしながら発色させます。\nハードライト：オーバーレイより強くコントラストが付きます。\nソフトライト：オーバーレイより穏やかにコントラストが付きます。柔らかい陰影に向きます。\n差の絶対値：上下の色の差を表示します。色のズレ確認などに使えます。\n色相・彩度・カラー・輝度：それぞれ色相・彩度・色味・明るさだけを下のレイヤーへ反映します。\n焼き込み（リニア）：上下の色を足してから基準値を引き、強く暗くします。\n覆い焼き（リニア）：上下の色を線形に加算して明るくします。加算・発光とは別のブレンドモードで、レイヤーが半透明のときは加算・発光の方が明るくなります。\nビビッドライト：上の色に応じて焼き込みと覆い焼きを切り替え、強いコントラストを作ります。\nリニアライト：上の色を基準に明るさを線形に増減します。\nピンライト：上の色に応じて暗い側または明るい側へ置き換えます。\nハードミックス：ビビッドライトの結果を二値化し、原色的な強い色分離を作ります。\n除外：差の絶対値より穏やかな反転・差分効果です。\n除算：下の色を上の色で割り、明るい補正や色差の強調に使えます。\nブレンドモードの選択一覧では、各モードの横に、赤・黄・青・白・黒を暗い色から明るい色の上へ重ねた見本が出ます（見本の下の方は半透明で重ねた見え方です）。","help.entry22.title":"クリッピング","help.entry22.desc":"自分のすぐ下にあるレイヤーの、不透明なピクセルの範囲内にのみ描画されるようにする機能です。線画からはみ出さずに色を塗りたい時、線画レイヤーの上に色塗り用レイヤーを作ってクリッピングを有効にすると、線画の外側にうっかりはみ出して描いてしまう心配がなくなります。","help.entry23.title":"共通レイヤー","help.entry23.desc":"通常のレイヤーは1フレームごとに独立していますが、共通レイヤーは複数のフレーム・シーンで同じ内容を共有するレイヤーです。背景などフレームが変わっても動かさない要素を、フレームごとに描き直す手間なく一度描くだけで済ませられます。タイムライン上では専用のトラックとして表示されます。 通常レイヤーを共通レイヤー（複数フレームに同じ内容を表示し続けるレイヤー）へ変換できる機能です。表示中のレイヤーを複製して1枚に統合してから共通化することもできます。背景など毎フレーム同じ内容を使い回したい場合に、描き直す手間を省けます。","help.entry24.title":"レイヤーの複数選択・一括操作","help.entry24.desc":"レイヤーパネルの選択モードを使うと、複数のレイヤーをチェックボックスでまとめて選び、結合や一括削除ができます。結合は通常・自動塗り用線画・自動塗りレイヤー同士でのみ可能です（共通レイヤー・フォルダ・タイムライン素材は結合対象外）。","help.entry25.title":"レイヤーフォルダ","help.entry25.desc":"複数のレイヤーをフォルダにまとめて整理できる機能です。パーツ数が多いイラストでもレイヤーパネルが見やすくなります。クリッピングはフォルダをまたいで適用できない仕様のため、クリッピングを使う場合は同じフォルダ内でまとめておくと安全です。","help.entry26.title":"自動塗り","help.entry26.desc":"自動塗り用線画レイヤーの下に自動塗りレイヤーを作り、あらかじめ作成した「自動塗り設定」（パーツごとの色・トーンの組み合わせ）に基づいて色を自動で塗る機能です。線画を描き終えた後に一括で色を塗れるため、同じキャラクターを何度も描く手描きアニメーションで色塗りの手間を大幅に減らせます。線画を描き直した場合はタイムライン・レイヤーパネルに更新マークが表示され、自動塗りの再実行が必要なことを知らせます。 タイムライン画面の三点メニューから「自動塗り実行」を選ぶと、更新マークが付いた自動塗りレイヤーをまとめて再計算できます。線画を描き直した後に1枚ずつレイヤーパネルで実行する手間を省けます。 自動塗り設定の各パーツには、線画の色をどう扱うかの設定（指定色・塗り色と同じ・色トレス）があります。色トレス（線画馴染ませ）を選ぶと、線画の色を塗り色に合わせてHSLシフトし、線が浮かずに馴染んだ仕上がりになります。 設定が増えてくると、パーツ割り当て時の一覧が長くなって選びにくくなります。プロジェクト設定（またはレイヤーパネルのパーツ割り当てダイアログ）から、このプロジェクトで使う設定だけに絞り込んでおくと、一覧がすっきりして選びやすくなります。 「線画と塗りの隙間を埋める」を大きくすると、線の薄いふちの下まで塗り、縁取りや塗り色と同じ線画色のときに見える線画と塗りの間の隙間が小さくなります。","help.entry27.title":"グラデーション塗り（自動塗り設定）","help.entry27.desc":"自動塗り設定の各パーツには単色だけでなくグラデーションも設定できます。ドラッグで移動できる対称ハンドルにより、直感的にグラデーションの範囲・角度を調整できます。 各パーツには「指定色で縁取り」も設定できます。チェックを入れると、塗り範囲の一番外側（線画に接する部分）に指定した色・太さのラインが引かれます。縁取り色はカラーピッカーで自由に選べ、太さはスライダー・±ボタン・数値タップでの直接入力のいずれでも調整できます。設定項目のすぐ上にプレビューが表示されるため、実際に自動塗りを実行する前に色と太さを確認できます。","help.entry28.title":"シーン操作","help.entry28.desc":"タイムラインのシーンタブでは、シーンの追加・複製・削除・名前変更・並び替えができます。複数選択モードにすると複数シーンをまとめて移動・複製・削除することも可能です。","help.entry29.title":"オニオンスキン","help.entry29.desc":"現在編集中のフレームの前後のフレームを半透明で重ねて表示し、動きの繋がりを確認しながら描けるようにする機能です。パフォーマンス設定で表示する枚数（前後何枚まで）や色・透明度を調整できます。","help.entry30.title":"定規","help.entry30.desc":"直線・円・楕円・パース定規（消失点を使った透視図法用の定規）など、フリーハンドでは描きにくい正確な線を補助するための機能です。配置した定規に沿ってペン先が自動でスナップするため、定規なしでは難しい奥行きのある構図も描きやすくなります。定規はハンドルを操作して移動・回転・サイズ変更ができます。魚眼パースは、レンズの縁の円の中で横・縦の線が弧を描き、奥行きの線が中心へ集まる5点の曲線透視です。描き始めた向きに合う線に沿って描け、ハンドルで中心の移動・半径（円の右の丸）・傾き（円の上の丸）を変えられます。","help.entry31.title":"フェード","help.entry31.desc":"入り（始点）と抜き（終点）の値と距離をそれぞれ独立して設定できるブラシ機能です。入りだけ、抜きだけ、または非対称の設定にでき、線の描き始め・描き終わりの太さや不透明度を別々に調整できます。縁取りペンでは全体の形（太さ）だけが変わり、不透明度は変わりません。","help.entry32.title":"ストローク減衰","help.entry32.desc":"フェードと似ていますが、こちらは「インクが減っていく」ような表現に近く、描き続けるほど色が薄くなったりかすれたりする効果です。筆やマーカーで描き続けた時のインク切れのような質感を再現します。","help.entry33.title":"混色","help.entry33.desc":"ブラシで塗る際、ブラシの直下にすでにある色と、これから塗ろうとしている選択色を混ぜ合わせながら描画する機能です。ブラシ設定の「混色モード」で、混ぜずに塗る「デジタル」、絵の具のように混ざり拾った色を引きずって伸ばす「油彩風混色」、透明な絵の具を重ねて乾くと縁に色が溜まる「水彩風混色」を選べます。","help.entry34.title":"筆圧カーブ","help.entry34.desc":"ペン入力設定にある機能で、実際の筆圧の強さと、ブラシの太さ・不透明度への反映のされ方の関係をグラフで自由に調整できます。弱い筆圧でも太く出したい人、逆に強く押さないと太くならないようにしたい人など、手癖に合わせて描き心地を細かくカスタマイズできます。設定変更後はその場で試し書きしながら確認できます。","help.entry35.title":"トーン塗り","help.entry35.desc":"バケツツールの設定でベタ塗りからトーン塗りへ切り替えると、選択した網点・ライン柄などのトーンパターンで塗りつぶせます。ピクセルモード専用の市松模様・格子柄トーンも用意されており、ドット絵の質感を活かした塗りができます。フリルやニット、タイツなど、手描きでは手間のかかる細かい柄も簡単に描けます。オリジナルのトーンを自作して追加したり、ほかの人と共有したりすることも可能です。","help.entry36.title":"ピクセルモード","help.entry36.desc":"ブラシ・フォント・スタンプのそれぞれに用意されている設定で、ONにするとアンチエイリアスを取り除き、くっきりとしたドット絵風の輪郭で描画されます。あえて古いゲームのような質感を出したい時や、低解像度感を演出したい時に使います。配色方式は「色を指定しない」「色を指定する」「色数を指定する」「パレットから選ぶ」の4種類から選べ、ドット絵専用パレットを使った配色もできます。","help.entry37.title":"描画領域","help.entry37.desc":"書き出し範囲よりも広い範囲まで描いておける設定です。キャンバス上には書き出し範囲を示す赤枠が表示され、枠の外側にはみ出して描いた部分は書き出されませんが、パン・ズームなどのカメラワークで見せる範囲を後から調整する余地を残せます。新規プロジェクト作成時に倍率を設定します。","help.entry38.title":"キャンバスの背景色","help.entry38.desc":"プロジェクトのキャンバス背景色を設定できます。透過書き出し（透過WebM）を使う場合は背景色は書き出しに影響しませんが、作業中の見やすさのために好みの色に変更できます。","help.entry39.title":"タイムライン","help.entry39.desc":"アニメーションの時間軸を管理する画面です。フレーム（静止画1コマ）を並べてパラパラ漫画のように再生することでアニメーションになります。テキスト・画像・動画・音声の素材トラック、共通レイヤートラック、カメラキーフレームも同じタイムライン上で管理します。テキスト・画像・動画とフレームのイラストの前後関係は「重なり順」で、シーン全体、または指定したフレームの範囲ごとに並べ替えられます。項目を長押しして複数選択し、まとめて動かすこともできます。","help.entry40.title":"シーン","help.entry40.desc":"1つのプロジェクト（1本の動画）の中を、場面（カット）ごとに分割して管理する機能です。フォルダがプロジェクト単位の整理なのに対し、シーンは1本の動画の中の場面転換を表現するために使います。タイムラインのシーンタブでは、シーンの追加・複製・削除・名前変更・並び替えができます。複数選択モードにすると複数シーンをまとめて移動・複製・削除することも可能です。","help.entry41.title":"フレーム操作","help.entry41.desc":"フレーム一覧では新規追加・複製・削除に加えて、複数選択モードで複数フレームをまとめて移動・複製・削除できます。保持セル数を増やすと同じフレームを複数コマ分表示させ続けられる（いわゆる「止め」）ので、動きの少ないカットで枚数を節約できます。","help.entry42.title":"素材クリップ（テキスト・画像・動画・音声）","help.entry42.desc":"タイムラインのテキスト・画像・動画・音声トラックに配置したクリップです。クリップ本体を長押しドラッグすると表示開始位置を移動でき、左右端のハンドルをドラッグすると使用範囲（長さ）を変更できます。同じ時間に重なる素材は自動で別の列に置かれます。テキスト・画像・動画のクリップをタップすると、プレビューの下に編集パネルが開きます。文字の内容・フォント・色・縁取り、位置・拡大縮小・X軸／Y軸／Z軸回転・不透明度（プレビュー上のドラッグでも動かせます。キーフレームを追加すると動きになります）、マスク（四角・楕円・ぼかし・反転）、置く列を変えられ、複製・削除もここから行えます。音声クリップは詳細シートで音量・フェードを調整します。","help.entry43.title":"素材一覧","help.entry43.desc":"プロジェクトで使用している画像・動画・音声素材をまとめて確認できる画面です。タイムラインへ配置した素材の元ファイルがここに集約されます。","help.entry44.title":"音量調整","help.entry44.desc":"タイムラインに配置した音声クリップは、詳細シートから音量・フェードイン・フェードアウトの秒数を調整できます。効果音やBGMの音量バランスを整えたり、曲の始まり・終わりを滑らかにしたりできます。","help.entry45.title":"カメラキーフレーム","help.entry45.desc":"タイムライン上の特定の位置にカメラの位置・拡大率・回転を記録しておく機能です。キーフレーム間は自動で滑らかに補間されるため、パン（横移動）やズームイン・ズームアウトのようなカメラワークを簡単に付けられます。","help.entry46.title":"演出フィルター","help.entry46.desc":"シーンやフレームに適用できる映像効果（ぼかし・色調補正・グロー・ドット絵等）です。手描きの絵そのものを変えずに、演出として画面全体の見た目を調整したい時に使います。描画フィルターのうち、トーンカーブ（プリセットと強さ）・レベル補正・シャープ・アンシャープマスク・周辺減光（色・範囲・濃さ）・水彩境界も、複数のフレームへ同じ効果を一度にかけられるよう演出フィルターに入っています。ドット絵は配色方式（色を指定しない・色を指定する・色数を指定する・パレットから選ぶ）も選べます。色を限るときは、1色では元の色から遠い所を、使える色のうち2〜3色を規則正しく並べて（ディザリング）元の色に近づけます。輪郭の所は混ぜずにくっきり保ちます。色数を指定すると、絵の多くを占める色から選ばれます。ディザリングはスイッチでオン・オフでき、オフにすると最も近い1色で塗ります。 演出フィルターは複数重ねて適用でき、その適用順はタイムライン上での並び順に従います。フィルター一覧をドラッグで並び替えると、実際に画面へ反映される順序も変わります。 フィルムの粒状感のようなノイズをフレームごとに変化させながら適用する演出フィルターです。強度・量（ノイズが乗る密度）・粒の大きさをスライダーで調整できます。同じフレームに戻ると同じ粒状になるため、スクラブ中にちらつかず、再生すると粒が動いて見えます。 画面に降る雨を表現する演出フィルターです。降り方（本数）・速さ・粒の大きさ・風向きの角度をスライダーで調整できます。各雨粒はフレームが進むごとに一定の速度で降り続けるため、自然な雨の動きになります。","help.entry47.title":"描画フィルター","help.entry47.desc":"選択中のレイヤーに直接適用するフィルターです（演出フィルターがタイムライン全体・シーン単位に適用されるのに対し、描画フィルターはレイヤー単位）。ガウスぼかし・レンズぼかし・アニメ風加工・トーンカーブ・レベル補正・縁取り・シャープ・アンシャープマスク・周辺減光・レトロアニメ・ブラウン管・二値化・魚眼レンズ・色収差・眼鏡断層・ドット絵・質感変更フィルター・背景馴染ませ・墨溜まり・自動線画・プリズム・色反転・モザイク・ノイズ・球体陰影・水彩境界の26種類が用意されています。水彩境界は、作業レイヤーの塗った所の縁に色を溜め、内側を透けさせて、乾いた水彩のようにします（「色の境目にも付ける」で、隣り合う色の境目にも縁が付きます）。アニメ風加工は色数を減らし、隣どうしの色の差が「色の違いの閾値」以上の境目に「境界線の太さ」の線を暗い側へ引きます（線画の線は太りません）。プリズムは、レイヤーに描いた形ごとに虹の6色（赤・緑・水色・青・紫・赤）で塗ってぼかし、合成モードを「覆い焼き（リニア）」にします。暗い色の細い葉のような形を別のレイヤーに描いてから使うと、絵の上に淡い虹の光の筋が入ります（「ぼかし量」は一般的なガウスぼかしと同じ尺度）。球体陰影は、楕円の光の内側を光色、外側を影色で、描いてあるところにだけ重ねます（光の位置・大きさはキャンバス上でもドラッグできます）。縁取りは元のレイヤーを書き換えず、縁どった内容だけを新規レイヤーへ描画します。眼鏡断層フィルターは、パネルの「ペン」「バケツ」でキャンバスに塗った範囲（「消しゴム」で修正）だけに、強い眼鏡レンズのような局所的な歪みをかけられます（選択範囲・選択レイヤーがあればその範囲から始まります）。キャンバスで選択範囲を作ってあると、描画フィルターはその中だけに適用されます。ドット絵は配色方式（色を指定しない・色を指定する・色数を指定する・パレットから選ぶ）も選べます。色を限るときは、1色では元の色から遠い所を、使える色のうち2〜3色を規則正しく並べて（ディザリング）元の色に近づけます。輪郭の所は混ぜずにくっきり保ちます。色数を指定すると、絵の多くを占める色から選ばれます。ディザリングはスイッチでオン・オフでき、オフにすると最も近い1色で塗ります。大きさは「ブロックサイズを指定」（1〜100の100段階）と「ドット数を指定」（横・縦のドット数のスライダー。左端で1、右端でキャンバスの画素数）を切り替えられ、縦横比を保ったまま横と縦が一緒に変わります。どちらの指定も連動します。どちらも正方形のドットのまま半透明の縁を作りません。 自動線画では適用前の一時Vector制御点を直接編集できます。点をドラッグするとその点だけを移動します。「適用」の右の「制御点追加」を選んで線をタップすると制御点を追加、「制御点削除」を選んで点をタップすると削除できます（どちらも選んでいないときに点をタップすると、確認してから削除します）。編集した形状がそのまま適用結果になり、制御点の移動・追加・削除もフィルター編集の元に戻す・やり直すで1つずつ戻せます。 トーンカーブは曲線の何もない所をタップすると点を追加、点をドラッグで移動、長押しで削除でき、R・G・Bの色ごとのカーブはRGBのカーブの後にかかります。レベル補正もR・G・Bごとに調整でき、ガンマで中間の明るさを変えられます。縁取りは「内側への食い込み」で元の輪郭の内側まで縁を広げられ、縁取りの新規レイヤーは元のレイヤーの直下に作られます。色収差は、ずれをX（横）・Y（縦）・Z（中心から外向き）へどれだけ振り分けるかを指定できます。魚眼レンズの中心と半径は、キャンバス上の＋と円のつまみをドラッグしても変えられます。周辺減光はキャンバス全体の四隅をぼんやり暗くします（描いていない透明な所にも影がかかります）。「範囲」で四隅から中心へ向かってどこまで暗くするか、「濃さ」で四隅の暗さを調整できます。眼鏡断層は本物の度の強い眼鏡のように、レンズ越しの景色をレンズの中心へ向かって一様に縮め（負の値・近視用）、または広げ（正の値・遠視用）、レンズの縁で輪郭が段になってずれます。墨溜まりは線が「最大角度」以下で出会う所（初期値の90°では鋭角と直角：V字・交差の狭い側・T字・四角い角など）の角の内側にだけ溜まり、それより広い角には溜まりません。出会う点で線の縁から「中央の太さ」、そこから「範囲」の端に向かってまっすぐ細くなって、端で0pxになり、なめらかにとがって消えます。「中央の太さ」を大きくしても、両側の墨溜まりの端どうしを結ぶ直線より外へはふくらまず、いちばん太くても中央は平らになります。範囲の途中で線が途切れているときは、その線ではそこを終点として0pxまで細くなります（線ごとに長さが変わります）。そのときも2つの墨溜まりは角の真ん中で、どちらの線からも同じ太さで出会います（長い方の線の墨溜まりは、そこから範囲の端まで細くなります）。自動線画は下描きの線の中心をなぞって細い線にします。近くに並んだ線も間が少しでも空いていれば2本のまま描き、線の中の小さな白い点（かすれ）だけを埋めます。2本の線が近づいてくっついている所は、真ん中に1本の線を引くのではなく、下描きと同じように2本の線が徐々に近づいて合わさります。線が交差したり重なったりしている所も、下描きのとおりにそれぞれの線がそのまま続きます（交点で折れ曲がったり、重なった2本が1本に融けたりしません）。斜めに浅く交わる線もまっすぐ交差したまま続き、触れ合うだけの線（頭に沿って描いた髪の輪郭など）は、それぞれ自分の側を通る別々の線のままです。目のような点は塗りつぶした点のまま描きます。「対象ラフ線幅」より短い枝分かれは描きません。「入り抜き」はスイッチでオン・オフでき、オフにすると線の端まで同じ太さになります。背景馴染ませは、背景の光と影を合成モード「ハードライト」で重ねます（影の色は黒や灰色ではなく、背景の影の部分の色を暗くしたもの）。周りの色は「オーバーレイ」で全体に重ねて色の方向を合わせ、下からの照り返しや周りからの反射は「スクリーン」で、ネオンのような強い有色光は「加算・発光」で輪郭に入れます。「明るさ・色みを背景に合わせる」は、描いた色が背景より明るすぎたり鮮やかすぎたりする所を背景の範囲へ寄せ、暗い所・中間・明るい所をそれぞれ背景の同じ明るさの色みへ寄せます（線画の黒はそのまま）。「ぼかし具合」は色を拾う背景をぼかす量です。","help.entry48.title":"自動操作（操作記録）","help.entry48.desc":"キャンバスまたはタイムラインで行った対応操作を手順として記録し、名前を付けて繰り返し実行できる機能です。「自動操作」から新規追加して記録を開始し、停止後の確認画面で手順の並べ替え・削除をして保存します。保存した操作は名前変更・再記録・削除ができ、お気に入りだけに絞り込めます。JSONファイルとして書き出し・読み込みもできます。キャンバスだけで、かつ同じ1フレーム内に記録した操作では、実行時に現在のフレーム・指定したフレーム範囲・全フレームを選べます。タイムライン操作や複数フレームにまたがる記録では、このフレーム範囲選択は表示されません。","help.entry49.title":"レイヤーキーフレーム（パーツ単位アニメーション）","help.entry49.desc":"各レイヤーの位置・拡大縮小・回転をフレームごとに指定し、キーフレーム間を自動で補間する機能です。カメラキーフレームが画面全体を動かすのに対し、こちらは個々のレイヤーだけを動かします。自動塗りの各パーツはそれぞれ独立したレイヤーとして生成されるため、パーツ単位でのアニメーション（腕だけ動かす、口だけ開閉させる等）にそのまま使えます。各キーフレームには「等速」「ゆっくり始まる」「ゆっくり終わる」「ゆっくり始まって終わる」「弾む」というイージング（次のキーフレームへのつなぎ方）を個別に設定でき、単調な等速移動だけでなく弾むような動きも表現できます。レイヤーパネルの三点メニュー「アニメーション（キーフレーム）」から設定します。レイヤーの絵自体は変わらず、表示位置だけが変わる非破壊な変形です。この機能はタイムラインの表示（プレビュー・書き出し）にのみ影響し、キャンバスモードでの実際の作画には影響しません。","help.entry50.title":"レイヤーグループ（複数パーツをまとめて動かす）","help.entry50.desc":"複数のレイヤーをまとめて1つのキーフレームストリームで動かす機能です。例えば「腕」が肌・袖の2枚の自動塗りパーツで構成されている場合、この2枚をグループ化しておけば、1回のキーフレーム操作でまとめて動かせます。レイヤーパネルで複数選択（チェックボックス）した状態で下部バーの「グループ化」アイコンから作成します。グループの動きは各レイヤー自身のキーフレーム（設定されていれば）に重ねて適用されるため、グループ全体の動き＋個別レイヤーの微調整、という組み合わせも可能です。1つのレイヤーは同時に1つのグループにのみ所属できます。","help.entry51.title":"エンドカード","help.entry51.desc":"動画書き出し時、本編の終わりに自動で追加されるNIARIMロゴの短い動画（約5秒）です。無料版では非表示・削除ができませんが、プレミアム会員になると表示のON/OFF・長さ変更・差し替えができるようになります。","help.entry52.title":"自動保存","help.entry52.desc":"クラッシュやファイル破損が起きた時のための復元専用の保存です。描画などの変更があるたびに自動で保存され、最大3件まで古い順に上書きされます。手動保存（セーブスロット・セーブツリー）とは完全に別で管理されており、通常の保存の代わりにはなりません。アプリを異常終了した後の再起動時のみ、復元するかどうかを尋ねられます。","help.entry53.title":"セーブスロット","help.entry53.desc":"決まった数の保存枠（スロット）に、自分で保存先を選びながら保存する方式です。スロット数は設定（低品質5件・中品質10件）で決まります。上書きしたい枠を毎回自分で選ぶため、「このタイミングの状態は残しておきたい」という管理がしやすい方式です。","help.entry54.title":"セーブツリー","help.entry54.desc":"保存するたびに新しい保存地点が作られ、過去の保存地点から分岐して別の履歴を作れる（枝分かれする）保存方式です。件数の上限がなく、「あの時のバージョンに戻ってから別の展開を試したい」といった使い方に向いています。画面には保存地点が下から上へ伸びる樹形図として表示されます。","help.entry55.title":"フォルダ","help.entry55.desc":"プロジェクト（作品）をグループ化して整理する機能です。複数階層に対応しているので、同じ作品の複数話数やシリーズ物をまとめて管理する使い方もできます（例：「作品名」フォルダの中に「第1話」「第2話」…とプロジェクトを並べる）。1つの動画の中で場面を分けて作りたい場合は、フォルダではなくキャンバス画面の「シーン」機能をご利用ください。","help.entry56.title":"ゴミ箱","help.entry56.desc":"削除したプロジェクトが一時的に移動する場所です。完全に削除するまではここから元に戻せます。設定で自動削除までの日数（OFF/30日/60日/90日）を指定できます。","help.entry57.title":"共有（.niashare）","help.entry57.desc":"プロジェクトを他の人（または自分の他の端末）へ渡すための共有専用ファイル形式です。受け取った側がこのファイルを開くと、複製されて自分のプロジェクト一覧に追加されます。共有元の.niashare自体は変更されません。","help.entry58.title":"引き継ぎ（.niatra）","help.entry58.desc":"設定・素材・ブラシ・自動塗り設定・テーマ・パレット（カラーピッカー・ドット絵専用）など、アプリ全体の環境を別の端末へまとめて引き継ぐための機能です。引き継ぐ項目はチェックボックスで個別に選べるほか、制作中のプロジェクトも任意で選んで含められます（選択したプロジェクトは素材・フォントも含めて丸ごと引き継がれます）。個別のプロジェクトだけを渡したい場合は「共有（.niashare）」も使えます。","help.entry59.title":"動画書き出し（MP4・WebM・GIF・AVI）","help.entry59.desc":"作品を汎用的なMP4動画として書き出します。無料版は書き出せる長さに上限（90秒）があり、動画の最後にエンドカード（アプリロゴ）が自動で追加されます。 アルファチャンネル（背景の透明部分）を保持したまま書き出せる動画形式です。対応する再生環境でのみ透過再生されます。他のアプリの素材として重ねて使いたい場合などに向いています。 アニメーションGIFとして書き出します。自動でループ再生される形式のため、SNSへの投稿など気軽に共有したい場面に向いています。 互換性を重視したい場合はAVI（Motion JPEG）としても書き出せます。アルファチャンネル（透過）には対応せず、端末によってはアプリ内プレビューが利用できない場合があります（その場合も「共有」から外部プレイヤーで再生できます）。 無料会員はプロジェクトの長さに90秒までの上限があります（プレミアム会員は2時間）。フレーム追加・複製によって上限を超えそうな場合は、ボタンをタップした時点で注意ダイアログが表示され、実際に90秒を超えることはありません。","help.entry60.title":"書き出し画面","help.entry60.desc":"「プリセット」で「標準」「高画質」「カスタム」を選べます。「カスタム」ではFPSを調整できます。動画・画像の書き出し中は進捗状況が表示され、途中でキャンセルすることもできます。書き出しにかかる時間は端末の性能によって変わります。","help.entry61.title":"作品広場","help.entry61.desc":"アニメ・イラスト作品をYouTube動画としてコミュニティに投稿し、他のユーザーの作品を閲覧できる機能です。「新着」「ランキング」「フォロー中」「検索」「ブックマーク」の5タブで一覧を切り替えられ、作品タイトルまたは投稿者名で検索できるほか、タグ検索モードに切り替えるとタグから作品を絞り込めます。タグは投稿者以外のユーザーも自由に追加・削除でき（投稿者がロックしたタグは投稿者本人にしか外せません）、タグをタップするだけでも同じタグの作品に絞り込めます。作品カードをタップするとドラッグ・リサイズできるフローティングプレビューウィンドウが開き、他の画面を操作しながら視聴を続けられます。「詳細へ」ボタンで作品の詳細画面（投稿者・投稿日・タグ編集・ブックマーク・リポストなど）を開けます。作者名の横の「フォロー」ボタンでフォローすると、「フォロー中」タブでその作者の投稿だけを新着順にまとめて追いかけられます。フォローされると画面右上のベルアイコンの通知一覧に届きます。自分のフォロー中/フォロワー一覧を全体公開するかどうかも設定でき（既定は非公開）、公開設定にしている他のユーザーの一覧も閲覧できます。他者の作品（自分の投稿を除く）は「リポスト」ボタンで再投稿でき、フォロー中の作者が誰かの作品をリポストすると、その作品も「投稿日時」と「リポスト日時」のうちより新しい方を基準に「フォロー中」タブへ混ざって表示されます（カードに「○○さんがリポスト」と表示）。ブックマークした作品は作品広場の「ブックマーク」タブにまとめて表示されるほか、投稿者別の作品一覧画面の「ブックマーク」タブでも確認できます。自分のブックマーク一覧はユーザー全体へ公開するかどうかを設定でき（既定は非公開）、公開設定にしている他のユーザーのブックマーク一覧も閲覧できます。不適切な作品は理由を添えて通報でき、送信後にはその投稿者をブロックするか選べます。縦長の動画は「縦画面モード」でTikTok風に連続再生して視聴できます。投稿できる本数には1日あたりの上限があり、無料会員は1日1本、プレミアム会員は1日3本までです。画面右上の表示フィルターボタン（斜線の入った目のアイコン）では、見たくない作品を非表示にできます。「AI画像・AI動画使用」の作品を非表示にする設定のほか、作品タイトルだけを対象にする非表示ワードと、作品広場で作品に設定されたタグだけを対象にする非表示タグを「新規追加」から1件ずつ登録し、ペンで編集、ゴミ箱で削除できます。カンマや#は不要です。これらのフィルターは新着・ランキング・フォロー中（リポストを含む）・縦画面モード・投稿者ページ・作品詳細・ブックマークに適用されます。「AI画像・AI動画使用」は投稿時に投稿者が申告するもので、投稿後に変更できるのも投稿者本人だけです（「自分の投稿」または作品詳細画面から変更できます）。","help.entry62.title":"ウォーターマークの再編集","help.entry62.desc":"タイムラインの共通レイヤートラックに配置したウォーターマークをタップすると、角度・大きさ・不透明度・表示範囲（ループ表示）をいつでも再編集できます。登録時だけでなく、実際にプロジェクト内で使うタイミングで細かく調整できます。","help.entry63.title":"ウォーターマーク","help.entry63.desc":"書き出した動画・画像に、自分の署名やロゴを透かしとして入れられるプレミアム限定機能です。位置・大きさ・不透明度を調整できます。タイムラインの共通レイヤートラックに配置したウォーターマークをタップすると、角度・大きさ・不透明度・表示範囲（ループ表示）をいつでも再編集できます。登録時だけでなく、実際にプロジェクト内で使うタイミングで細かく調整できます。 追加するには、タイムラインの「素材を追加」メニューから「＋ウォーターマーク」を選びます。","help.entry64.title":"プレミアム","help.entry64.desc":"プレミアム会員になると、無料版で90秒までに制限されている動画の尺が最大2時間まで拡大され、動画の最後に自動追加されるエンドカード（アプリロゴ）を削除できます。広告も非表示になり、ウォーターマーク・トーンカーブ・レベル補正機能も利用できるようになります。","help.entry65.title":"ホーム画面","help.entry65.desc":"アプリを起動して最初に表示される画面で、プロジェクト・共有・作品一覧・ゴミ箱の各タブを切り替えて閲覧できます。右上の検索アイコンからプロジェクト名で絞り込み検索もできます。プロジェクトタブでは新規プロジェクト作成とフォルダ作成を画面右下の＋ボタンから選べます。","help.entry66.title":"新規プロジェクト作成","help.entry66.desc":"キャンバスサイズ・fps・長さ（秒数。あとからタイムラインでのフレーム増減にも連動）・描画領域（書き出し範囲より広く描いておける設定）・使用する自動塗り設定などをまとめて指定してからプロジェクトを作成します。","help.entry67.title":"プロジェクト詳細画面","help.entry67.desc":"プロジェクト名・サムネイル・お気に入り登録・使用する自動塗り設定の絞り込みなど、プロジェクト単位の設定をまとめて確認・編集できる画面です。セーブツリーへの入り口もここにあります。","help.entry68.title":"テーマ設定","help.entry68.desc":"アプリ全体の配色をテーマ一覧から選んだり、差し色を自由にカスタマイズしたりできる画面です。見出し・項目名用フォントと説明文用フォントが分かれており、視認性を保ちながら着せ替えを楽しめます。","help.entry69.title":"ワークスペース設定","help.entry69.desc":"左利きモード（ドッキングパネルを左右反転）、PC/DeXモードの手動切替、手のひらツールの表示条件などをまとめて設定できる画面です。使用端末や利き手に合わせて作業しやすいレイアウトに調整できます。","help.entry70.title":"ジェスチャー設定","help.entry70.desc":"2本指タップ・3本指タップ・2本指スワイプ・長押しに、Undo/Redo・フレーム移動・スポイトなどの操作を割り当てられる設定です。ペンボタン（対応スタイラス使用時）にも別途操作を割り当てられます。指を使わずワンタッチで頻用操作を呼び出したい場合に便利です。","help.entry71.title":"ペン設定","help.entry71.desc":"板タブ・液晶タブレットの筆圧カーブに加えて、ペン側面のボタン（対応スタイラス使用時）に消しゴム切替やスポイトなどの操作を割り当てられる設定画面です。","help.entry72.title":"傾き検知","help.entry72.desc":"対応スタイラスの傾き情報を使って、筆先を寝かせたときに線を太く・薄くするなど、実際の筆記具に近い描き心地を再現する設定です。パフォーマンス設定からON/OFFを切り替えられます。","help.entry73.title":"パフォーマンス設定","help.entry73.desc":"端末の性能に応じて、低品質・中品質・高品質のプリセットから選ぶか、各項目を個別に設定（カスタム）できます。保存方式・動作の軽さ・オニオンスキン・傾き検知に加えて、Undo回数やゴミ箱の自動削除などアプリの容量・動作の重さに影響する設定もここにまとまっています。","help.entry74.title":"バケツ塗り詳細設定","help.entry74.desc":"設定画面の「バケツ塗り」から、許容誤差（クリックした位置の色からどこまでの色差を同一領域とみなすか）・拡張px（塗った範囲を境界の外側へ広げて線画との隙間を埋める量）・線の下まで潜る（拡張分を線画の上から上書きせず、線の見た目を保ったまま背後へ塗り色を合成する）を調整できます。線画に細かい隙間がある場合や、塗り残しが気になる場合に調整すると仕上がりが安定します。","help.entry75.title":"Undo（元に戻す）回数設定","help.entry75.desc":"パフォーマンス設定から、Undoで遡れる操作回数を調整できます。回数を増やすほど安心して試行錯誤できますが、メモリ使用量も増えるため、低スペック端末では回数を抑えると動作が軽くなります。","help.entry76.title":"フォントの読み込み","help.entry76.desc":"端末内のフォントファイルを直接読み込んで使えるようにする機能です。設定画面のフォント管理「読み込み」タブから追加できます。配信されていない自作フォントや購入した商用フォントを使いたい場合に利用します。","help.entry77.title":"容量削減","help.entry77.desc":"端末容量に対するNIARIMの使用量と、NIARIM内部（プロジェクト・素材・書き出し済みファイル・自作ブラシ/トーン/スタンプ/フォント・キャッシュ・ゴミ箱）の内訳を円グラフで確認できます。キャッシュの削除・未使用素材の一括削除（全プロジェクト）・ゴミ箱を空にする・プロジェクトの整理・全データ削除（初期化）が行えます。","help.entry78.title":"ホーム画面ウィジェット","help.entry78.desc":"スマホのホーム画面に置ける3種類のウィジェット（作品の1コマ表示／作品をつくる／作品広場）の設定です。ウィジェット自体の追加はホーム画面の長押しから行います（アプリ内には追加ボタンはありません）。「作品を選ぶ」では、プロジェクト一覧タブと同じ並び替え・表示方法・検索・お気に入り絞り込みを使って作品を選び、再生コントロール付きのプレビューで表示するフレームまで選べます。「作品をつくる」「作品広場」ウィジェットは、背景色をアプリのテーマに合わせるか個別に指定するかを選べます。","help.lead":"アプリ内のヘルプと同じ79項目を、同じ見出しと説明文で掲載しています。検索やカテゴリから内容を探せます。"},"en":{"help.category.tool":"Tools","help.category.brush":"Brush","help.category.penInput":"Pen Input","help.category.drawing":"Drawing","help.category.layer":"Layers","help.category.animation":"Animation","help.category.save":"Save","help.category.projectManagement":"Project Management","help.category.export":"Export","help.category.community":"Community","help.category.premium":"Premium","help.category.settings":"Settings","help.entry0.title":"Basic controls (tap, long-press, swipe)","help.entry0.desc":"A single tap on a toolbar icon switches to that tool. Long-press the same icon, or swipe up on it, to open its detailed settings. Behind that long-press or swipe you will find: brush / screentone / stamp / lasso fill for the pen, solid vs. screentone for the bucket, rectangle / lasso / magic wand for the selection tool, blur vs. mosaic for the finger tool, and the registered tool list for the quick-swap tool. Double-tapping an icon shows a short description at the bottom of the screen.\\nOn the canvas, pinch with two fingers to zoom, drag with two fingers to pan, tap with two fingers to undo and with three fingers to redo. Double-tap the left or right edge of the screen to move to the previous or next frame.\\nWith a mouse or pen tablet connected, the wheel zooms and dragging with the middle button pans.","help.entry1.title":"Pen Tool","help.entry1.desc":"The basic tool for drawing lines on the canvas. Long-press to change the brush type, size, and color (double-tap shows a quick summary). It supports pressure and tilt from stylus/tablet devices, and adjusting the pressure curve under Settings > Pen Input lets you finely customize how pressure translates into size and opacity changes. Switching pen sub-tools lets you apply screentones or place stamps from the same pen tool.","help.entry2.title":"Eraser Tool","help.entry2.desc":"The counterpart to the pen tool, used to erase what you've drawn. Like a brush, you can adjust its size and opacity, and brush settings such as fade and stroke decay apply to it as well. Rather than \"adding\" to the transparent parts of a layer, it \"removes\" existing drawing, so the layer below becomes visible through it.","help.entry3.title":"Bucket Tool","help.entry3.desc":"Fills an enclosed area all at once. Tap inside an area enclosed by line art and the whole area is filled with the selected color (or screentone). If there are gaps in the line art, the fill can spread into unintended areas, so it helps to make sure the line art is properly closed before using it. You can switch between flat fill and screentone fill in the settings. Detailed settings (tolerance, expand px, fill under lines) can be adjusted from the \"Bucket Fill\" section in Settings.","help.entry4.title":"Lasso Fill","help.entry4.desc":"Trace with your finger to form a polygonal area, then fill the inside all at once. Unlike the bucket tool, you can define the area yourself even where the line art isn't closed, making it well suited for complex shapes or areas with gaps in the lines. With \"Fill enclosed area\" on, every area closed by lines inside your lasso is filled at once, however many there are, as with the bucket (the space between the lasso and the drawing is left as it is).","help.entry5.title":"Eyedropper Tool","help.entry5.desc":"Picks up the color at the tapped position and sets it as the drawing color. It samples the composited look of all layers as actually displayed on screen, so it accurately picks up the \"color as seen\" even where multiple layers overlap.","help.entry6.title":"Select Tool","help.entry6.desc":"Selects part of the canvas so you can move, rotate, or scale just that area. Long-press to choose from three selection methods: \"Rectangle Select,\" \"Lasso Select\" (freeform enclosure), or \"Auto Select\" (magic wand — automatically groups areas of similar color). While a selection is active, an outline marks the selected area on the canvas, and the same area stays fixed across all frames and layers until you deselect. In Lasso Select, turning on \"Snap to lines\" looks at the areas the line art divides the canvas into, the way a bucket fill does, and selects only the areas lying mostly inside your lasso. The edge of the selection runs exactly along the outer edge of the line art: the lines around those areas and inside them are selected with them (a line running on out of the outline is cut where it leaves it). Filled colors count as areas of their own, as for a bucket fill, so a layer with fills and lines is selected along the shape of the drawing too. Breaks in a line up to the \"Gap tolerance\" width are treated as closed. If there is no line art inside the lasso, the lasso is selected as drawn. The lines are taken from the selection reference (\"Working layer only\" / \"All visible layers\").","help.entry7.title":"Finger Tool (Warp Tool)","help.entry7.desc":"Warps pixels by pushing them in the direction you drag your finger, like smearing wet paint with a finger. It's used less for fine corrections and more when you want to organically warp lines you've already drawn to give them more expression.","help.entry8.title":"Shape Tool","help.entry8.desc":"Draws precise shapes such as lines, rectangles, and circles with a single gesture. Dragging from the start point to the end point previews the shape live, and it's finalized when you lift your finger. Handy when you need straight lines or perfect circles that are hard to draw freehand.","help.entry9.title":"Text Tool","help.entry9.desc":"Places text on the canvas. You can choose the font, size, color, and vertical/horizontal writing direction. Vertical writing supports automatic rotation of half-width alphanumerics, tate-chu-yoko (keeping numbers horizontal within vertical text), and ruby (furigana). Placed text is baked in as pixels when exported as well. A screen where you can add, search, and remove fonts available in the text tool. Additional free fonts beyond the bundled defaults are downloaded on demand from here, in order to keep the initial install size down.","help.entry10.title":"Quick tool management","help.entry10.desc":"Register a set of frequently used tools to cycle through with a single tap. Open the management popup with a long press or an upward swipe to edit the registered tools and their order.","help.entry11.title":"Quick Tool","help.entry11.desc":"Register combinations of brushes and tools you use often, and cycle through them with a single button tap. Long-press or swipe up on the ↺ button on the canvas to open a management popup where you can add, reorder, and remove entries. Drag to change their order.","help.entry12.title":"Stamp tool","help.entry12.desc":"Places a pre-registered image onto the canvas like a brush, so speed lines, background patterns, and small props can be reused without redrawing them. In pixel mode, stamps use the same Pixel Art processing as the pixel-art filter, preserving hard transparency edges while pixelizing and reducing colors. Mosaic is a separate effect and is not used for stamp pixel mode. The stamp panel also lets you adjust rotation and size.","help.entry13.title":"Pen","help.entry13.desc":"Long-pressing the pen tool switches it from regular drawing to the screentone-fill or stamp-placement sub-tools. Lets you move between several tasks from the same pen without constantly switching tools.","help.entry14.title":"Transforming a selection","help.entry14.desc":"A region enclosed with the select tool can be transformed by picking Move, Scale, or Rotate from the buttons at the bottom left of the canvas and then dragging inside the selection. Handy for repositioning a mistakenly drawn part, or enlarging just one area to emphasize it. Tapping Select All on the same bar selects the entire current layer, so you can move, rotate, and scale a whole layer the same way (the separate Transform tool has been merged into this). To warp more freely by dragging individual grid points, use Free transform or Mesh warp on the same bar.","help.entry15.title":"Free Transform / Mesh Warp","help.entry15.desc":"A transform tool for the whole layer, opened from the edit/settings menu in the top-right of the canvas. Unlike transforming a selection, no selection is needed — drag corners or individual grid points with your finger for a freeform result. The control panel's density slider can subdivide the mesh up to 10×10, and pinching two different points with two fingers at once gives an intuitive way to rotate or scale.","help.entry16.title":"Color picker","help.entry16.desc":"A color picker that lets you switch between HSV and RGB on one screen. The palette feature lets you save and recall the color set you are using. Palettes can also be shared with other devices via file export or QR code.","help.entry17.title":"Favorite brushes","help.entry17.desc":"Tap the star icon on a brush in the brush list to favorite or unfavorite it (the same interaction used for favorites throughout the app — autofill settings, stamps, fonts, draw filters, and more). The star icon at the top of the list also lets you filter down to favorites only. Favorited brushes can’t be deleted by accident.","help.entry18.title":"Custom Brushes","help.entry18.desc":"Long-press a pre-installed brush in the brush list and choose “Duplicate” to create your own custom brush based on it. Duplicated brushes can be freely edited — thickness, opacity, hardness, rotation, density, scatter, blur radius, and more — and deleted once you no longer need them (the pre-installed brushes themselves can’t be edited or deleted). The thickness and opacity you set with the canvas sliders are remembered for each brush, including pre-installed ones, which you can return to their default values from the brush’s menu in the list. You can also sort them into folders and mark favorites with the star icon.","help.entry19.title":"Brush folds","help.entry19.desc":"Turn on Outline in the brush settings to use Fold mode. With it off, the brush draws exactly like the normal outline pen. With it on, the outline pen's own line folds and curls along the direction and bends of the stroke you draw; it does not generate waves automatically. At each bend, a fold line branches from the inner edge, curves and fades out. A stroke that keeps turning the same way gets a subtler fold line every 270°. There are five fold types. Wave (top view) brings the earlier part of the stroke forward, and Wave (low angle) the later part. Right curl decides front and back as if rolling to the right of the drawing direction, and Left curl to the left; they follow the stroke, not the screen. Crescent curl follows the C-shaped curves you draw to form connected crescents. Fold length sets the length of the fold line (it scales with the brush size), Fold angle sets how strongly it follows the stroke's curve (50% follows it naturally), and Fold line curve start sets how thick the material looks (at 0% it curves right from where it branches). On the outline pen, pressure and Fade (entry and exit) change only the overall shape, outline included; the outline keeps its width and the color never gets lighter. Turn off Keep overlaps under Outline to merge overlapping strokes: their joins are not outlined and no fold lines are drawn where they overlap, only the outside of the combined shape is outlined. Turn on Weight variation under Outline to thicken the outline toward the apex of each curve: it keeps the outline width where the curve begins and ends and gradually reaches the Outline width at the apex (applied when you lift the pen).","help.entry20.title":"Layers","help.entry20.desc":"A system that lets you draw on a single canvas across multiple transparent “layers.” By drawing line art, coloring, and backgrounds on separate layers, you can redo just the coloring later or swap out the background without erasing the line art. Layers stacked higher appear in front on screen. Each layer row has one-tap buttons to delete it or merge it with the layer below, and a button at the top of the layer panel lets you merge all visible layers at once.","help.entry21.title":"Blend Mode","help.entry21.desc":"Changes how a layer is composited with the layers below it. Often used when layering screentones or color effects.\nNormal: Layers as-is.\nMultiply: Darkens by multiplying with the layer below. The standard choice for shadows.\nScreen: Brightens by adding light. Good for glow effects.\nOverlay: Darkens dark areas and brightens light areas, increasing contrast.\nAddition (Glow): Simply adds colors together. Good for light streak effects.\nSubtract: Subtracts colors, producing a dark, sunken look.\nDarken: Keeps whichever color is darker between the two layers.\nLighten: Keeps whichever color is lighter between the two layers.\nColor Burn: Darkens and saturates the color below.\nColor Dodge: Brightens and saturates the color below.\nHard Light: A stronger version of Overlay contrast.\nSoft Light: A gentler version of Overlay contrast. Good for soft shading.\nDifference: Shows the difference between the two colors. Useful for checking color misalignment.\nHue / Saturation / Color / Luminosity: Applies only that one property (hue, saturation, color, or brightness) from this layer onto the one below.\nLinear Burn: Adds the two colors then subtracts the baseline, producing a strong darkening effect.\nLinear Dodge: Linearly adds the two colors to brighten. This is a separate blend mode from Addition (Glow): when the layer is semi-transparent, Addition (Glow) comes out brighter.\nVivid Light: Switches between burn and dodge based on the upper color for very strong contrast.\nLinear Light: Linearly raises or lowers brightness based on the upper color.\nPin Light: Replaces toward the darker or lighter side depending on the upper color.\nHard Mix: Thresholds the Vivid Light result for hard, primary-color separation.\nExclusion: A softer inversion/difference effect than Difference.\nDivide: Divides the lower color by the upper color, useful for bright correction and emphasizing color differences.\nIn the blend mode list, each mode shows a sample of red, yellow, blue, white and black laid over colors from dark to light (the lower part of the sample shows them half transparent).","help.entry22.title":"Clipping","help.entry22.desc":"Restricts drawing to only the opaque pixels of the layer directly below. When you want to color without going outside the line art, enabling clipping on a coloring layer placed above a line art layer removes the risk of accidentally drawing outside the lines.","help.entry23.title":"Common Layer","help.entry23.desc":"Ordinary layers are independent per frame, but a common layer shares the same content across multiple frames and scenes. Elements that don't move between frames, like backgrounds, can be drawn once instead of redrawn for every frame. It's shown as a dedicated track on the timeline. Converts a normal layer into a common layer (one that keeps showing the same content across multiple frames). You can also merge the currently visible layers into one before converting. Saves you redrawing something like a background that stays the same every frame.","help.entry24.title":"Multi-selecting and bulk layer actions","help.entry24.desc":"Selection mode in the layer panel lets you check off several layers at once to merge or bulk-delete them. Merging only works between normal, autofill-lineart, and autofill layers (common layers, folders, and timeline materials can't be merged).","help.entry25.title":"Layer folders","help.entry25.desc":"Lets you organize several layers into a folder. Keeps the layer panel manageable even in illustrations with many parts. Clipping can't cross folder boundaries, so if you use clipping, keep the relevant layers in the same folder.","help.entry26.title":"Auto Fill","help.entry26.desc":"Creates an auto-fill layer beneath the auto-fill line art layer and automatically colors it based on a pre-made \"autofill setting\" (a combination of colors and screentones per part). Since you can color everything at once after finishing the line art, it greatly reduces coloring effort in hand-drawn animation where the same character is drawn repeatedly. If you redraw the line art, an update mark appears on the timeline and layer panel to let you know the auto-fill needs to be reapplied. Choosing \"Run autofill\" from the timeline screen’s three-dot menu recalculates every autofill layer flagged with the update mark at once. Saves you from running it one layer at a time in the layer panel after redrawing lineart. Each part in an autofill setting has a setting for how to handle the lineart color — a specified color, matching the fill color, or color tracing. Choosing color tracing shifts the lineart color’s HSL to match the fill color, so the line doesn’t stand out and blends in naturally. As settings pile up, the list shown when assigning parts gets long and harder to browse. From project settings (or the part-assignment dialog in the layer panel), you can narrow it down to only the settings used in this project, keeping the list tidy and easy to pick from. Raising 「Close the gap between lines and fill」 fills further under the soft edge of the lines, narrowing the gap between line art and fill that shows with an outline or a line color matching the fill.","help.entry27.title":"Gradient fill (autofill settings)","help.entry27.desc":"Each part in an autofill setting can use a gradient instead of a solid color. Symmetric handles you can drag let you intuitively adjust the gradient’s extent and angle. Each part can also enable \"Outline with specified color\". When checked, a line of the chosen color and width is drawn around the very outer edge of the filled area (right up against the lineart). The outline color can be freely chosen from the color picker, and the width can be adjusted via the slider, the ± buttons, or by tapping the number to type it directly. A preview appears just above the settings, so you can check the color and width before actually running autofill.","help.entry28.title":"Scene operations","help.entry28.desc":"The timeline's scene tab lets you add, duplicate, delete, rename, and reorder scenes. Multi-select mode lets you move, duplicate, or delete several scenes at once.","help.entry29.title":"Onion Skin","help.entry29.desc":"Overlays the frames before and after the one you're currently editing at partial transparency, so you can draw while checking how the motion connects. You can adjust how many frames are shown (before and after) and their color and opacity in the performance settings.","help.entry30.title":"Ruler","help.entry30.desc":"A guide for drawing precise lines that are hard to achieve freehand, including straight, circle, ellipse, and perspective rulers (using vanishing points for perspective drawing). The pen tip automatically snaps to the placed ruler, making even compositions with challenging depth easier to draw than without a ruler. Rulers can be moved, rotated, and resized using their handles. The fisheye perspective ruler is a curvilinear (five-point) perspective: horizontal and vertical lines bend into arcs within the lens circle and depth lines meet at the center. Each stroke follows the line that matches the direction you start drawing in; drag the handles to move the center, change the radius (the dot on the right of the circle) and tilt it (the dot at the top).","help.entry31.title":"Fade","help.entry31.desc":"A brush feature that lets you set the value and distance of the entry (stroke start) and exit (stroke end) independently. You can taper only the start, only the end, or use asymmetric settings to control thickness and opacity separately at each endpoint. On the outline pen, only the overall shape (thickness) changes, never the opacity.","help.entry32.title":"Stroke Decay","help.entry32.desc":"Similar to fade, but closer to the effect of \"ink running out\" — the color fades or gets patchy the longer you keep drawing. It reproduces the texture of a brush or marker running dry as you keep using it.","help.entry33.title":"Color Mixing","help.entry33.desc":"While painting with a brush, blends the color already under the brush with the color you're about to apply. In the brush settings' mixing mode, choose Digital to paint without mixing, Oil-style mixing to mix like paint and drag the picked-up color along, or Watercolor-style mixing to layer transparent washes that gather color at their edges as they dry.","help.entry34.title":"Pressure Curve","help.entry34.desc":"A feature in the pen input settings that lets you freely adjust, via a graph, the relationship between actual pen pressure and how it affects brush size and opacity. Whether you want thick lines even with light pressure, or the opposite — needing firm pressure to get thick lines — you can finely customize the feel to match your habits. You can try drawing right there to check the effect after changing the settings.","help.entry35.title":"Screentone fill","help.entry35.desc":"Switching the bucket tool's setting from solid fill to screentone fill lets you fill with a chosen halftone or line-pattern screentone. Pixel-mode-only checker and grid patterns are also available, for fills that fit a pixel-art texture. Great for frills, knitwear, tights, and other fine patterns that are tedious to draw by hand. You can also create and add your own custom screentones, or share them with other users.","help.entry36.title":"Pixel mode","help.entry36.desc":"A setting available on brushes, fonts, and stamps individually. Turning it on strips anti-aliasing for crisp, pixel-art-style edges. Use it when you want a deliberately old-game feel or a low-resolution look. You can choose from four color modes — no color limit, specify colors, specify color count, or choose from a palette — including a dedicated pixel-art palette.","help.entry37.title":"Drawing area","help.entry37.desc":"Lets you draw beyond the export bounds. A red frame on the canvas marks the export area — anything drawn outside it isn't exported, but it leaves room to adjust what's shown later with camera moves like panning and zooming. Set the scale when creating a new project.","help.entry38.title":"Canvas background color","help.entry38.desc":"Lets you set the project's canvas background color. It has no effect on transparent exports (transparent WebM), but you can change it to whatever's easiest to work against.","help.entry39.title":"Timeline","help.entry39.desc":"The screen for managing the time axis of your animation. Arranging frames (individual still images) and playing them back like a flipbook creates the animation. Text, image, video and audio material tracks, common layer tracks and camera keyframes are all managed on the same timeline. Which of the texts, images, videos and the frame's drawing is in front is set in \"Stacking order\", for the whole scene or for a range of frames. You can also long-press an item to select several and move them together.","help.entry40.title":"Scene","help.entry40.desc":"Splits the inside of a single project (one video) into scenes (cuts) to manage them separately. While folders organize things at the project level, scenes represent scene changes within a single video. In the timeline’s scene tab you can add, duplicate, delete, rename, and reorder scenes. Switching to multi-select mode lets you move, duplicate, or delete multiple scenes at once.","help.entry41.title":"Frame operations","help.entry41.desc":"In the frame list, you can add, duplicate, and delete frames, and in multi-select mode move, duplicate, or delete several frames at once. Increasing the hold count keeps a single frame displayed across several cells (a \"hold\"), saving you drawing time on cuts with little motion.","help.entry42.title":"Material clips (text / image / video / audio)","help.entry42.desc":"Clips placed on the timeline's text, image, video and audio tracks. Long-press-drag a clip's body to move its start position, or drag the handles at either end to change how much of it is used. Materials shown at the same time go on rows of their own automatically. Tapping a text, image or video clip opens its edit panel below the preview: the text, font, colour and outline; the position, scale, X/Y/Z-axis rotation and opacity (you can also drag it on the preview, and adding keyframes makes it move); its mask (rectangle or ellipse, feathered, inverted); and the row it sits on. It can be duplicated or deleted there too. An audio clip's volume and fades are set in its detail sheet.","help.entry43.title":"Materials list","help.entry43.desc":"A screen that gathers the image, video, and audio materials used in a project. It collects the source files for anything placed on the timeline.","help.entry44.title":"Volume","help.entry44.desc":"An audio clip placed on the timeline can have its volume, fade-in, and fade-out durations adjusted from its detail sheet. Use it to balance sound effect and BGM volume, or smooth out a track's start and end.","help.entry45.title":"Camera Keyframe","help.entry45.desc":"Records the camera's position, zoom level, and rotation at a specific point on the timeline. Since the values are automatically interpolated smoothly between keyframes, you can easily add camera work such as panning or zooming in/out.","help.entry46.title":"Effect Filter","help.entry46.desc":"A visual effect (blur, color correction, glow, pixel art, etc.) you can apply to a scene or frame. Use it when you want to adjust the overall look of the screen as a directorial touch, without changing the hand-drawn artwork itself. Of the drawing filters, Tone Curve (a preset and its strength), Levels, Sharpen, Unsharp Mask, Vignette (color, range and density) and Watercolor Edge are effect filters too, so the same effect can be applied to many frames at once. Pixel art also lets you choose a color mode (no limit, specify colors, specify color count, or choose from a palette). When colors are limited, areas no single allowed color comes close to are made of two or three allowed colors in a regular pattern (dithering) that stays in place from frame to frame; edges stay crisp. Dithering can be switched off, to fill each dot with the nearest single color. Multiple effect filters can be stacked, and they're applied in the order they appear on the timeline. Dragging to reorder the filter list also changes the order they're actually applied on screen. An effect filter that applies film-grain-like noise, changing it frame by frame. Strength, amount (how dense the noise is), and grain size can all be adjusted with sliders. Returning to the same frame reproduces the same grain (no flicker while scrubbing), while playback makes the grain appear to move. An effect filter that renders rain falling across the screen. Intensity (drop count), speed, drop size, and wind angle can all be adjusted with sliders. Each drop keeps falling at a steady speed as the frame advances, giving natural-looking rain motion.","help.entry47.title":"Draw filters","help.entry47.desc":"Filters applied directly to the selected layer (as opposed to effect filters, which apply across the whole timeline or a scene, draw filters work per layer). The 26 included filters are Gaussian Blur, Lens Blur, Anime Style, Tone Curve, Levels, Outline, Sharpen, Unsharp Mask, Vignette, Retro Anime, CRT, Threshold, Fisheye Lens, Chromatic Aberration, Lens Distortion, Pixel Art, Texture, Background Blend, Ink Pool, Auto Line Art, Prism, Invert colors, Mosaic, Noise, Sphere Shading, and Watercolor Edge. Watercolor Edge gathers color along the edges of what is painted on the working layer and makes the inside sheer, like dried watercolor (with \"Also at color borders\", borders between neighboring colors get an edge too). Anime Style reduces the colors and draws a line of the \"Border width\" on the darker side of every border where neighboring colors differ by at least the \"Color difference threshold\" (line art doesn't get thicker). Prism paints each shape on the layer with the six rainbow colors (red, green, cyan, blue, purple, red), blurs it and sets the layer to Linear Dodge. Draw small, slender leaf-like shapes in a dark color on their own layer first, and you get soft rainbow streaks of light over your picture (Blur amount is measured like an ordinary Gaussian blur). Sphere Shading lays a light color inside an elliptical light and a shadow color outside it, only where something is drawn (the light can also be dragged on the canvas). Outline does not rewrite the original layer — it draws just the outlined result onto a new layer. Lens Distortion applies a localized warp, like looking through a strong eyeglass lens, only to the area painted on the canvas with the panel's \"Pen\" and \"Bucket\" (corrected with \"Eraser\"; it starts from the selection or Selection layer if there is one). When the canvas has a selection, drawing filters apply only inside it. Pixel Art also lets you choose a color mode (no limit, specify colors, specify color count, or choose from a palette). When colors are limited, areas no single allowed color comes close to are made of two or three allowed colors laid out in a regular pattern (dithering) that looks closer to the original; edges stay crisp. With a color count, the colors are taken from what most of the picture is made of. Dithering can be switched off, to fill each dot with the nearest single color. Its size can be set with the block size (100 steps, 1 to 100) or with sliders for the dots across and down (1 at the left end, the canvas size at the right); moving one moves the other, keeping the picture’s proportions, and the two ways of setting it stay in step. Either way the dots stay square, with no semi-transparent edge. Auto Line Art lets you edit temporary vector control points before applying the filter. Drag a point to move only that point. Choose \"Add control point\" next to Apply and tap a line to add a point, or choose \"Delete control point\" and tap a point to delete it (with neither chosen, tapping a point asks before deleting it). The edited geometry is used directly for the applied result, and moving, adding or deleting points can be undone and redone one at a time with the filter editor's Undo and Redo. On the Tone Curve, tap an empty spot to add a point, drag a point to move it and long-press it to delete it; the R, G and B curves apply after the RGB curve. Levels can also be set for R, G and B on their own, and Gamma changes the midtones. The Outline's \"Reach inside\" widens the edge into the original shape, and the outline's new layer is placed right below the original layer. Chromatic Aberration lets you share the shift between X (sideways), Y (up and down) and Z (outward from the centre). The Fisheye's centre and radius can also be dragged on the canvas, with the + and the knob on the circle. Vignette softly darkens the four corners of the whole canvas (transparent, undrawn areas get the shadow too). \"Range\" sets how far in from the corners it reaches, and \"Density\" how dark the corners get. Lens Distortion works like real strong glasses: what is seen through the lens shrinks evenly towards the lens centre (negative values, for short sight) or grows (positive values, for long sight), and the outline steps out of line at the lens rim. Ink Pooling collects only inside corners where lines meet at the \"Max angle\" or less (at the default 90°, acute and right angles: a V, the narrow side of a crossing, a T-junction, a square corner), never in wider ones: at the meeting point it is the \"Center width\" beyond the line's edge, and it thins in a straight slope to nothing, a smooth point, at the end of the \"Range\" (however large the \"Center width\", it never bulges past the straight line between the two pools' ends: at its widest the middle is flat); where a line ends sooner, the pool along that line thins to nothing where the line ends, so each line can have its own length, and the two pools still meet in the middle of the corner, as thick from either line (the longer line's pool thins on from there to the end of the range). Auto line art traces the centre of the rough lines and draws them thin. Lines running close together stay separate lines as long as any gap shows between them; only tiny specks of paper inside a stroke are filled. Where two lines run into each other, they come together gradually as in the rough, rather than turning into one line down the middle. Where lines cross or lie over each other, each line carries on as drawn in the rough (it does not bend into the crossing, and two overlapping lines do not melt into one). Lines crossing at a shallow slant carry straight on through the crossing, and lines that only touch (such as a hair outline drawn along the head) stay separate lines, each on its own side. Dots such as eyes stay filled dots. Branches shorter than the \"Rough line width\" are left out. \"Taper the ends\" can be switched on or off; when off, lines keep the same width right to their ends. Background Blend lays the background’s light and shadow over the picture in the \"Hard Light\" blend mode (the shadow colour is not black or grey but the colour of the background’s own shadows, darkened). The surroundings’ colour goes over the whole picture in \"Overlay\" to set its overall colour, light bouncing up from below and reflected from around goes on in \"Screen\", and a strong coloured light such as neon glows along the outline in \"Addition (Glow)\". \"Match the background’s tones\" brings colours brighter or more vivid than the background back into its range, and gives the dark, middle and light tones the colour cast of the background’s tones of the same brightness (black line art stays as it is). \"Blur amount\" is how much the background is blurred before its colours are taken.","help.entry48.title":"Custom automations (action recording)","help.entry48.desc":"Record supported actions on the canvas or timeline as a named sequence that you can run again. Add a new item from Automations to start recording, then reorder or remove steps on the review screen before saving. You can rename, re-record, delete, filter to favorites, export, and import saved automations as JSON files. For a canvas-only automation recorded entirely within one frame, you can run it on the current frame, a specified frame range, or all frames. Frame-range choices are not shown for timeline automations or recordings that span multiple frames.","help.entry49.title":"Layer keyframes (per-part animation)","help.entry49.desc":"Set each layer's position, scale, and rotation per frame, with the keyframes interpolated automatically. Where camera keyframes move the whole screen, this moves an individual layer only. Since each autofill part is generated as its own separate layer, this works directly for per-part animation — moving just an arm, opening and closing just a mouth, and so on. Each keyframe can also be given its own easing — Linear, Ease in, Ease out, Ease in and out, or Bounce — controlling how it transitions into the next keyframe, so motion doesn't have to stay at a flat, constant speed. Set it up from the \"Animation (keyframes)\" entry in each layer's three-dot menu in the layer panel. The layer's artwork itself doesn't change — it's a non-destructive transform of where it's displayed. This only affects the timeline's display (preview / export) and has no effect on actual drawing in canvas mode.","help.entry50.title":"Layer groups (moving multiple parts together)","help.entry50.desc":"Moves several layers together with a single keyframe stream. For example, if an \"arm\" is made up of two autofill parts — skin and sleeve — grouping them lets you move both with one keyframe operation. Create a group by multi-selecting layers (checkboxes) in the layer panel and tapping the \"Group\" icon in the bottom bar. A group's motion is layered on top of each member layer's own keyframes (if set), so you can combine the group's overall movement with per-layer fine adjustments. A layer can belong to only one group at a time.","help.entry51.title":"End Card (End Logo)","help.entry51.desc":"A short video (about 5 seconds) with the NIARIM logo, automatically added to the end of the main content when exporting a video. The free version cannot hide or remove it, but Premium members can turn it on/off, change its length, or replace it.","help.entry52.title":"Auto Save","help.entry52.desc":"A save dedicated to recovery in case of a crash or file corruption. It saves automatically every time there's a change, such as drawing, and overwrites the oldest of up to 3 saves. It's managed completely separately from manual saves (save slots and the save tree) and is not a substitute for regular saving. You're only asked whether to restore it when relaunching the app after an abnormal exit.","help.entry53.title":"Save Slot","help.entry53.desc":"A method of saving into a fixed number of save slots, where you choose which slot to save to each time. The number of slots is determined by the settings (5 for low quality, 10 for medium quality). Since you choose which slot to overwrite every time, it's an easy way to manage keeping a particular moment's state.","help.entry54.title":"Save Tree","help.entry54.desc":"A save method where a new save point is created every time you save, and you can branch off from a past save point to create a different history. There's no limit on the number of saves, making it well suited for use cases like \"I want to go back to that version and try a different direction.\" On screen, save points are shown as a tree diagram growing from bottom to top.","help.entry55.title":"Folder","help.entry55.desc":"A feature for grouping and organizing your projects (works). It supports multiple levels of nesting, so you can also use it to manage multiple episodes or a series of the same work together (for example, arranging projects for \"Episode 1,\" \"Episode 2,\" and so on inside a folder named after the work). If you want to divide a single video into separate scenes, use the \"Scene\" feature on the canvas screen instead of folders.","help.entry56.title":"Trash","help.entry56.desc":"The place where deleted projects are temporarily moved. You can restore them from here until they're permanently deleted. You can set the number of days until automatic deletion (Off/30/60/90 days) in the settings.","help.entry57.title":"Share (.niashare)","help.entry57.desc":"A dedicated file format for handing a project to someone else (or to another device of your own). When the recipient opens this file, it's duplicated and added to their own project list. The original .niashare file itself is not changed.","help.entry58.title":"Transfer (.niatra)","help.entry58.desc":"A feature for transferring your entire app environment — settings, materials, brushes, autofill settings, theme, palettes (color picker and pixel-art), and more — to another device all at once. You can choose individual items to transfer with checkboxes, and optionally include in-progress projects too (selected projects are transferred whole, including their materials and fonts). If you just want to hand over a single project, you can also use \"Share (.niashare)\".","help.entry59.title":"Video Export (MP4, WebM, GIF, AVI)","help.entry59.desc":"Exports your work as a standard MP4 video. The free version has a length limit (90 seconds) and automatically adds an end card (app logo) at the end of the video. A video format that can be exported while keeping the alpha channel (the transparent parts of the background). Transparent playback only works in compatible playback environments. Good for layering as material in other apps. Exports as an animated GIF. Since it loops automatically, it works well for casual sharing on social media. If compatibility matters most, you can also export as AVI (Motion JPEG). It doesn't support the alpha channel (transparency), and in-app preview may not work on every device (you can still play it in an external player via Share in that case). Free accounts are capped at a 90-second project length (Premium accounts get 2 hours). If adding or duplicating frames would push you past the limit, a warning dialog appears the moment you tap the button, so you never actually go over 90 seconds.","help.entry60.title":"Export screen","help.entry60.desc":"Choose “Standard”, “High Quality”, or “Custom” under “Preset”. With “Custom”, you can adjust the FPS. Shows progress while exporting a video or image, and lets you cancel partway through. How long it takes depends on your device's performance.","help.entry61.title":"Work Plaza","help.entry61.desc":"Post your animations and illustrations to the community as YouTube videos, and browse works by other users. Switch between the “New”, “Ranking”, and “Following” tabs, and search by work title or creator name. Switch to tag search mode to filter works by tag — anyone (not just the creator) can add or remove tags, though a tag the creator has locked can only be removed by the creator, and tapping a tag instantly filters to matching works. Tapping a work card opens a draggable, resizable floating preview window, so you can keep browsing other screens while it plays. The “View Details” button opens the work's detail screen (creator, post date, tag editing, bookmarking, reposting, and more). Tap the “Follow” button next to a creator's name to follow them — the “Following” tab then gathers just that creator's posts in chronological order. When someone follows you, it shows up in the notification list under the bell icon at the top of the screen. You can choose whether your own following/followers lists are visible to other users (private by default), and view other users' lists if they've made theirs public. You can repost anyone else's work (except your own) with the “Repost” button; when a creator you follow reposts someone else's work, that work also appears in your “Following” tab, sorted by whichever is more recent — its original post date or its repost date (the card shows “Reposted by …”). Bookmarked works appear together under the “Bookmarked” tab on the Home screen, and also under the “Bookmarks” tab on a creator's work list screen. You can choose whether your own bookmark list is visible to other users (private by default), and you can view other users' bookmark lists if they've made theirs public. You can report a work with a reason, and after submitting you'll be asked whether to block that creator. Portrait videos can be watched in “Portrait mode”, which plays them back-to-back like a short-form video feed. There is a daily limit on how many works you can post: 1 per day for free members, 3 per day for Premium members. The display filter button at the top right (the eye icon with a slash) lets you hide works you don't want to see. You can hide works marked “Contains generative-AI images or video”, and add hidden-title keywords (matched against work titles only) and hidden tags (matched only against Work Plaza tags), one entry at a time using “Add new”. Edit with the pencil or delete with the trash icon; no commas or # needed. These filters apply to New, Ranking, Following (including reposts), portrait mode, creator pages, work details, and bookmarks. “Contains generative-AI images or video” is declared by the poster when posting, and only the poster can change it afterwards (from “My posts” or the work's detail screen).","help.entry62.title":"Re-editing a watermark","help.entry62.desc":"Tapping a watermark placed on the timeline's common-layer track lets you re-edit its angle, size, opacity, and display range (loop) at any time. You can fine-tune it not just when registering it, but whenever you're actually using it in a project.","help.entry63.title":"Watermark","help.entry63.desc":"A premium-only feature that lets you add your own signature or logo as a watermark on exported videos and images. You can adjust its position, size, and opacity. Tap the watermark placed on the common-layer track in the timeline to re-edit its angle, size, opacity, and visible range (looping) at any time — not just when you first register it, but whenever you use it in a project. To add a watermark, open “Add material” in the timeline and choose “+ Watermark”.","help.entry64.title":"Premium","help.entry64.desc":"Premium membership extends the 90-second video length limit of the free version up to 2 hours and lets you remove the end card (app logo) automatically added at the end of every video. Ads are also hidden, and you gain access to the watermark, tone curve, and level correction features.","help.entry65.title":"Home screen","help.entry65.desc":"The first screen shown when you launch the app, with Projects, Shared, Works, and Trash tabs. The search icon at the top right lets you filter projects by name. On the Projects tab, the + button in the bottom right lets you choose between creating a new project or a new folder.","help.entry66.title":"New project","help.entry66.desc":"Set canvas size, fps, duration (in seconds — later kept in sync with frame changes made in the timeline), drawing area (lets you draw beyond the export bounds), and which autofill settings to use, all before creating the project.","help.entry67.title":"Project details screen","help.entry67.desc":"A screen for checking and editing per-project settings all in one place — name, thumbnail, favorite status, and which autofill settings are enabled. The entry point to the save tree is also here.","help.entry68.title":"Theme settings","help.entry68.desc":"Choose the app's overall color scheme from the theme list, or freely customize the accent color. Headings/labels and body text use separate fonts, so you can enjoy re-skinning the app while keeping it readable.","help.entry69.title":"Workspace settings","help.entry69.desc":"Gathers settings such as left-handed mode (mirrors the docked panels), manually switching PC/DeX mode, and when the pan tool is shown. Adjust the layout to suit your device and dominant hand.","help.entry70.title":"Gesture settings","help.entry70.desc":"Lets you assign actions — undo/redo, frame move, eyedropper, and more — to a two-finger tap, three-finger tap, two-finger swipe, or long press. Pen buttons (on supported styluses) can also be assigned separately. Handy for triggering frequent actions with one touch instead of switching tools.","help.entry71.title":"Pen settings","help.entry71.desc":"Along with the pressure curve for tablets and pen displays, this screen lets you assign actions — such as toggling the eraser or the eyedropper — to the side buttons of a supported stylus.","help.entry72.title":"Tilt detection","help.entry72.desc":"A setting that uses tilt data from a supported stylus to thicken or thin the line as you lay the pen tip down, recreating a feel closer to a real drawing tool. Toggle it on/off from performance settings.","help.entry73.title":"Performance Settings","help.entry73.desc":"Choose from low, medium, or high quality presets based on your device's capability, or configure each item individually (custom). In addition to save method, performance, onion skin, and tilt detection, settings that affect app size and how heavy it runs — such as undo history length and automatic trash deletion — are also gathered here.","help.entry74.title":"Bucket fill detail settings","help.entry74.desc":"From the \"Bucket Fill\" section in settings, you can adjust tolerance (how much color difference from the clicked pixel still counts as the same region), expand px (how far the filled area extends past the boundary to cover gaps in the lineart), and fill under line (composites the expanded fill behind existing pixels instead of painting over the lineart, keeping the line's look intact). Adjusting these helps when the lineart has small gaps or fills feel incomplete.","help.entry75.title":"Undo history length","help.entry75.desc":"In performance settings, you can adjust how many actions undo can step back through. A larger number gives you more freedom to experiment, but also uses more memory — lower it on low-spec devices to keep things running smoothly.","help.entry76.title":"Font import","help.entry76.desc":"Lets you load a font file straight from your device's storage. Add it from the \"Import\" tab in font management, in settings. Handy when you want to use a custom-made font that isn't distributed anywhere, or a commercial font you've purchased.","help.entry77.title":"Free up space","help.entry77.desc":"See how much storage NIARIM is using on your device, and a breakdown of what's inside NIARIM (projects, materials, exported files, custom brushes/screentones/stamps/fonts, cache, and trash) as pie charts. Clear the cache, bulk-remove unused materials across all projects, empty the trash, organize projects, or erase all data (reset).","help.entry78.title":"Home screen widgets","help.entry78.desc":"Settings for the three widget types you can place on your phone's home screen: a single frame from a work (launch screen), the New work widget, and the Plaza widget. Widgets themselves are added by long-pressing the home screen, not from inside the app. \"Choose a work\" uses the same sort, display mode, search, and favorites filter as the project list tab, then lets you pick the exact frame to show in a preview with playback controls. The New work and Plaza widgets let you choose whether the background follows the app theme or uses a color you set.","help.lead":"The same 79 help topics and descriptions as in the app, searchable by keyword and category."},"zh-Hans":{"help.category.tool":"工具","help.category.brush":"画笔","help.category.penInput":"笔输入","help.category.drawing":"绘图","help.category.layer":"图层","help.category.animation":"动画","help.category.save":"保存","help.category.projectManagement":"项目管理","help.category.export":"导出","help.category.community":"社区","help.category.premium":"Premium","help.category.settings":"设置","help.entry0.title":"基本操作（点击・长按・上滑）","help.entry0.desc":"单击工具栏图标即可切换到该工具。长按同一图标或向上滑动，可打开详细设置。钢笔可切换笔刷・网点・图章・套索填充，油漆桶可切换纯色填充与网点填充，选择工具可切换矩形・套索・自动选择，手指工具可切换模糊与马赛克，快速切换工具可编辑已登记的内容，这些都在长按或上滑之后。双击图标时，画面下方会显示该工具的简短说明。\\n在画布上，双指捏合可缩放，双指拖动可平移，双指点击撤销，三指点击重做。双击画面左右边缘可移动到前后一帧。\\n连接鼠标或数位板时，可用滚轮缩放、按住中键拖动平移。","help.entry1.title":"笔工具","help.entry1.desc":"在画布上绘制线条的基本工具。长按可更改画笔种类・粗细・颜色（双击显示简要说明）。支持数位板/液晶数位板的笔压与倾斜，在设置画面的“笔输入”中调整笔压曲线，可以细致自定义笔压的传达方式（轻压时粗细/不透明度会变化多少）。切换笔的子工具后，还能用同一支笔工具进行贴网点・放置图章。","help.entry2.title":"橡皮擦工具","help.entry2.desc":"与笔工具相对，用于擦除已绘制的内容。与画笔一样可以调整粗细与不透明度，淡出、笔画衰减等画笔设置也同样适用。它进行的是“擦除”已有绘制内容的处理，而不是在图层的透明部分“添加”内容，因此下方图层会透出显示。","help.entry3.title":"填充桶工具","help.entry3.desc":"一次性填充被包围的区域。在线稿所围成的区域内点击，整个区域就会被填充为当前选择的颜色（或网点）。如果线稿有缝隙，颜色可能会扩散到意料之外的范围，因此使用前请确认线稿是否已完全闭合。可以在设置中切换纯色填充/网点填充。 详细设置（容差・扩展px・潜入线稿下方）可以在设置画面的「油漆桶填充」中调整。","help.entry4.title":"套索填充","help.entry4.desc":"用手指沿想要包围的范围描画出多边形区域，然后一次性填充其内部的工具。与填充桶不同，即使线稿有未闭合的部分，也可以自行指定要包围的范围，因此适合形状复杂或线条中断处的填色。开启“填充封闭区域”后，会像填充桶一样一次性填充套索内所有由线条封闭的区域，无论有多少个（套索与画之间的空白不会被填充）。","help.entry5.title":"吸管工具","help.entry5.desc":"拾取点击位置的颜色并将其设为绘图色的工具。它拾取的是画面上实际显示的全部图层合成后的颜色，因此即使在多个图层重叠的部分，也能准确获取“肉眼所见的颜色”。","help.entry6.title":"选择工具","help.entry6.desc":"选取画布的一部分区域，仅对所选区域进行移动・旋转・缩放的工具。长按可以从“矩形选择”“套索选择（自由形状包围）”“自动选择（魔术棒，自动合并相近颜色的区域）”三种选择方式中选择。选择中会在画布上显示表示所选范围的边框，在取消选择之前，所有帧・所有图层都会固定显示相同的范围。在套索选择中开启“吸附到线条”后，会像油漆桶填充一样查看线稿划分出的区域，只选择大部分位于套索内的区域。选区边缘会精确沿着线稿的外缘，围住这些区域的线条和内部的线条也会一并选中（从轮廓向外延伸的线条会在轮廓处截断）。上色的面也会像油漆桶填充一样按颜色视为各自的区域，因此在有上色和线条的图层上也能按画的形状选择。线条中不超过“线条间隙容差”宽度的断口会被视为相连。套索内没有线稿时，按圈出的形状原样选择。线稿取自选择参照（“仅工作图层”／“所有可见图层”）。","help.entry7.title":"手指工具（扭曲工具）","help.entry7.desc":"沿手指划动的方向推挤像素使其扭曲，营造出用手指涂抹湿颜料般的效果。相较于精细修正，更常用于将已画好的线条进行有机的扭曲以增添表现力。","help.entry8.title":"图形工具","help.entry8.desc":"一键绘制直线・矩形・圆形等精确图形的工具。从起点拖动到终点时会即时预览，松开手指即可确定。在难以徒手绘制直线或正圆时非常方便。","help.entry9.title":"文字工具","help.entry9.desc":"在画布上放置文字的工具。可选择字体・大小・颜色・竖排/横排。竖排时还支持半角字母数字的自动旋转・纵中横（数字保持横向排列的表记）・注音标注（类似日语振假名的读音标注）。放置的文字在导出时也会作为像素烧录进画面。 可添加・搜索・删除文字工具可用字体的画面。除初始内置字体外的其他免费字体，为控制初始安装容量，需从此处按需下载。","help.entry10.title":"快捷工具管理","help.entry10.desc":"登记一组常用工具组合，只需一次点击即可依次切换。长按或向上滑动可打开管理弹窗，编辑已登记的内容和顺序。","help.entry11.title":"快捷工具","help.entry11.desc":"预先登记常用的画笔・工具组合，只需点击一个按钮即可依次切换。长按或向上滑动画布上的↺按钮，即可打开可以添加、排序、删除的管理弹窗。可通过拖动改变顺序。","help.entry12.title":"印章工具","help.entry12.desc":"像画笔一样把已注册的图像放到画布上，可重复使用速度线、背景图案和小道具而无需重新绘制。像素模式使用与像素画滤镜相同的 Pixel Art 处理，在像素化和减色时保持清晰的透明边界。马赛克是独立效果，不用于印章像素模式。印章面板还可调整旋转角度和大小。","help.entry13.title":"画笔","help.entry13.desc":"长按画笔工具，可以从普通绘图切换到网点填充或印章放置等子工具。无需每次切换工具，就能用同一支笔在多种作业之间来回操作。","help.entry14.title":"变换选区","help.entry14.desc":"用选择工具圈出的区域，可以在画布左下方的「移动」「缩放」「旋转」按钮中选择模式，然后在选区内拖动进行变形。适合用来调整误画部分的位置，或只放大强调某一部分。按同一栏的「全选」会把当前图层整体变成选区，因此整个图层的移动、旋转、缩放也可以用同样的方式完成（原先独立的「变换工具」已整合到这里）。如果想单独拖动各个网格点做出更自由的变形，请使用同一栏的「自由变形」「网格变形」。","help.entry15.title":"自由变形・网格变形","help.entry15.desc":"从画布右上角的编辑/设置菜单打开的、以整个图层为对象的变形工具。与选区变形不同，不需要选区，可以用手指单独拖动角点或网格点做出自由的变形。控制面板的分割数滑块最多可将网格细分为10×10，用两根手指同时捏住不同的点，即可直观地进行旋转、缩放操作。","help.entry16.title":"取色器","help.entry16.desc":"可在同一画面中切换HSV与RGB来选色的取色器。调色板功能可保存、调用正在使用的配色组合。调色板也可以通过文件导出或二维码与其他设备共享。","help.entry17.title":"笔刷收藏","help.entry17.desc":"点击笔刷列表中笔刷上的星形图标即可添加或取消收藏（与应用内其他收藏功能——自动上色设置、图章、字体、绘图滤镜等——操作方式相同）。列表顶部的星形图标还可以筛选为仅显示收藏项目。已收藏的笔刷不会被误删。","help.entry18.title":"自定义笔刷","help.entry18.desc":"在笔刷列表中长按预装笔刷并选择「复制」，即可基于它创建专属自定义笔刷。复制后的笔刷可以自由编辑粗细、不透明度、硬度、旋转、密度、散布、模糊半径等参数，不需要时也可以删除（预装笔刷本身无法编辑或删除）。用画布上的滑块调整的粗细和不透明度会按笔刷分别记住，预装笔刷也一样，并可以从列表的菜单恢复为默认值。还可以用文件夹分类，或用星标图标收藏。","help.entry19.title":"画笔折返","help.entry19.desc":"在画笔设置中开启「描边」后即可使用「折叠模式」。关闭时与普通描边笔的绘制完全相同。开启后，描边笔的线条本身会根据所画笔画的方向和弯曲而折叠、卷曲；它不会自动生成波浪。每个弯曲处都会出现一条从内侧轮廓分出、弯曲后渐渐消失的折返线。若笔画持续朝同一方向转动，每转270°会加入一条较含蓄的折返线。折叠类型有5种。「波浪俯视」让先画的一侧在前，「波浪仰视」让后画的一侧在前。「右卷」按照朝笔画前进方向右侧卷入的方式决定前后，「左卷」则朝左侧；依据的是所画方向而不是屏幕方向。「月牙卷」会沿着所画的C形曲线整理成相连的月牙形。「折返长度」调整折返线的长度（与画笔大小联动），「折返角度」调整跟随笔画弯曲的强度（50%时自然联动），「折返线的弯曲起点」调整材质看起来的厚度（0%时从分叉处立即弯曲）。描边笔的笔压和淡出（入笔与收笔）只改变包括描边在内的整体形状，描边线的粗细和颜色都不会改变。关闭「描边」中的「保持重叠」后，重叠的笔画在交界处不描边而连成一体（重叠处也不画折返线），只描整体的外围。开启「描边」中的「强弱」后，描边线会朝笔画中每段曲线的顶点变粗（曲线的起点和终点保持描边宽度，到顶点逐渐变为「顶点处的描边宽度」，抬起笔时生效）。","help.entry20.title":"图层","help.entry20.desc":"将一块画布分成多个透明「图层」来绘制的机制。将线稿、上色、背景等分别绘制在不同图层上，之后可以只重做上色，或在不擦除线稿的情况下更换背景。画面中，叠得越靠上的图层显示在越靠前的位置。每个图层行的图标可一键删除或与下方图层合并，图层面板顶部的图标还可以一次性合并所有可见图层。","help.entry21.title":"混合模式","help.entry21.desc":"用于更改图层与下方图层的合成方式，常用于叠加网点或颜色效果的图层。\n正常：直接叠加。\n正片叠底：与下方图层相乘后变暗，是阴影表现的经典手法。\n滤色：叠加亮度后变亮，适合表现光效。\n叠加：暗部更暗、亮部更亮，增强对比度。\n相加（发光）：直接相加颜色，适合光效线条等。\n减去：相减颜色，呈现暗沉的效果。\n变暗：取上下两图层中较暗的颜色。\n变亮：取上下两图层中较亮的颜色。\n颜色加深：使下方颜色变暗并加深发色。\n颜色减淡：使下方颜色变亮并加深发色。\n强光：比叠加更强烈的对比效果。\n柔光：比叠加更柔和的对比效果，适合柔和的阴影。\n差值：显示上下两色的差异，可用于检查颜色偏差等。\n色相、饱和度、颜色、明度：分别仅将该图层的色相、饱和度、色彩或明度反映到下方图层。\n线性加深：将上下颜色相加后减去基准值，产生更强的变暗效果。\n线性减淡：线性相加上下颜色使其变亮。它与“相加（发光）”是不同的混合模式，图层半透明时“相加（发光）”会更亮。\n亮光：根据上层颜色在加深与减淡之间切换，产生很强的对比。\n线性光：根据上层颜色线性提高或降低亮度。\n点光：根据上层颜色向较暗或较亮一侧替换。\n实色混合：对亮光结果进行阈值化，形成强烈的原色分离。\n排除：比“差值”更柔和的反相与差异效果。\n划分：用上层颜色除下层颜色，可用于提亮校正和强调色差。\n在混合模式列表中，每种模式旁会显示将红、黄、蓝、白、黑叠加在由暗到亮的颜色上的样例（样例下方为半透明叠加时的效果）。","help.entry22.title":"剪贴蒙版","help.entry22.desc":"使绘制内容仅限于紧邻下方图层的不透明像素范围内的功能。当想要在不超出线稿的范围内上色时，在线稿图层上方新建上色图层并启用剪贴蒙版，就不必担心不小心画到线稿外面。","help.entry23.title":"公共图层","help.entry23.desc":"普通图层按每一帧独立存在，而公共图层则是在多个帧・场景中共享同一内容的图层。像背景这样不随帧变化而移动的元素，无需每帧重新绘制，只需画一次即可。在时间轴上会以专用轨道的形式显示。 可以把普通图层转换为共同图层（在多个帧中持续显示相同内容的图层）的功能。也可以先把当前显示的图层合并为一张，再进行共同化。想反复使用背景等每帧内容相同的部分时，可以省去重新绘制的麻烦。","help.entry24.title":"图层多选・批量操作","help.entry24.desc":"使用图层面板的选择模式，可以用勾选框一次选中多个图层进行合并或批量删除。合并只能在普通图层、自动上色用线稿、自动上色图层之间进行（共同图层、文件夹、时间轴素材不能合并）。","help.entry25.title":"图层文件夹","help.entry25.desc":"可以把多个图层整理到文件夹中的功能。即使是部位较多的插画，也能让图层面板保持清晰易看。剪裁无法跨文件夹套用，如果要使用剪裁，建议把相关图层放在同一个文件夹内。","help.entry26.title":"自动上色","help.entry26.desc":"在自动上色专用线稿图层下方创建自动上色图层，并根据预先制作的「自动上色设置」（各部位的颜色、网点组合）自动进行上色的功能。由于可以在画完线稿后一次性上色，能大幅减少需要反复绘制同一角色的手绘动画中的上色工作量。重新绘制线稿后，时间轴和图层面板会显示更新标记，提示需要重新执行自动上色。在时间轴画面的三点菜单中选择「执行自动上色」，即可一次性重新计算所有带有更新标记的自动上色图层，省去重新绘制线稿后逐个图层在图层面板中执行的麻烦。自动上色设置的每个部位都有关于如何处理线稿颜色的设置（指定颜色、与填充色相同、色彩描边）。选择色彩描边（贴合线稿）后，线稿颜色会按HSL偏移以匹配填充色，使线条不显突兀、自然融合。设置越积越多，分配部位时显示的列表就会变长、难以浏览。可以在项目设置（或图层面板的部位分配对话框）中，将列表筛选为只显示本项目使用的设置，让列表更简洁、更易于挑选。「填补线稿与填色之间的缝隙」调大后，会填充到线条较淡的边缘下方，描边或线稿颜色与填充色相同时可见的线稿与填色之间的缝隙会变小。","help.entry27.title":"渐变上色（自动上色设置）","help.entry27.desc":"自动上色设置的每个部位不仅可以使用单色，还可以设置渐变。可拖动的对称控制点让你直观地调整渐变的范围和角度。每个部件还可以设置「用指定颜色描边」。勾选后，会在填色范围的最外侧（紧贴线稿的部分）画出指定颜色和粗细的线条。描边颜色可通过取色器自由选择，粗细可通过滑块、±按钮或点击数字直接输入来调整。设置项上方会显示预览，可以在实际执行自动上色之前确认颜色和粗细。","help.entry28.title":"场景操作","help.entry28.desc":"在时间轴的场景标签页中，可以新增、复制、删除、重命名、重新排序场景。切换到多选模式后，还可以一次性移动、复制、删除多个场景。","help.entry29.title":"洋葱皮","help.entry29.desc":"将当前编辑帧前后的帧以半透明方式叠加显示，使你可以一边确认动作的连贯性一边绘制的功能。可以在性能设置中调整显示的帧数（前后各显示几帧）以及颜色・透明度。","help.entry30.title":"标尺","help.entry30.desc":"直线・圆・椭圆・透视标尺（使用消失点的透视图法专用标尺）等，用于辅助绘制徒手难以画出的精确线条的功能。放置的标尺会使笔尖自动吸附，即使是没有标尺就难以绘制的具有纵深感的构图也会更容易画出。标尺可以通过操作控制柄进行移动・旋转・调整大小。鱼眼透视标尺是五点曲线透视：在镜头圆内，横线和竖线弯成圆弧，纵深方向的线汇聚到中心。笔画会沿着与开始绘制方向相符的线条，拖动控制柄可移动中心、改变半径（圆右侧的点）和倾斜（圆上方的点）。","help.entry31.title":"淡出","help.entry31.desc":"可分别独立设置入笔（笔画起点）和收笔（笔画终点）的数值与距离的画笔功能。可以只调整起点、只调整终点，或使用非对称设置，分别控制两端的粗细和不透明度。描边笔只改变整体形状（粗细），不改变不透明度。","help.entry32.title":"笔画衰减","help.entry32.desc":"与淡出类似，但更接近“墨水逐渐用尽”的表现，绘制得越久颜色越淡或越干涩的效果。可再现毛笔或马克笔持续书写时墨水耗尽般的质感。","help.entry33.title":"混色","help.entry33.desc":"使用画笔上色时，将画笔正下方已有的颜色与即将涂上的选定颜色混合后再绘制的功能。可在画笔设置的混色模式中选择：不混合直接上色的“数字”、像颜料一样混合并把沾到的颜色拖开的“油画风混色”、叠加透明颜料且干后颜色聚集在边缘的“水彩风混色”。","help.entry34.title":"笔压曲线","help.entry34.desc":"笔输入设置中的功能，可通过图表自由调整实际笔压强度与画笔粗细・不透明度反映方式之间的关系。无论是希望轻压也能画出粗线的人，还是相反希望必须用力按压才会变粗的人，都能根据自己的用笔习惯细致自定义画感。更改设置后可当场试写确认效果。","help.entry35.title":"网点上色","help.entry35.desc":"在填充工具的设置中把纯色填充切换为网点填充，就能用选中的网点、线条等网点图案进行填充。还提供像素模式专用的方格纹、格子纹网点，可以做出符合像素画质感的上色效果。荷叶边、针织纹理、连裤袜等手绘起来很费工夫的细致花纹也能轻松画出。还可以自制原创网点并添加使用，或与其他用户分享。","help.entry36.title":"像素模式","help.entry36.desc":"笔刷、字体、印章各自都提供的设置，开启后会去除抗锯齿，呈现清晰的像素画风轮廓。想特意做出老游戏般的质感，或想营造低分辨率效果时使用。配色方式可从「不指定颜色」「指定颜色」「指定颜色数」「从调色板选择」4种中选择，也可以使用像素画专用调色板。","help.entry37.title":"作画区域","help.entry37.desc":"可以在比导出范围更大的区域内作画的设置。画布上会显示表示导出范围的红色边框，画到边框外的部分不会被导出，但可以为之后用推拉镜头等运镜方式调整所展示的范围留出余地。在新建项目时设置放大倍率。","help.entry38.title":"画布背景色","help.entry38.desc":"可以设置项目画布的背景色。使用透明导出（透明WebM）时背景色不会影响导出结果，但可以改成自己喜欢的颜色，方便作画时查看。","help.entry39.title":"时间轴","help.entry39.desc":"管理动画时间轴的画面。将帧（单张静止图像）排列并像翻页动画一样播放，就形成了动画。文字・图片・视频・音频素材轨道、公共图层轨道、摄像机关键帧也都在同一条时间轴上管理。文字・图片・视频与帧插画之间的前后关系可在「叠放顺序」中按整个场景或指定的帧范围调整。也可以长按项目进行多选，一起移动。","help.entry40.title":"场景","help.entry40.desc":"将一个项目（一段视频）内部按场景（分镜）划分管理的功能。文件夹是以项目为单位进行整理，而场景则用于表现一段视频内部的场景转换。在时间轴的场景标签中可以新增、复制、删除、重命名、重新排序场景。切换到多选模式后，还可以一次性移动、复制或删除多个场景。","help.entry41.title":"帧操作","help.entry41.desc":"在帧列表中，除了新增、复制、删除之外，还可以在多选模式下一次性移动、复制、删除多个帧。增加保留格数可以让同一帧持续显示多个格子（即所谓的“停格”），从而在动作较少的镜头中节省作画张数。","help.entry42.title":"素材片段（文字・图片・视频・音频）","help.entry42.desc":"放置在时间轴文字、图片、视频、音频轨道上的片段。长按拖动片段本身可移动其起始位置，拖动两端的手柄可改变使用范围（长度）。同一时间重叠的素材会自动放到其他行。点击文字・图片・视频片段，会在预览下方打开编辑面板：可修改文字内容・字体・颜色・描边，位置・缩放・X轴／Y轴／Z轴旋转・不透明度（也可在预览上拖动，添加关键帧即可产生动画），蒙版（矩形・椭圆・羽化・反转）以及所在行，也可在此复制或删除。音频片段在详情面板中调整音量和淡入淡出。","help.entry43.title":"素材列表","help.entry43.desc":"可以统一查看项目中使用的图片、视频、音频素材的画面。放置在时间轴上的素材的原始文件都汇集在这里。","help.entry44.title":"音量调整","help.entry44.desc":"放置在时间轴上的音频片段，可以在详情面板中调整音量、淡入、淡出的秒数。可用来调整音效和背景音乐的音量平衡，或让曲子的开头、结尾更加顺滑。","help.entry45.title":"摄像机关键帧","help.entry45.desc":"在时间轴上的特定位置记录摄像机的位置・缩放比例・旋转角度的功能。关键帧之间会自动平滑插值，因此可以轻松添加平移（横向移动）或拉近拉远等镜头运动。","help.entry46.title":"演出滤镜","help.entry46.desc":"可应用于场景或帧的画面效果（模糊・色调校正・辉光・像素画等）。在不改变手绘画面本身的前提下，作为演出手段调整整个画面观感时使用。绘画滤镜中的色调曲线（预设与强度）・色阶・锐化・USM锐化・暗角（颜色・范围・浓度）・水彩边界也收录在演出滤镜中，可以一次对多个帧施加相同的效果。像素画也可以选择配色方式（不指定颜色・指定颜色・指定颜色数・从调色板选择）。限制颜色时，单用一种颜色与原色相差较远的地方，会用可用颜色中的两到三种按规则排列（抖动）来接近原色，这种排列在帧与帧之间不会移动；轮廓处保持清晰。抖动可以用开关打开或关闭，关闭后用最接近的一种颜色填充。 演出滤镜可以叠加应用多个，其应用顺序依照时间轴上的排列顺序。拖动滤镜列表重新排序后，实际反映到画面上的顺序也会随之改变。 一种演出滤镜，会逐帧改变类似胶片颗粒感的噪点。可以用滑块调整强度、数量（噪点出现的密度）和颗粒大小。回到同一帧时噪点形态相同（拖动时不会闪烁），播放时颗粒则会呈现出跳动的效果。 用来表现画面中降雨的演出滤镜。可以用滑块调整降雨强度（雨滴数量）、速度、雨滴大小和风向角度。每滴雨都会随着帧数推进以恒定速度持续下落，呈现自然的降雨效果。","help.entry47.title":"绘图滤镜","help.entry47.desc":"直接应用于所选图层的滤镜（演出滤镜作用于整条时间线或整个场景，而绘图滤镜按图层生效）。内置26种滤镜：高斯模糊、镜头模糊、动画风、色调曲线、色阶、描边、锐化、USM锐化、暗角、复古动漫、老电视、二值化、鱼眼镜头、色差、眼镜断层、像素画、质感变换、背景融合、积墨、自动线稿、棱镜、反色、马赛克、噪点、球体阴影和水彩边界。水彩边界会让作业图层上涂色部分的边缘聚集颜色、内侧变得通透，就像干了的水彩（开启“颜色交界处也添加”后，相邻颜色的交界处也会出现边缘）。动漫风格会减少颜色数，并在相邻颜色之差达到“颜色差阈值”以上的边界上，于较暗的一侧画出“边界线粗细”的线（线稿的线条不会变粗）。棱镜会把图层上每个形状分别涂上彩虹六色（红、绿、青色、蓝、紫、红）并模糊，再把图层设为线性减淡。先在单独的图层上用深色画出细小的叶片状形状再使用，画面上就会出现柔和的彩虹光痕（模糊量与一般的高斯模糊采用相同标准）。球体阴影会在椭圆形光的内侧叠加光色、外侧叠加阴影色，且只加在已绘制的地方（也可以在画布上拖动光）。描边不会改写原图层，只会把结果绘制到新图层。眼镜断层只对用面板的「画笔」「填充桶」在画布上涂抹的范围（可用「橡皮擦」修改）施加类似强力眼镜镜片的局部变形（如果有选区或选区图层，会从该范围开始）。画布上有选区时，绘图滤镜只应用于选区内。像素画还可选择配色方式（不限制、指定颜色、指定颜色数或从调色板选择）。限制颜色时，单用一种颜色与原色相差较远的地方，会用可用颜色中的两到三种按规则排列（抖动），使其更接近原色；轮廓处不混色，保持清晰。指定颜色数时，会从占画面大部分的颜色中选取。抖动可以用开关打开或关闭，关闭后用最接近的一种颜色填充。大小可在“指定色块大小”（1～100共100级）和“指定点数”（横向・纵向点数滑块，最左为1，最右为画布尺寸）之间切换，横向和纵向会在保持画面宽高比的同时一起变化，两种指定方式也会联动。两种方式下点都保持正方形，不会产生半透明的边缘。 自动线稿可在应用滤镜前直接编辑临时Vector控制点。拖动控制点时只移动该点。选择“应用”右侧的“添加控制点”后点击线条可添加控制点，选择“删除控制点”后点击控制点可将其删除（两者都未选择时点击控制点，会先确认再删除）。编辑后的形状会直接用于最终应用结果，控制点的移动、添加和删除也可以用滤镜编辑的撤销・重做逐一恢复。 色调曲线中，轻点曲线上的空白处可添加点，拖动点可移动，长按可删除；R、G、B 各颜色的曲线在 RGB 曲线之后生效。色阶也可按 R、G、B 分别调整，伽马可改变中间调的亮度。描边的“向内延伸”可将边缘扩展到原轮廓内侧，描边的新图层会放在原图层的正下方。色差可指定将偏移分配到 X（横向）、Y（纵向）、Z（从中心向外）各多少。鱼眼镜头的中心和半径也可以在画布上拖动 ＋ 和圆上的手柄来更改。暗角会柔和地压暗整个画布的四个角（没有绘画的透明处也会有阴影）。可用“范围”调整从四角向中心压暗到多远，用“浓度”调整四角的暗度。眼镜断层像真正的高度数眼镜一样，让透过镜片看到的景物朝镜片中心均匀缩小（负值，近视用）或放大（正值，远视用），并在镜片边缘使轮廓错开成台阶状。积墨只积在线条以“最大角度”或更小角度相交处（初始值90°时为锐角和直角：V字、交叉的窄侧、T字、方角）的夹角内侧，更宽的角不积：在相交点从线条边缘起为“中央宽度”，再朝“范围”的末端笔直变细，末端为0px，平滑地收成尖端（即使加大“中央宽度”，也不会鼓出连接两侧积墨末端的直线之外，最宽时中间也是平的）；若线条在范围内中断，该线条上的积墨会以中断处为终点细到0px（每条线的长度可以不同），此时两处积墨仍会在夹角的正中相接，距两条线的宽度相同（较长线条的积墨从那里再细到范围的末端）。自动线稿沿草稿线条的中心描出细线。靠得很近的线条只要中间有一点空隙，就仍画成两条线，只填补线条内部的小白点。两条线靠拢并贴在一起的地方，不会在中间画成一条线，而是像草稿一样两条线逐渐靠近并合在一起。线条交叉或重叠的地方，也会像草稿一样让每条线照原样延续（不会在交点处折弯，重叠的两条线也不会融成一条）。以较浅角度斜向交叉的线也会笔直地穿过交叉处，仅相互接触的线（例如沿着头部画的头发轮廓）则各自留在自己的一侧，仍是分开的线。眼睛之类的点会画成实心的点。比“草稿线宽”短的分叉不绘制。“起笔收笔”可以用开关打开或关闭，关闭后线条直到末端都保持相同粗细。背景融入以混合模式“强光”叠加背景的光与影（影子的颜色不是黑色或灰色，而是把背景中阴影部分的颜色压暗后的颜色）。周围的颜色以“叠加”覆盖整幅画来统一色彩方向，从下方反上来的光和周围的反射光以“滤色”加入，霓虹灯之类的强烈有色光以“相加（发光）”加在轮廓上。“匹配背景的明暗与色调”会把比背景过亮或过于鲜艳的颜色拉回背景的范围，并让暗部、中间调、亮部分别带上背景中相同明度的色调（线稿的黑色保持不变）。“模糊程度”是取色前模糊背景的程度。","help.entry48.title":"自定义自动操作（操作录制）","help.entry48.desc":"将在画布或时间线上进行的受支持操作录制为命名步骤，以便重复执行。从“自动操作”中新建项目开始录制，停止后可在检查画面中调整步骤顺序或删除步骤，再进行保存。已保存的自动操作可以重命名、重新录制、删除、仅筛选收藏项，还能以JSON文件导出和导入。仅包含画布操作且全部录制于同一帧的自动操作，可在执行时选择当前帧、指定帧范围或所有帧。时间线自动操作以及跨越多帧的录制不会显示帧范围选项。","help.entry49.title":"图层关键帧（分部件动画）","help.entry49.desc":"按帧设置每个图层的位置・缩放・旋转，关键帧之间会自动插值。摄像机关键帧移动的是整个画面，而这个功能只移动单个图层。由于自动上色的每个部件都会生成为独立的图层，因此可以直接用它来做分部件动画（只动一只手臂、只让嘴巴开合等）。每个关键帧还可以单独设置「匀速」「缓入」「缓出」「缓入缓出」「弹跳」这类缓动（与下一个关键帧的衔接方式），不仅限于单调的匀速移动，还能表现出弹跳般的动作。在图层面板的三点菜单「动画（关键帧）」中设置。图层本身的画面内容不会改变，只是显示位置发生变化的非破坏性变形。此功能只影响时间轴的显示（预览・导出），不会影响画布模式下的实际作画。","help.entry50.title":"图层分组（把多个部件一起移动）","help.entry50.desc":"用同一组关键帧把多个图层一起移动的功能。例如「手臂」由皮肤、袖子两个自动上色部件组成时，把这两个图层分到同一组后，只需一次关键帧操作就能让它们一起移动。在图层面板中多选（勾选框）图层，再点击底部工具栏的「分组」图标即可创建。分组的运动会叠加在每个成员图层自身的关键帧（如果设置了的话）之上，因此可以把分组整体的运动和单个图层的微调结合起来使用。一个图层同一时间只能属于一个分组。","help.entry51.title":"EndCard（片尾标志）","help.entry51.desc":"导出视频时，会在正片结尾自动添加的NIARIM标志短片（约5秒）。免费版无法隐藏或删除，但成为Premium会员后可以开关显示・更改时长・进行替换。","help.entry52.title":"自动保存","help.entry52.desc":"专用于崩溃或文件损坏时恢复的保存。每次绘图等发生变更时都会自动保存，最多保留3份，按从旧到新的顺序覆盖。它与手动保存（存档槽・存档树）完全分开管理，不能替代常规保存。仅在应用异常退出后重新启动时，才会询问是否要恢复。","help.entry53.title":"存档槽","help.entry53.desc":"在固定数量的存档位（槽）中，由自己选择保存位置进行保存的方式。槽位数量由设置决定（低画质5个・中画质10个）。由于每次都需要自己选择要覆盖的槽位，适合“想保留这个时间点的状态”这类管理方式。","help.entry54.title":"存档树","help.entry54.desc":"每次保存都会创建一个新的存档点，并可以从过去的存档点分支出另一段历史（分叉）的保存方式。没有数量上限，适合“想回到那个版本后再尝试另一种展开”这类用法。画面上存档点会以从下往上生长的树状图形式显示。","help.entry55.title":"文件夹","help.entry55.desc":"将项目（作品）分组整理的功能。支持多层级结构，因此也可以用来统一管理同一作品的多个话数或系列作品（例如：在“作品名”文件夹中依次排列“第1话”“第2话”……等项目）。如果想在一部动画内划分场景，请使用画布画面中的“场景”功能，而不是文件夹。","help.entry56.title":"回收站","help.entry56.desc":"已删除项目暂时移动到的地方。在被彻底删除之前，都可以从这里恢复。可以在设置中指定自动删除的天数（关闭/30天/60天/90天）。","help.entry57.title":"共享（.niashare）","help.entry57.desc":"用于将项目传递给他人（或自己的其他设备）的专用共享文件格式。接收方打开此文件后，会复制并添加到自己的项目列表中。共享源的.niashare文件本身不会被更改。","help.entry58.title":"数据迁移（.niatra）","help.entry58.desc":"将设置、素材、笔刷、自动上色设置、主题、调色板（取色器・像素画专用）等整个应用环境一次性转移到其他设备的功能。可以通过复选框单独选择要转移的项目，还可以选择性地一并包含制作中的项目（所选项目会连同素材、字体一起完整转移）。如果只想传递单个项目，也可以改用「共享（.niashare）」。","help.entry59.title":"视频导出（MP4・WebM・GIF・AVI）","help.entry59.desc":"将作品导出为通用MP4视频。免费版可导出的时长有上限（90秒），且会在视频结尾自动添加片尾卡（应用Logo）。 可在保留Alpha通道（背景透明部分）的情况下导出的视频格式。仅在支持的播放环境中才能透明播放。适合作为素材叠加到其他应用中使用。 导出为动图GIF。由于会自动循环播放，适合在社交媒体上轻松分享的场景。 如果更看重兼容性，也可以导出为AVI（Motion JPEG）。不支持Alpha通道（透明），部分设备上应用内预览可能无法使用（此时仍可通过「分享」用外部播放器播放）。 免费会员的项目长度上限为90秒（付费会员为2小时）。如果新增或复制帧会超过上限，在点击按钮的瞬间就会显示提示对话框，因此实际上不会超过90秒。","help.entry60.title":"导出画面","help.entry60.desc":"在“预设”中选择“标准”“高画质”或“自定义”。选择“自定义”后，可以调整帧率（FPS）。导出视频、图片期间会显示进度，也可以中途取消。所需时间会因设备性能而异。","help.entry61.title":"作品广场","help.entry61.desc":"可以将动画・插画作品以YouTube视频的形式发布到社区，并浏览其他用户的作品。可以切换「最新」「排行榜」「关注」三个标签页，也可以按作品标题或投稿者名称搜索。切换到标签搜索模式后可按标签筛选作品，标签不仅投稿者本人，其他用户也可以自由添加或删除（投稿者锁定的标签只能由投稿者本人解锁），点击标签即可筛选出相同标签的作品。点击作品卡片会打开可拖动、可调整大小的悬浮预览窗口，可以在继续操作其他画面的同时观看。点击「查看详情」按钮可打开作品详情画面（投稿者、发布日期、标签编辑、收藏、转发等）。点击投稿者名称旁的「关注」按钮即可将其加入关注列表，「关注」标签页会按时间顺序汇总显示该作者的作品。有人关注你时，会显示在画面右上角铃铛图标的通知列表中。你可以分别设置自己的关注列表/粉丝列表是否对所有用户公开（默认非公开），也可以查看已公开的其他用户的列表。除自己发布的作品外，都可以用「转发」按钮转发；当关注的作者转发了他人的作品时，该作品也会以「发布日期」和「转发日期」中较新的一方为基准，混入「关注」标签页中显示（卡片上会显示「○○转发了」）。收藏的作品会汇总显示在主页的「已收藏」标签页中，也可以在投稿者作品列表画面的「收藏」标签页中查看。可以设置自己的收藏列表是否对其他用户公开（默认不公开），也可以查看已设为公开的其他用户的收藏列表。对不当作品可以附上理由进行举报，举报提交后会询问你是否要屏蔽该投稿者。竖屏视频可以在「竖屏模式」中连续播放观看。每日可发布的作品数量有上限，免费会员每天1个，高级会员每天3个。点击画面右上角的显示筛选按钮（带斜线的眼睛图标），可以隐藏不想看到的作品。除了可以隐藏「包含生成式 AI 图像或视频」的作品外，还可以通过「新增」逐条登记只匹配作品标题的隐藏标题关键词，以及只匹配作品广场标签的隐藏标签。可用编辑图标修改或垃圾桶图标删除，无需输入逗号或 #。这些筛选适用于「最新」「排行榜」「关注」（含转发）、竖屏模式、投稿者页面、作品详情和收藏。「包含生成式 AI 图像或视频」由投稿者在发布时自行声明，发布后也只有投稿者本人可以更改（可在「我的投稿」或作品详情画面中更改）。","help.entry62.title":"重新编辑水印","help.entry62.desc":"点击放置在时间轴共同图层轨道上的水印，随时可以重新编辑其角度、大小、不透明度、显示范围（循环显示）。不仅在登记时，在项目中实际使用时也能随时细致调整。","help.entry63.title":"水印","help.entry63.desc":"可以在导出的视频・图片上加入自己签名或Logo作为水印的高级会员专属功能。可以调整位置、大小、不透明度。点击时间轴共通图层轨道上放置的水印，随时都能重新编辑其角度、大小、不透明度、显示范围（循环显示）——不仅是首次设置时，在项目中实际使用时也能随时细致调整。 添加水印时，请在时间轴的“添加素材”菜单中选择“＋水印”。","help.entry64.title":"Premium","help.entry64.desc":"成为高级会员后，免费版限制的90秒视频时长将延长至最长2小时，并可移除每个视频结尾自动添加的片尾卡（应用Logo）。同时广告也会隐藏，还可使用水印、色调曲线、色阶校正功能。","help.entry65.title":"主页","help.entry65.desc":"启动应用后最先显示的画面，可在项目、共享、作品列表、回收站各标签间切换查看。右上角的搜索图标可按项目名称筛选。在项目标签页中，可通过悬浮按钮选择新建项目或新建文件夹。","help.entry66.title":"新建项目","help.entry66.desc":"在创建项目前，统一设定画布尺寸、fps、时长（以秒为单位，之后会与时间轴上的帧数增减联动）、绘制区域（可以在导出范围之外多画一些的设置）、要使用的自动上色设置等。","help.entry67.title":"项目详情画面","help.entry67.desc":"可以在一个画面中集中查看、编辑项目名称、缩略图、收藏状态、要启用的自动上色设置筛选等项目相关设置。存档树的入口也在这里。","help.entry68.title":"主题设置","help.entry68.desc":"可以从主题列表中选择应用整体的配色，也可以自由自定义强调色。标题・项目名称用字体与说明文字用字体是分开的，能在保持可读性的同时享受换装乐趣。","help.entry69.title":"工作区设置","help.entry69.desc":"汇集了左手模式（左右翻转停靠面板）、手动切换电脑/DeX模式、手掌工具显示条件等设置的画面。可以根据所用设备和惯用手调整成更方便操作的布局。","help.entry70.title":"手势设置","help.entry70.desc":"可以将撤销/重做、跳转帧、取色等操作分配给双指点击、三指点击、双指滑动或长按。数位笔按键（在支持的触控笔上）也可以单独分配操作。想不切换工具就用一个动作触发常用操作时很方便。","help.entry71.title":"画笔设置","help.entry71.desc":"除了数位板・数位屏的压感曲线外，这个设置画面还能把切换橡皮擦、取色器等操作分配给支持的触控笔侧面按键。","help.entry72.title":"倾斜检测","help.entry72.desc":"利用支持的触控笔的倾斜信息，在笔尖倾斜放倒时让线条变粗或变淡，重现更接近实际画具的书写手感的设置。可以在性能设置中开关。","help.entry73.title":"性能设置","help.entry73.desc":"可根据设备性能从低画质・中画质・高画质预设中选择，也可逐项单独设置（自定义）。除保存方式・运行速度・洋葱皮・倾斜检测外，撤销次数、回收站自动删除等影响应用容量与运行负载的设置也都集中在这里。","help.entry74.title":"填充工具详细设置","help.entry74.desc":"在设置画面的“填充工具”中可以调整容差（点击位置的颜色相差多少仍视为同一区域）、扩展px（填充区域向边界外扩展多少以填补线稿的缝隙）以及潜入线条下方（不覆盖线稿本身，而是把扩展部分合成到已有像素的背后，从而保持线条外观不变）。当线稿有细小缝隙或填色感觉不完整时，调整这些设置能让效果更稳定。","help.entry75.title":"撤销次数设置","help.entry75.desc":"在性能设置中可以调整撤销能回溯的操作次数。次数越多越能放心地反复尝试，但也会占用更多内存；在低性能设备上减少次数可以让运行更轻快。","help.entry76.title":"字体读取","help.entry76.desc":"可以直接读取设备内的字体文件来使用的功能。可在设置画面字体管理的「读取」标签页中添加。想使用未公开发布的自制字体或已购买的商用字体时可以使用此功能。","help.entry77.title":"释放空间","help.entry77.desc":"以饼图查看NIARIM在设备上占用的容量，以及NIARIM内部（项目、素材、已导出文件、自制画笔/网点/图章/字体、缓存、回收站）的详细占比。可以清除缓存、批量删除所有项目中的未使用素材、清空回收站、整理项目，或删除全部数据（初始化）。","help.entry78.title":"主屏幕小组件","help.entry78.desc":"可放置在手机主屏幕上的三种小组件(启动页的作品单帧画面／「创作作品」／「作品广场」)设置。添加小组件本身需要长按主屏幕进行,应用内没有添加按钮。「选择作品」使用与作品列表标签页相同的排序、显示方式、搜索和收藏筛选,选好作品后还可以在带播放控件的预览中选择要显示的具体帧。「创作作品」和「作品广场」小组件可以选择背景色跟随应用主题,还是自行指定颜色。","help.lead":"与应用内帮助完全一致的79个条目，可按关键词或类别查找。"},"zh-Hant":{"help.category.tool":"工具","help.category.brush":"筆刷","help.category.penInput":"筆輸入","help.category.drawing":"繪圖","help.category.layer":"圖層","help.category.animation":"動畫","help.category.save":"儲存","help.category.projectManagement":"專案管理","help.category.export":"匯出","help.category.community":"社群","help.category.premium":"Premium","help.category.settings":"設定","help.entry0.title":"基本操作（點擊・長按・上滑）","help.entry0.desc":"單擊工具列圖示即可切換到該工具。長按同一圖示或向上滑動，可開啟詳細設定。鋼筆可切換筆刷・網點・印章・套索填色，油漆桶可切換純色填色與網點填色，選取工具可切換矩形・套索・自動選取，手指工具可切換模糊與馬賽克，快速切換工具可編輯已登記的內容，這些都在長按或上滑之後。雙擊圖示時，畫面下方會顯示該工具的簡短說明。\\n在畫布上，雙指捏合可縮放，雙指拖曳可平移，雙指點擊復原，三指點擊重做。雙擊畫面左右邊緣可移動到前後一格。\\n連接滑鼠或繪圖板時，可用滾輪縮放、按住中鍵拖曳平移。","help.entry1.title":"筆工具","help.entry1.desc":"在畫布上繪製線條的基本工具。長按可變更筆刷種類・粗細・顏色（雙擊顯示簡易說明）。支援數位板/液晶數位板的筆壓與傾斜，於設定畫面的「筆輸入」中調整筆壓曲線，可細緻自訂筆壓的反映方式（輕壓時粗細/不透明度會有多少變化）。切換筆的子工具後，還能以同一支筆工具進行貼網點・放置印章。","help.entry2.title":"橡皮擦工具","help.entry2.desc":"與筆工具相對，用來擦除已繪製的內容。與筆刷一樣可以調整粗細與不透明度，淡出、筆畫衰減等筆刷設定也同樣適用。它進行的是「擦除」既有繪製內容，而不是在圖層的透明部分「加畫」，因此下方圖層會透出顯示。","help.entry3.title":"油漆桶工具","help.entry3.desc":"一次性填滿被包圍的區域。在線稿所圍成的區域內點擊，整個區域就會被填滿為目前選擇的顏色（或網點）。若線稿有縫隙，顏色可能會擴散到意料之外的範圍，因此使用前請確認線稿是否已完全封閉。可在設定中切換純色填滿/網點填滿。 詳細設定（容差・擴張px・潛入線稿下方）可在設定畫面的「油漆桶填色」中調整。","help.entry4.title":"套索填色","help.entry4.desc":"用手指沿想要包圍的範圍畫出多邊形區域，然後一次性填滿其內部的工具。與油漆桶不同，即使線稿有未封閉的部分，也可以自行指定要包圍的範圍，因此適合形狀複雜或線條中斷處的上色。開啟「填滿封閉區域」後，會像油漆桶一樣一次填滿套索內所有由線條封閉的區域，無論有多少個（套索與畫之間的空白不會被填滿）。","help.entry5.title":"滴管工具","help.entry5.desc":"擷取點擊位置的顏色並將其設為繪圖色的工具。它擷取的是畫面上實際顯示的所有圖層合成後的顏色，因此即使在多個圖層重疊的部分，也能準確取得「肉眼所見的顏色」。","help.entry6.title":"選取工具","help.entry6.desc":"選取畫布的一部分範圍，僅對所選範圍進行移動・旋轉・縮放的工具。長按可以從「矩形選取」「套索選取（自由形狀包圍）」「自動選取（魔術棒，自動合併相近顏色的範圍）」三種選取方式中選擇。選取中會在畫布上顯示表示所選範圍的框線，在取消選取之前，所有影格・所有圖層都會固定顯示相同的範圍。在套索選取中開啟「吸附到線條」後，會像油漆桶填色一樣查看線稿劃分出的區域，只選取大部分位於套索內的區域。選取範圍的邊緣會精確沿著線稿的外緣，圍住這些區域的線條和內部的線條也會一併選取（從輪廓向外延伸的線條會在輪廓處截斷）。上色的面也會像油漆桶填色一樣依顏色視為各自的區域，因此在有上色和線條的圖層上也能依畫的形狀選取。線條中不超過「線條間隙容差」寬度的斷口會視為相連。套索內沒有線稿時，按圈出的形狀原樣選取。線稿取自選取參照（「僅工作圖層」／「所有可見圖層」）。","help.entry7.title":"手指工具（扭曲工具）","help.entry7.desc":"沿手指劃動的方向推擠像素使其扭曲，營造出用手指塗抹濕顏料般的效果。相較於精細修正，更常用於將已畫好的線條進行有機的扭曲以增添表現力。","help.entry8.title":"圖形工具","help.entry8.desc":"一鍵繪製直線・矩形・圓形等精確圖形的工具。從起點拖曳到終點時會即時預覽，放開手指即可確定。在難以徒手畫出直線或正圓時非常方便。","help.entry9.title":"文字工具","help.entry9.desc":"在畫布上放置文字的工具。可選擇字型・大小・顏色・直排/橫排。直排時還支援半形英數字的自動旋轉・縱中橫（數字保持橫向排列的表記）・注音標示（類似日文振假名的讀音標示）。放置的文字在匯出時也會作為像素燒錄進畫面。 可新增・搜尋・刪除文字工具可用字型的畫面。除初始內建字型外的其他免費字型，為控制初始安裝容量，需從此處按需下載。","help.entry10.title":"快捷工具管理","help.entry10.desc":"登記一組常用工具組合，只需點一下即可依序切換。長按或向上滑動可開啟管理彈出視窗，編輯已登記的內容和順序。","help.entry11.title":"快速切換工具","help.entry11.desc":"預先登記常用的畫筆・工具組合，只需點擊一個按鈕即可依序切換。長按或向上滑動畫布上的↺按鈕，即可開啟可以新增、排序、刪除的管理彈窗。可透過拖曳改變順序。","help.entry12.title":"印章工具","help.entry12.desc":"像筆刷一樣把已登錄的圖像放到畫布上，可重複使用速度線、背景圖樣與小道具而無需重新繪製。像素模式使用與像素畫濾鏡相同的 Pixel Art 處理，在像素化與減色時維持清晰的透明邊界。馬賽克是獨立效果，不用於印章像素模式。印章面板還可調整旋轉角度與大小。","help.entry13.title":"畫筆","help.entry13.desc":"長按畫筆工具，可以從一般繪圖切換到網點填色或印章放置等子工具。不用每次切換工具，就能用同一支筆在多種作業之間來回操作。","help.entry14.title":"變形選取範圍","help.entry14.desc":"用選取工具圈出的範圍，可以在畫布左下方的「移動」「縮放」「旋轉」按鈕中選擇模式，再於選取範圍內拖曳進行變形。適合用來調整誤畫部分的位置，或只放大強調某一部分。按同一列的「全選」會把目前圖層整體變成選取範圍，因此整個圖層的移動、旋轉、縮放也能用同樣的方式完成（原先獨立的「變形工具」已整合到這裡）。若想單獨拖曳各個網格點做出更自由的變形，請使用同一列的「自由變形」「網格變形」。","help.entry15.title":"自由變形・網格變形","help.entry15.desc":"從畫布右上角的編輯/設定選單開啟的、以整個圖層為對象的變形工具。與選取範圍變形不同，不需要選取範圍，可以用手指單獨拖曳角點或網格點做出自由的變形。控制面板的分割數滑桿最多可將網格細分為10×10，用兩根手指同時捏住不同的點，即可直覺地進行旋轉、縮放操作。","help.entry16.title":"取色器","help.entry16.desc":"可在同一畫面中切換HSV與RGB來選色的取色器。調色盤功能可儲存、叫出正在使用的配色組合。調色盤也可以透過檔案匯出或QR code與其他裝置共享。","help.entry17.title":"筆刷收藏","help.entry17.desc":"點擊筆刷清單中筆刷上的星形圖示即可加入或取消收藏（與應用程式內其他收藏功能——自動上色設定、圖章、字型、繪圖濾鏡等——操作方式相同）。清單頂部的星形圖示還可以篩選為僅顯示收藏項目。已收藏的筆刷不會被誤刪。","help.entry18.title":"自訂筆刷","help.entry18.desc":"在筆刷清單中長按預裝筆刷並選擇「複製」，即可基於它建立專屬自訂筆刷。複製後的筆刷可以自由編輯粗細、不透明度、硬度、旋轉、密度、散佈、模糊半徑等參數，不需要時也可以刪除（預裝筆刷本身無法編輯或刪除）。用畫布上的滑桿調整的粗細和不透明度會依筆刷分別記住，預裝筆刷也一樣，並可以從清單的選單恢復為預設值。還可以用資料夾分類，或用星標圖示收藏。","help.entry19.title":"筆刷折返","help.entry19.desc":"在筆刷設定中開啟「描邊」後即可使用「折疊模式」。關閉時與一般描邊筆的繪製完全相同。開啟後，描邊筆的線條本身會依照所畫筆畫的方向與彎曲而折疊、捲曲；它不會自動產生波浪。每個彎曲處都會出現一條從內側輪廓分出、彎曲後漸漸消失的折返線。若筆畫持續朝同一方向轉動，每轉270°會加入一條較含蓄的折返線。折疊類型有5種。「波浪俯視」讓先畫的一側在前，「波浪仰視」讓後畫的一側在前。「右捲」依照朝筆畫前進方向右側捲入的方式決定前後，「左捲」則朝左側；依據的是所畫方向而不是螢幕方向。「月牙捲」會沿著所畫的C形曲線整理成相連的月牙形。「折返長度」調整折返線的長度（與筆刷大小連動），「折返角度」調整跟隨筆畫彎曲的強度（50%時自然連動），「折返線的彎曲起點」調整材質看起來的厚度（0%時從分岔處立即彎曲）。描邊筆的筆壓與淡出（入筆與收筆）只改變包含描邊在內的整體形狀，描邊線的粗細與顏色都不會改變。關閉「描邊」中的「保持重疊」後，重疊的筆畫在交界處不描邊而連成一體（重疊處也不畫折返線），只描整體的外圍。開啟「描邊」中的「強弱」後，描邊線會朝筆畫中每段曲線的頂點變粗（曲線的起點和終點保持描邊寬度，到頂點逐漸變為「頂點處的描邊寬度」，抬起筆時生效）。","help.entry20.title":"圖層","help.entry20.desc":"將一塊畫布分成多個透明「圖層」來繪製的機制。將線稿、上色、背景等分別繪製在不同圖層上，之後可以只重做上色，或在不擦除線稿的情況下更換背景。畫面中，疊得越靠上的圖層顯示在越靠前的位置。每個圖層行的圖示可一鍵刪除或與下方圖層合併，圖層面板頂部的圖示還可以一次性合併所有可見圖層。","help.entry21.title":"混合模式","help.entry21.desc":"用於變更圖層與下方圖層的合成方式，常用於疊加網點或顏色效果的圖層。\n正常：直接疊加。\n色彩增值：與下方圖層相乘後變暗，是陰影表現的經典手法。\n濾色：疊加亮度後變亮，適合表現光效。\n覆蓋：暗部更暗、亮部更亮，增強對比度。\n相加（發光）：直接相加顏色，適合光效線條等。\n差異化減去：相減顏色，呈現暗沉的效果。\n變暗：取上下兩圖層中較暗的顏色。\n變亮：取上下兩圖層中較亮的顏色。\n顏色加深：使下方顏色變暗並加深發色。\n顏色減淡：使下方顏色變亮並加深發色。\n實光：比覆蓋更強烈的對比效果。\n柔光：比覆蓋更柔和的對比效果，適合柔和的陰影。\n差異化：顯示上下兩色的差異，可用於檢查顏色偏差等。\n色相、飽和度、顏色、明度：分別僅將該圖層的色相、飽和度、色彩或明度反映到下方圖層。\n線性加深：將上下顏色相加後減去基準值，產生更強的變暗效果。\n線性減淡：線性相加上下顏色使其變亮。與「相加（發光）」是不同的混合模式，圖層半透明時「相加（發光）」會更亮。\n亮光：依上層顏色在加深與減淡之間切換，產生很強的對比。\n線性光：依上層顏色線性提高或降低亮度。\n小光源：依上層顏色向較暗或較亮一側替換。\n實色疊印混合：對亮光結果套用閾值，形成強烈的原色分離。\n排除：比「差異化」更柔和的反相與差異效果。\n劃分：用上層顏色除下層顏色，可用於提亮校正和強調色差。\n在混合模式列表中，每種模式旁會顯示將紅、黃、藍、白、黑疊加在由暗到亮的顏色上的範例（範例下方為半透明疊加時的效果）。","help.entry22.title":"剪裁遮罩","help.entry22.desc":"使繪製內容僅限於緊鄰下方圖層的不透明像素範圍內的功能。當想要在不超出線稿的範圍內上色時，於線稿圖層上方新增上色圖層並啟用剪裁遮罩，就不必擔心不小心畫到線稿外面。","help.entry23.title":"共用圖層","help.entry23.desc":"一般圖層依每個影格獨立存在，而共用圖層則是在多個影格・場景中共享同一內容的圖層。像背景這類不隨影格變化而移動的元素，無需每格重新繪製，只需畫一次即可。在時間軸上會以專用軌道的形式顯示。 可以把一般圖層轉換為共用圖層（在多個影格中持續顯示相同內容的圖層）的功能。也可以先把目前顯示的圖層合併為一張，再進行共用化。想反覆使用背景等每影格內容相同的部分時，可以省去重新繪製的麻煩。","help.entry24.title":"圖層多選・批次操作","help.entry24.desc":"使用圖層面板的選取模式，可以用勾選框一次選取多個圖層進行合併或批次刪除。合併只能在一般圖層、自動上色用線稿、自動上色圖層之間進行（共用圖層、資料夾、時間軸素材不能合併）。","help.entry25.title":"圖層資料夾","help.entry25.desc":"可以把多個圖層整理到資料夾中的功能。即使是部件較多的插畫，也能讓圖層面板保持清晰易看。剪裁無法跨資料夾套用，如果要使用剪裁，建議把相關圖層放在同一個資料夾內。","help.entry26.title":"自動上色","help.entry26.desc":"在自動上色專用線稿圖層下方建立自動上色圖層，並依據預先製作的「自動上色設定」（各部位的顏色、網點組合）自動進行上色的功能。由於可以在畫完線稿後一次性上色，能大幅減少需要反覆繪製同一角色的手繪動畫中的上色工作量。重新繪製線稿後，時間軸和圖層面板會顯示更新標記，提示需要重新執行自動上色。在時間軸畫面的三點選單中選擇「執行自動上色」，即可一次性重新計算所有帶有更新標記的自動上色圖層，省去重新繪製線稿後逐個圖層在圖層面板中執行的麻煩。自動上色設定的每個部位都有關於如何處理線稿顏色的設定（指定顏色、與填充色相同、色彩描邊）。選擇色彩描邊（貼合線稿）後，線稿顏色會按HSL偏移以符合填充色，使線條不顯突兀、自然融合。設定越積越多，分配部位時顯示的清單就會變長、難以瀏覽。可以在專案設定（或圖層面板的部位分配對話框）中，將清單篩選為只顯示本專案使用的設定，讓清單更簡潔、更易於挑選。「填補線稿與填色之間的縫隙」調大後，會填色到線條較淡的邊緣下方，外框或線稿顏色與填充色相同時可見的線稿與填色之間的縫隙會變小。","help.entry27.title":"漸層上色（自動上色設定）","help.entry27.desc":"自動上色設定的每個部位不僅可以使用單色，還可以設定漸層。可拖曳的對稱控制點讓你直覺地調整漸層的範圍和角度。每個部件還可以設定「用指定顏色描邊」。勾選後，會在填色範圍的最外側（緊貼線稿的部分）畫出指定顏色和粗細的線條。描邊顏色可透過取色器自由選擇，粗細可透過滑桿、±按鈕或點擊數字直接輸入來調整。設定項上方會顯示預覽，可以在實際執行自動上色之前確認顏色和粗細。","help.entry28.title":"場景操作","help.entry28.desc":"在時間軸的場景標籤頁中，可以新增、複製、刪除、重新命名、重新排序場景。切換到多選模式後，還可以一次移動、複製、刪除多個場景。","help.entry29.title":"洋蔥皮","help.entry29.desc":"將目前編輯影格前後的影格以半透明方式疊加顯示，讓你可以一邊確認動作的連貫性一邊繪製的功能。可以在效能設定中調整顯示的影格數（前後各顯示幾張）以及顏色・透明度。","help.entry30.title":"尺規","help.entry30.desc":"直線・圓・橢圓・透視尺規（使用消失點的透視圖法專用尺規）等，用於輔助繪製徒手難以畫出的精確線條的功能。放置的尺規會使筆尖自動吸附，即使是沒有尺規就難以繪製的具有縱深感的構圖也會更容易畫出。尺規可以透過操作控制點進行移動・旋轉・調整大小。魚眼透視尺規是五點曲線透視：在鏡頭圓內，橫線和豎線彎成圓弧，縱深方向的線匯聚到中心。筆畫會沿著與開始繪製方向相符的線條，拖曳控制點可移動中心、改變半徑（圓右側的點）和傾斜（圓上方的點）。","help.entry31.title":"淡出","help.entry31.desc":"可分別獨立設定入筆（筆畫起點）與收筆（筆畫終點）的數值和距離的筆刷功能。可以只調整起點、只調整終點，或使用非對稱設定，分別控制兩端的粗細與不透明度。描邊筆只改變整體形狀（粗細），不改變不透明度。","help.entry32.title":"筆畫衰減","help.entry32.desc":"與淡出類似，但更接近「墨水逐漸用盡」的表現，繪製越久顏色越淡或越乾澀的效果。可重現毛筆或麥克筆持續書寫時墨水耗盡般的質感。","help.entry33.title":"混色","help.entry33.desc":"使用筆刷上色時，將筆刷正下方已有的顏色與即將塗上的選定顏色混合後再繪製的功能。可在筆刷設定的混色模式中選擇：不混合直接上色的「數位」、像顏料一樣混合並把沾到的顏色拖開的「油畫風混色」、疊加透明顏料且乾後顏色聚集在邊緣的「水彩風混色」。","help.entry34.title":"筆壓曲線","help.entry34.desc":"筆輸入設定中的功能，可透過圖表自由調整實際筆壓強度與筆刷粗細・不透明度反映方式之間的關係。無論是希望輕壓也能畫出粗線的人，還是相反希望必須用力按壓才會變粗的人，都能依自己的用筆習慣細緻自訂畫感。變更設定後可當場試畫確認效果。","help.entry35.title":"網點上色","help.entry35.desc":"在填色工具的設定中把純色填滿切換為網點填滿，就能用選中的網點、線條等網點圖案進行填滿。還提供像素模式專用的方格紋、格子紋網點，可以做出符合像素畫質感的上色效果。荷葉邊、針織紋理、褲襪等手繪起來很費工夫的細緻花紋也能輕鬆畫出。還可以自製原創網點並新增使用，或與其他使用者分享。","help.entry36.title":"像素模式","help.entry36.desc":"筆刷、字型、印章各自都提供的設定，開啟後會去除反鋸齒，呈現清晰的像素畫風輪廓。想刻意做出老遊戲般的質感，或想營造低解析度效果時使用。配色方式可從「不指定顏色」「指定顏色」「指定顏色數」「從調色盤選擇」4種中選擇，也可以使用像素畫專用調色盤。","help.entry37.title":"作畫區域","help.entry37.desc":"可以在比匯出範圍更大的區域內作畫的設定。畫布上會顯示表示匯出範圍的紅色邊框，畫到邊框外的部分不會被匯出，但可以為之後用推拉鏡頭等運鏡方式調整所展示的範圍留出餘地。在新增專案時設定放大倍率。","help.entry38.title":"畫布背景色","help.entry38.desc":"可以設定專案畫布的背景色。使用透明匯出（透明WebM）時背景色不會影響匯出結果，但可以改成自己喜歡的顏色，方便作畫時檢視。","help.entry39.title":"時間軸","help.entry39.desc":"管理動畫時間軸的畫面。將影格（單張靜止影像）排列並像翻頁動畫一樣播放，就形成了動畫。文字・圖片・影片・音訊素材軌道、共用圖層軌道、攝影機關鍵影格也都在同一條時間軸上管理。文字・圖片・影片與影格插畫之間的前後關係可在「疊放順序」中依整個場景或指定的影格範圍調整。也可以長按項目進行多選，一起移動。","help.entry40.title":"場景","help.entry40.desc":"將一個專案（一段影片）內部按場景（分鏡）劃分管理的功能。資料夾是以專案為單位進行整理，而場景則用於表現一段影片內部的場景轉換。在時間軸的場景標籤中可以新增、複製、刪除、重新命名、重新排序場景。切換到多選模式後，還可以一次性移動、複製或刪除多個場景。","help.entry41.title":"影格操作","help.entry41.desc":"在影格清單中，除了新增、複製、刪除之外，還可以在多選模式下一次移動、複製、刪除多個影格。增加保留格數可以讓同一影格持續顯示多個格子（即所謂的「停格」），從而在動作較少的鏡頭中節省作畫張數。","help.entry42.title":"素材片段（文字・圖片・影片・音訊）","help.entry42.desc":"放置在時間軸文字、圖片、影片、音訊軌道上的片段。長按拖曳片段本身可移動其起始位置，拖曳兩端的把手可改變使用範圍（長度）。同一時間重疊的素材會自動放到其他列。點擊文字・圖片・影片片段，會在預覽下方開啟編輯面板：可修改文字內容・字型・顏色・描邊，位置・縮放・X軸／Y軸／Z軸旋轉・不透明度（也可在預覽上拖曳，新增關鍵影格即可產生動畫），遮罩（矩形・橢圓・羽化・反轉）以及所在列，也可在此複製或刪除。音訊片段在詳細面板中調整音量和淡入淡出。","help.entry43.title":"素材清單","help.entry43.desc":"可以統一檢視專案中使用的圖片、影片、音訊素材的畫面。放置在時間軸上的素材的原始檔案都彙集在這裡。","help.entry44.title":"音量調整","help.entry44.desc":"放置在時間軸上的音訊片段，可以在詳細面板中調整音量、淡入、淡出的秒數。可用來調整音效和配樂的音量平衡，或讓曲子的開頭、結尾更加順暢。","help.entry45.title":"攝影機關鍵影格","help.entry45.desc":"在時間軸上的特定位置記錄攝影機的位置・縮放比例・旋轉角度的功能。關鍵影格之間會自動平滑內插，因此可以輕鬆加入平移（橫向移動）或拉近拉遠等鏡頭運動。","help.entry46.title":"演出濾鏡","help.entry46.desc":"可套用於場景或影格的畫面效果（模糊・色調校正・光暈・像素畫等）。在不改變手繪畫面本身的前提下，作為演出手段調整整個畫面觀感時使用。繪畫濾鏡中的色調曲線（預設與強度）・色階・銳化・USM銳化・暗角（顏色・範圍・濃度）・水彩邊界也收錄在演出濾鏡中，可以一次對多個影格套用相同的效果。像素畫也可以選擇配色方式（不指定顏色・指定顏色・指定顏色數・從調色盤選擇）。限制顏色時，單用一種顏色與原色相差較遠的地方，會用可用顏色中的兩到三種按規則排列（混色抖動）來接近原色，這種排列在影格之間不會移動；輪廓處保持清晰。混色抖動可以用開關開啟或關閉，關閉後用最接近的一種顏色填色。 演出濾鏡可以疊加套用多個，其套用順序依照時間軸上的排列順序。拖曳濾鏡清單重新排序後，實際反映到畫面上的順序也會隨之改變。 一種演出濾鏡，會逐影格改變類似膠片顆粒感的雜訊。可以用滑桿調整強度、數量（雜訊出現的密度）和顆粒大小。回到同一影格時雜訊形態相同（拖曳時不會閃爍），播放時顆粒則會呈現出跳動的效果。 用來表現畫面中降雨的演出濾鏡。可以用滑桿調整降雨強度（雨滴數量）、速度、雨滴大小和風向角度。每滴雨都會隨著影格數推進以固定速度持續落下，呈現自然的降雨效果。","help.entry47.title":"繪圖濾鏡","help.entry47.desc":"直接套用於所選圖層的濾鏡（演出濾鏡作用於整條時間軸或整個場景，而繪圖濾鏡按圖層生效）。內建26種濾鏡：高斯模糊、鏡頭模糊、動畫風、色調曲線、色階、外框、銳化、USM銳化、暗角、復古動漫、老電視、二值化、魚眼鏡頭、色差、眼鏡斷層、像素畫、質感變換、背景融合、積墨、自動線稿、稜鏡、色彩反轉、馬賽克、雜訊、球體陰影和水彩邊界。水彩邊界會讓作業圖層上塗色部分的邊緣聚集顏色、內側變得通透，就像乾了的水彩（開啟「顏色交界處也添加」後，相鄰顏色的交界處也會出現邊緣）。動漫風格會減少顏色數，並在相鄰顏色之差達到「顏色差閾值」以上的邊界上，於較暗的一側畫出「邊界線粗細」的線（線稿的線條不會變粗）。稜鏡會把圖層上每個形狀分別塗上彩虹六色（紅、綠、青色、藍、紫、紅）並模糊，再把圖層設為線性減淡。先在單獨的圖層上用深色畫出細小的葉片狀形狀再使用，畫面上就會出現柔和的彩虹光痕（模糊量與一般的高斯模糊採用相同標準）。球體陰影會在橢圓形光的內側疊加光色、外側疊加陰影色，且只加在已繪製的地方（也可以在畫布上拖曳光）。外框不會改寫原圖層，只會把結果繪製到新圖層。眼鏡斷層只對用面板的「畫筆」「油漆桶」在畫布上塗抹的範圍（可用「橡皮擦」修改）套用類似強力眼鏡鏡片的局部變形（如果有選取範圍或選取圖層，會從該範圍開始）。畫布上有選取範圍時，繪圖濾鏡只套用於選取範圍內。像素畫還可選擇配色方式（不限制、指定顏色、指定顏色數或從調色盤選擇）。限制顏色時，單用一種顏色與原色相差較遠的地方，會用可用顏色中的兩到三種按規則排列（混色抖動），使其更接近原色；輪廓處不混色，保持清晰。指定顏色數時，會從佔畫面大部分的顏色中選取。混色抖動可以用開關開啟或關閉，關閉後用最接近的一種顏色填色。大小可在「指定色塊大小」（1～100共100級）和「指定點數」（橫向・縱向點數滑桿，最左為1，最右為畫布尺寸）之間切換，橫向和縱向會在維持畫面長寬比的同時一起變化，兩種指定方式也會連動。兩種方式下點都維持正方形，不會產生半透明的邊緣。 自動線稿可在套用濾鏡前直接編輯暫時Vector控制點。拖曳控制點時只移動該點。選擇「套用」右側的「新增控制點」後點擊線條可新增控制點，選擇「刪除控制點」後點擊控制點可將其刪除（兩者都未選擇時點擊控制點，會先確認再刪除）。編輯後的形狀會直接用於最終套用結果，控制點的移動、新增和刪除也可以用濾鏡編輯的復原・重做逐一還原。 色調曲線中，輕點曲線上的空白處可新增點，拖曳點可移動，長按可刪除；R、G、B 各顏色的曲線在 RGB 曲線之後套用。色階也可按 R、G、B 分別調整，伽瑪可改變中間調的亮度。描邊的「向內延伸」可將邊緣擴展到原輪廓內側，描邊的新圖層會放在原圖層的正下方。色差可指定將偏移分配到 X（橫向）、Y（縱向）、Z（從中心向外）各多少。魚眼鏡頭的中心和半徑也可以在畫布上拖曳 ＋ 和圓上的控點來變更。暗角會柔和地壓暗整個畫布的四個角（沒有繪畫的透明處也會有陰影）。可用「範圍」調整從四角向中心壓暗到多遠，用「濃度」調整四角的暗度。眼鏡斷層像真正的高度數眼鏡一樣，讓透過鏡片看到的景物朝鏡片中心均勻縮小（負值，近視用）或放大（正值，遠視用），並在鏡片邊緣使輪廓錯開成台階狀。積墨只積在線條以「最大角度」或更小角度相交處（初始值90°時為銳角和直角：V字、交叉的窄側、T字、方角）的夾角內側，更寬的角不積：在相交點從線條邊緣起為「中央寬度」，再朝「範圍」的末端筆直變細，末端為0px，平滑地收成尖端（即使加大「中央寬度」，也不會鼓出連接兩側積墨末端的直線之外，最寬時中間也是平的）；若線條在範圍內中斷，該線條上的積墨會以中斷處為終點細到0px（每條線的長度可以不同），此時兩處積墨仍會在夾角的正中相接，距兩條線的寬度相同（較長線條的積墨從那裡再細到範圍的末端）。自動線稿沿草稿線條的中心描出細線。靠得很近的線條只要中間有一點空隙，就仍畫成兩條線，只填補線條內部的小白點。兩條線靠攏並貼在一起的地方，不會在中間畫成一條線，而是像草稿一樣兩條線逐漸靠近並合在一起。線條交叉或重疊的地方，也會像草稿一樣讓每條線照原樣延續（不會在交點處折彎，重疊的兩條線也不會融成一條）。以較淺角度斜向交叉的線也會筆直地穿過交叉處，僅相互接觸的線（例如沿著頭部畫的頭髮輪廓）則各自留在自己的一側，仍是分開的線。眼睛之類的點會畫成實心的點。比「草稿線寬」短的分岔不繪製。「起筆收筆」可以用開關開啟或關閉，關閉後線條直到末端都保持相同粗細。背景融入以混合模式「實光」疊加背景的光與影（影子的顏色不是黑色或灰色，而是把背景中陰影部分的顏色壓暗後的顏色）。周圍的顏色以「覆蓋」疊在整幅畫上來統一色彩方向，從下方反上來的光和周圍的反射光以「濾色」加入，霓虹燈之類的強烈有色光以「相加（發光）」加在輪廓上。「匹配背景的明暗與色調」會把比背景過亮或過於鮮豔的顏色拉回背景的範圍，並讓暗部、中間調、亮部分別帶上背景中相同明度的色調（線稿的黑色保持不變）。「模糊程度」是取色前模糊背景的程度。","help.entry48.title":"自訂自動操作（操作錄製）","help.entry48.desc":"將在畫布或時間軸上進行的支援操作錄製為命名步驟，以便重複執行。從「自動操作」新增項目開始錄製，停止後可在檢查畫面調整步驟順序或刪除步驟，再進行儲存。已儲存的自動操作可以重新命名、重新錄製、刪除、僅篩選收藏項目，還能以JSON檔案匯出和匯入。僅包含畫布操作且全部錄製於同一影格的自動操作，可在執行時選擇目前影格、指定影格範圍或所有影格。時間軸自動操作以及跨越多個影格的錄製不會顯示影格範圍選項。","help.entry49.title":"圖層關鍵影格（分部件動畫）","help.entry49.desc":"依影格設定每個圖層的位置・縮放・旋轉，關鍵影格之間會自動內插。攝影機關鍵影格移動的是整個畫面，而這個功能只移動單一圖層。由於自動上色的每個部件都會生成為獨立的圖層，因此可以直接用它來做分部件動畫（只動一隻手臂、只讓嘴巴開合等）。每個關鍵影格還可以單獨設定「等速」「緩入」「緩出」「緩入緩出」「彈跳」這類緩動（與下一個關鍵影格的銜接方式），不僅限於單調的等速移動，還能表現出彈跳般的動作。在圖層面板的三點選單「動畫（關鍵影格）」中設定。圖層本身的畫面內容不會改變，只是顯示位置改變的非破壞性變形。這個功能只影響時間軸的顯示（預覽・匯出），不會影響畫布模式下的實際作畫。","help.entry50.title":"圖層群組（把多個部件一起移動）","help.entry50.desc":"用同一組關鍵影格把多個圖層一起移動的功能。例如「手臂」由皮膚、袖子兩個自動上色部件組成時，把這兩個圖層分到同一群組後，只需一次關鍵影格操作就能讓它們一起移動。在圖層面板中多選（勾選框）圖層，再點擊底部工具列的「群組化」圖示即可建立。群組的運動會疊加在每個成員圖層自身的關鍵影格（如果設定了的話）之上，因此可以把群組整體的運動和單一圖層的微調結合起來使用。一個圖層同時只能屬於一個群組。","help.entry51.title":"EndCard（片尾標誌）","help.entry51.desc":"匯出影片時，會在正片結尾自動加入的NIARIM標誌短片（約5秒）。免費版無法隱藏或刪除，但成為Premium會員後可以開關顯示・變更長度・進行替換。","help.entry52.title":"自動儲存","help.entry52.desc":"專用於當機或檔案損毀時復原的儲存。每次繪圖等發生變更時都會自動儲存，最多保留3份，依由舊到新的順序覆寫。它與手動儲存（儲存槽・儲存樹）完全分開管理，不能取代一般儲存。僅在App異常結束後重新啟動時，才會詢問是否要復原。","help.entry53.title":"儲存槽","help.entry53.desc":"在固定數量的儲存位（槽）中，由自己選擇儲存位置進行儲存的方式。槽位數量由設定決定（低畫質5個・中畫質10個）。由於每次都需要自己選擇要覆寫的槽位，適合「想保留這個時間點的狀態」這類管理方式。","help.entry54.title":"儲存樹","help.entry54.desc":"每次儲存都會建立一個新的儲存點，並可以從過去的儲存點分支出另一段歷史（分叉）的儲存方式。沒有數量上限，適合「想回到那個版本後再嘗試另一種發展」這類用法。畫面上儲存點會以從下往上生長的樹狀圖形式顯示。","help.entry55.title":"資料夾","help.entry55.desc":"將專案（作品）分組整理的功能。支援多層級結構，因此也可以用來統一管理同一作品的多個話數或系列作品（例如：在「作品名」資料夾中依序排列「第1話」「第2話」……等專案）。若想在一部動畫內劃分場景，請使用畫布畫面中的「場景」功能，而不是資料夾。","help.entry56.title":"垃圾桶","help.entry56.desc":"已刪除專案暫時移動到的地方。在被永久刪除之前，都可以從這裡復原。可以在設定中指定自動刪除的天數（關閉/30天/60天/90天）。","help.entry57.title":"共享（.niashare）","help.entry57.desc":"用於將專案傳遞給他人（或自己的其他裝置）的專用共享檔案格式。接收方開啟此檔案後，會複製並新增到自己的專案列表中。共享來源的.niashare檔案本身不會被變更。","help.entry58.title":"資料轉移（.niatra）","help.entry58.desc":"將設定、素材、筆刷、自動上色設定、主題、調色盤（取色器・像素畫專用）等整個應用程式環境一次性轉移到其他裝置的功能。可以透過核取方塊個別選擇要轉移的項目，還可以選擇性地一併包含製作中的專案（所選專案會連同素材、字型一起完整轉移）。如果只想傳遞單一專案，也可以改用「共用（.niashare）」。","help.entry59.title":"影片匯出（MP4・WebM・GIF・AVI）","help.entry59.desc":"將作品匯出為通用MP4影片。免費版可匯出的長度有上限（90秒），且會在影片結尾自動加入片尾卡（應用程式Logo）。 可在保留Alpha色版（背景透明部分）的情況下匯出的影片格式。僅在支援的播放環境中才能透明播放。適合作為素材疊加到其他App中使用。 匯出為動畫GIF。由於會自動循環播放，適合在社群媒體上輕鬆分享的場景。 如果更重視相容性，也可以匯出為AVI（Motion JPEG）。不支援Alpha色版（透明），部分裝置上App內預覽可能無法使用（此時仍可透過「分享」用外部播放器播放）。 免費會員的專案長度上限為90秒（付費會員為2小時）。如果新增或複製影格會超過上限，在點擊按鈕的瞬間就會顯示提示對話框，因此實際上不會超過90秒。","help.entry60.title":"匯出畫面","help.entry60.desc":"在「預設」中選取「標準」「高畫質」或「自訂」。選取「自訂」後，可以調整影格率（FPS）。匯出影片、圖片期間會顯示進度，也可以中途取消。所需時間會依裝置效能而異。","help.entry61.title":"作品廣場","help.entry61.desc":"可以將動畫・插畫作品以YouTube影片的形式發佈到社群，並瀏覽其他使用者的作品。可以切換「最新」「排行榜」「追蹤」三個分頁，也可以依作品標題或投稿者名稱搜尋。切換到標籤搜尋模式後可依標籤篩選作品，標籤不僅投稿者本人，其他使用者也可以自由新增或刪除（投稿者鎖定的標籤只能由投稿者本人解鎖），點擊標籤即可篩選出相同標籤的作品。點擊作品卡片會開啟可拖曳、可調整大小的浮動預覽視窗，可以在繼續操作其他畫面的同時觀看。點擊「查看詳情」按鈕可開啟作品詳情畫面（投稿者、發佈日期、標籤編輯、收藏、轉發等）。點擊投稿者名稱旁的「追蹤」按鈕即可將其加入追蹤清單，「追蹤」分頁會依時間順序彙整顯示該作者的作品。有人追蹤你時，會顯示在畫面右上角鈴鐺圖示的通知清單中。你可以分別設定自己的追蹤清單/粉絲清單是否對所有使用者公開（預設為非公開），也可以查看已公開的其他使用者的清單。除自己發佈的作品外，都可以用「轉發」按鈕轉發；當追蹤的作者轉發了他人的作品時，該作品也會以「發佈日期」和「轉發日期」中較新的一方為基準，混入「追蹤」分頁中顯示（卡片上會顯示「○○轉發了」）。收藏的作品會彙整顯示在主畫面的「已收藏」分頁中，也可以在投稿者作品清單畫面的「收藏」分頁中查看。可以設定自己的收藏清單是否對其他使用者公開（預設不公開），也可以查看已設為公開的其他使用者的收藏清單。對不當作品可以附上理由進行檢舉，檢舉送出後會詢問你是否要封鎖該投稿者。直向影片可以在「直向模式」中連續播放觀看。每日可發佈的作品數量有上限，免費會員每天1個，進階會員每天3個。點擊畫面右上角的顯示篩選按鈕（帶斜線的眼睛圖示），可以隱藏不想看到的作品。除了可以隱藏「包含生成式 AI 圖像或影片」的作品外，還可以透過「新增」逐條登錄只比對作品標題的隱藏標題關鍵字，以及只比對作品廣場標籤的隱藏標籤。可用編輯圖示修改或垃圾桶圖示刪除，無需輸入逗號或 #。這些篩選適用於「最新」「排行榜」「追蹤」（含轉發）、直向模式、投稿者頁面、作品詳情和收藏。「包含生成式 AI 圖像或影片」由投稿者在發佈時自行聲明，發佈後也只有投稿者本人可以變更（可在「我的投稿」或作品詳情畫面中變更）。","help.entry62.title":"重新編輯浮水印","help.entry62.desc":"點擊放置在時間軸共用圖層軌道上的浮水印，隨時可以重新編輯其角度、大小、不透明度、顯示範圍（循環顯示）。不僅在登記時，在專案中實際使用時也能隨時細部調整。","help.entry63.title":"浮水印","help.entry63.desc":"可以在匯出的影片・圖片上加入自己簽名或Logo作為浮水印的進階會員專屬功能。可以調整位置、大小、不透明度。點擊時間軸共用圖層軌道上放置的浮水印，隨時都能重新編輯其角度、大小、不透明度、顯示範圍（循環顯示）——不僅是首次設定時，在專案中實際使用時也能隨時細緻調整。 新增浮水印時，請在時間軸的「新增素材」選單中選取「＋浮水印」。","help.entry64.title":"Premium","help.entry64.desc":"成為進階會員後，免費版限制的90秒影片長度將延長至最長2小時，並可移除每支影片結尾自動加入的片尾卡（應用程式Logo）。同時廣告也會隱藏，還可使用浮水印、色調曲線、色階校正功能。","help.entry65.title":"首頁","help.entry65.desc":"啟動App後最先顯示的畫面，可在專案、共用、作品清單、垃圾桶各標籤間切換檢視。右上角的搜尋圖示可依專案名稱篩選。在專案標籤頁中，可透過懸浮按鈕選擇新增專案或新增資料夾。","help.entry66.title":"新增專案","help.entry66.desc":"在建立專案前，統一設定畫布尺寸、fps、長度（以秒為單位，之後會與時間軸上的影格增減連動）、繪製區域（可以在匯出範圍之外多畫一些的設定）、要使用的自動上色設定等。","help.entry67.title":"專案詳情畫面","help.entry67.desc":"可以在一個畫面中集中檢視、編輯專案名稱、縮圖、收藏狀態、要啟用的自動上色設定篩選等專案相關設定。存檔樹的入口也在這裡。","help.entry68.title":"主題設定","help.entry68.desc":"可以從主題清單中選擇App整體的配色，也可以自由自訂強調色。標題・項目名稱用字型與說明文字用字型是分開的，能在保持可讀性的同時享受換裝樂趣。","help.entry69.title":"工作區設定","help.entry69.desc":"彙集了左手模式（左右翻轉停靠面板）、手動切換電腦/DeX模式、手掌工具顯示條件等設定的畫面。可以依所用裝置和慣用手調整成更方便操作的版面。","help.entry70.title":"手勢設定","help.entry70.desc":"可以將復原/重做、跳至影格、取色器等操作指派給雙指點擊、三指點擊、雙指滑動或長按。觸控筆按鍵（在支援的觸控筆上）也可以單獨指派操作。想不切換工具就用一個動作觸發常用操作時很方便。","help.entry71.title":"畫筆設定","help.entry71.desc":"除了數位板・數位螢幕的筆壓曲線外，這個設定畫面還能把切換橡皮擦、取色器等操作指派給支援的觸控筆側邊按鍵。","help.entry72.title":"傾斜偵測","help.entry72.desc":"利用支援的觸控筆的傾斜資訊，在筆尖傾斜放倒時讓線條變粗或變淡，重現更接近實際畫具的書寫手感的設定。可以在效能設定中開關。","help.entry73.title":"效能設定","help.entry73.desc":"可依裝置效能從低畫質・中畫質・高畫質預設中選擇，也可逐項單獨設定（自訂）。除儲存方式・運作速度・洋蔥皮・傾斜偵測外，復原次數、垃圾桶自動刪除等影響App容量與運作負擔的設定也都集中在這裡。","help.entry74.title":"填色工具詳細設定","help.entry74.desc":"在設定畫面的「填色工具」中可以調整容許誤差（點擊位置的顏色相差多少仍視為同一區域）、擴充px（填色區域向邊界外擴展多少以填補線稿的縫隙）以及潛入線條下方（不覆蓋線稿本身，而是把擴充部分合成到既有像素的背後，藉此保持線條外觀不變）。當線稿有細小縫隙或填色感覺不完整時，調整這些設定能讓效果更穩定。","help.entry75.title":"復原次數設定","help.entry75.desc":"在效能設定中可以調整復原能回溯的操作次數。次數越多越能放心地反覆嘗試，但也會佔用更多記憶體；在低效能裝置上減少次數可以讓運作更輕快。","help.entry76.title":"字型讀取","help.entry76.desc":"可以直接讀取裝置內的字型檔案來使用的功能。可在設定畫面字型管理的「讀取」標籤頁中新增。想使用未公開發布的自製字型或已購買的商用字型時可以使用此功能。","help.entry77.title":"釋放空間","help.entry77.desc":"以圓餅圖查看NIARIM在裝置上占用的容量，以及NIARIM內部（專案、素材、已匯出檔案、自製筆刷/網點/圖章/字型、快取、垃圾桶）的詳細佔比。可以清除快取、批次刪除所有專案中的未使用素材、清空垃圾桶、整理專案，或刪除全部資料（初始化）。","help.entry78.title":"主畫面小工具","help.entry78.desc":"可放在手機主畫面上的三種小工具(啟動頁的作品單格畫面／「創作作品」／「作品廣場」)設定。小工具本身需要長按主畫面才能加入,App 內沒有加入按鈕。「選擇作品」會使用與作品列表分頁相同的排序、顯示方式、搜尋與收藏篩選,選好作品後還能在附播放控制項的預覽中選擇要顯示的確切影格。「創作作品」與「作品廣場」小工具可以選擇背景色要跟隨 App 主題,或自行指定顏色。","help.lead":"收錄與應用程式內說明完全一致的79個項目，可透過關鍵字或分類尋找。"},"ko":{"help.category.tool":"도구","help.category.brush":"브러시","help.category.penInput":"펜 입력","help.category.drawing":"그리기","help.category.layer":"레이어","help.category.animation":"애니메이션","help.category.save":"저장","help.category.projectManagement":"프로젝트 관리","help.category.export":"내보내기","help.category.community":"커뮤니티","help.category.premium":"Premium","help.category.settings":"설정","help.entry0.title":"기본 조작(탭・길게 누르기・쓸어올리기)","help.entry0.desc":"도구 모음의 아이콘은 한 번 탭하면 해당 도구로 전환됩니다. 같은 아이콘을 길게 누르거나 위로 쓸어올리면 세부 설정이 열립니다. 펜은 브러시・스크린톤・스탬프・올가미 채우기 전환, 페인트통은 단색과 스크린톤 채우기 전환, 선택 도구는 사각형・올가미・자동 선택 전환, 손가락 도구는 흐리기와 모자이크 전환, 빠른 전환 도구는 등록 내용 편집이 각각 길게 누르기・위로 쓸어올리기 뒤에 있습니다. 아이콘을 두 번 탭하면 그 도구의 간단한 설명이 화면 아래에 표시됩니다.\\n캔버스에서는 두 손가락으로 오므리면 확대・축소, 두 손가락으로 끌면 이동, 두 손가락 탭으로 실행 취소, 세 손가락 탭으로 다시 실행입니다. 화면 좌우 끝을 두 번 탭하면 앞뒤 프레임으로 이동합니다.\\n마우스나 펜 태블릿을 연결한 경우에는 휠로 확대・축소, 가운데 버튼 드래그로 이동할 수 있습니다.","help.entry1.title":"펜 도구","help.entry1.desc":"캔버스에 선을 그리는 기본 도구입니다. 길게 누르면 브러시 종류・굵기・색을 변경할 수 있습니다（더블탭은 간단 설명 표시）. 펜 태블릿・액정 태블릿의 필압・기울기를 지원하며, 설정 화면의 「펜 입력」에서 필압 곡선을 조정하면 필압이 반영되는 방식（약한 힘으로 굵기・불투명도가 얼마나 변하는지）을 세밀하게 커스터마이즈할 수 있습니다. 펜 서브 도구를 전환하면 같은 펜 도구로 스크린톤 붙이기・스탬프 배치도 할 수 있습니다.","help.entry2.title":"지우개 도구","help.entry2.desc":"펜 도구와 짝을 이루는, 그린 내용을 지우기 위한 도구입니다. 브러시와 마찬가지로 굵기・불투명도를 조정할 수 있고, 페이드나 스트로크 감쇠 등의 브러시 설정도 공통으로 반영됩니다. 레이어의 투명한 부분에 「덧그리는」 것이 아니라 기존 그림을 「지우는」 처리를 하므로, 아래 레이어가 비쳐 보이게 됩니다.","help.entry3.title":"페인트통 도구","help.entry3.desc":"둘러싸인 영역을 한 번에 채우는 도구입니다. 선화로 둘러싸인 범위 안을 탭하면 그 범위 전체가 선택 중인 색（또는 스크린톤）으로 채워집니다. 선화에 틈이 있으면 의도치 않은 범위까지 채워질 수 있으므로, 선화가 제대로 닫혀 있는지 확인한 후 사용하는 것이 요령입니다. 설정에서 단색 채우기/스크린톤 채우기를 전환할 수 있습니다. 상세 설정(허용 오차・확장 px・선 아래로 파고들기)은 설정 화면의 \"페인트 통 채우기\"에서 조정할 수 있습니다.","help.entry4.title":"올가미 채우기","help.entry4.desc":"둘러싸고 싶은 범위를 손가락으로 따라 그려 다각형 영역을 만들고, 그 안쪽을 한꺼번에 채우는 도구입니다. 페인트통 도구와 달리 선화가 닫혀 있지 않은 부분이 있어도 직접 둘러쌀 범위를 지정할 수 있어, 복잡한 형태나 선이 끊긴 부분을 채우는 데 적합합니다. 「둘러싸서 채우기」를 켜면 둘러싼 범위 안에서 선으로 닫힌 영역을 몇 개든 페인트통처럼 한꺼번에 채웁니다(올가미와 그림 사이의 여백은 채우지 않습니다).","help.entry5.title":"스포이드 도구","help.entry5.desc":"탭한 위치의 색을 추출하여 그리기 색으로 선택하는 도구입니다. 화면에 실제로 표시되는 모든 레이어를 합성한 색을 추출하므로, 여러 레이어가 겹쳐 있는 부분에서도 「보이는 그대로의 색」을 정확하게 가져올 수 있습니다.","help.entry6.title":"선택 도구","help.entry6.desc":"캔버스의 일부를 범위 선택하여, 선택한 범위만 이동・회전・확대축소할 수 있는 도구입니다. 길게 누르면 「사각형 선택」「올가미 선택（자유로운 형태로 둘러싸기）」「자동 선택（매직 완드, 비슷한 색상의 범위를 자동으로 묶어 선택）」의 3가지 선택 방법 중에서 고를 수 있습니다. 선택 중에는 선택 범위를 나타내는 테두리가 캔버스 위에 표시되며, 선택을 해제할 때까지 모든 프레임・모든 레이어에서 같은 범위가 고정 표시됩니다. 올가미 선택에서 「선에 스냅」을 켜면, 페인트 통 채우기와 같은 방식으로 선화가 나누는 영역을 보고 올가미 안에 대부분이 들어 있는 영역만 선택합니다. 선택 범위의 가장자리는 선화의 바깥쪽 가장자리를 정확히 따라가며, 영역을 둘러싼 선과 안쪽의 선도 함께 선택됩니다(윤곽 밖으로 뻗어 나간 선은 윤곽에서 잘립니다). 색을 칠한 면도 페인트 통 채우기와 같이 색마다의 영역으로 다루므로, 채색과 선이 있는 레이어에서도 그림 모양대로 선택할 수 있습니다. 「선화 간격 허용」에서 지정한 폭까지의 선의 끊김은 이어진 것으로 취급합니다. 올가미 안에 선화가 없으면 둘러싼 모양 그대로 선택합니다. 선화는 선택 참조 대상（「작업 레이어만」／「표시 레이어 모두」）에서 찾습니다.","help.entry7.title":"손가락 도구（왜곡 도구）","help.entry7.desc":"손가락으로 문지른 방향으로 픽셀을 밀어내듯 왜곡시켜, 손가락으로 젖은 물감을 문지른 듯한 효과를 만드는 도구입니다. 세밀한 수정보다는 이미 그린 선을 유기적으로 왜곡시켜 표정을 더하고 싶을 때 사용합니다.","help.entry8.title":"도형 도구","help.entry8.desc":"직선・사각형・원 같은 정확한 도형을 한 번의 동작으로 그리는 도구입니다. 드래그로 시작점에서 끝점까지 움직이면 그 자리에서 미리보기가 표시되고, 손을 떼면 확정됩니다. 프리핸드로는 그리기 어려운 직선이나 정원이 필요할 때 편리합니다.","help.entry9.title":"텍스트 도구","help.entry9.desc":"캔버스 위에 문자를 배치하는 도구입니다. 글꼴・크기・색・세로쓰기/가로쓰기를 선택할 수 있습니다. 세로쓰기에서는 반각 영숫자의 자동 회전・다테추요코（숫자를 가로 방향 그대로 나열하는 표기）・루비（후리가나）에도 대응합니다. 배치한 텍스트는 내보내기 시에도 픽셀로 구워집니다. 텍스트 도구에서 사용할 폰트를 추가・검색・삭제할 수 있는 화면입니다. 기본 내장 폰트 외의 추가 무료 폰트는, 초기 설치 용량을 줄이기 위해 이곳에서 필요할 때 다운로드하는 방식으로 되어 있습니다.","help.entry10.title":"빠른 도구 관리","help.entry10.desc":"자주 쓰는 도구 조합을 등록해두고 탭 한 번으로 순서대로 전환할 수 있는 기능입니다. 길게 누르거나 위로 스와이프하면 관리 팝업이 열려 등록 내용과 순서를 편집할 수 있습니다.","help.entry11.title":"빠른 도구","help.entry11.desc":"자주 쓰는 브러시・도구 조합을 미리 등록해두고 버튼 하나로 순서대로 전환할 수 있는 기능입니다. 캔버스의 ↺ 버튼을 길게 누르거나 위로 스와이프하면 등록・순서 변경・삭제가 가능한 관리 팝업이 열립니다. 드래그로 순서를 바꿀 수 있습니다.","help.entry12.title":"스탬프 도구","help.entry12.desc":"등록된 이미지를 브러시처럼 캔버스에 배치하여 집중선, 배경 패턴, 소품 등을 다시 그리지 않고 재사용하는 도구입니다. 픽셀 모드에서는 픽셀 아트 필터와 동일한 Pixel Art 처리를 사용해 투명 경계를 선명하게 유지하면서 픽셀화와 감색을 수행합니다. 모자이크는 별도의 효과이며 스탬프 픽셀 모드에는 사용하지 않습니다. 스탬프 패널에서 회전 각도와 크기도 조절할 수 있습니다.","help.entry13.title":"펜","help.entry13.desc":"펜 도구를 길게 누르면 일반 그리기 외에 스크린톤 붙이기・스탬프 배치 서브 도구로 전환할 수 있습니다. 도구를 일일이 바꾸지 않고도 같은 펜으로 여러 작업을 오갈 수 있습니다.","help.entry14.title":"선택 범위 변형","help.entry14.desc":"선택 도구로 감싼 범위는 캔버스 왼쪽 아래에 나오는 「이동」「크기 조절」「회전」 버튼으로 모드를 고른 뒤 선택 범위 안을 드래그해 변형할 수 있습니다. 실수로 그린 부분의 위치를 조정하거나, 일부만 확대해 강조하고 싶을 때 사용합니다. 같은 바의 「전체 선택」을 누르면 그리고 있는 레이어 전체가 선택 범위가 되므로, 레이어 전체의 이동・회전・크기 조절도 같은 방법으로 할 수 있습니다（예전의 독립된 「변형 도구」는 여기로 통합했습니다）. 격자점을 개별적으로 드래그해 더 자유롭게 일그러뜨리고 싶다면 같은 바의 「자유 변형」「메시 변형」을 사용하세요.","help.entry15.title":"자유 변형・메시 변형","help.entry15.desc":"캔버스 오른쪽 위의 편집/설정 메뉴에서 열 수 있는, 레이어 전체를 대상으로 하는 변형 도구입니다. 선택 범위 변형과 달리 선택 범위가 필요 없으며, 모서리나 격자점을 손가락으로 개별적으로 드래그해 자유로운 형태로 변형할 수 있습니다. 컨트롤 패널의 분할 수 슬라이더로 메시를 최대 10×10까지 세밀하게 나눌 수 있고, 두 손가락으로 각각 다른 점을 동시에 잡으면 회전・확대축소 같은 조작도 직관적으로 할 수 있습니다.","help.entry16.title":"컬러 피커","help.entry16.desc":"HSV와 RGB를 한 화면에서 전환하며 색을 고를 수 있는 컬러 피커입니다. 팔레트 기능으로 사용 중인 색상 세트를 저장하고 불러올 수 있습니다. 팔레트는 파일 내보내기나 QR 코드로 다른 기기와 공유할 수도 있습니다.","help.entry17.title":"브러시 즐겨찾기","help.entry17.desc":"브러시 목록에서 브러시의 별 아이콘을 탭하면 즐겨찾기 등록・해제를 할 수 있습니다（자동 채색 설정・스탬프・폰트・그리기 필터 등 앱 내 다른 즐겨찾기 기능과 같은 조작 방법입니다）. 목록 위쪽의 별 아이콘으로 즐겨찾기만 표시하도록 필터링할 수도 있습니다. 실수로 삭제되지 않도록 즐겨찾기로 등록된 브러시는 삭제할 수 없습니다.","help.entry18.title":"커스텀 브러시","help.entry18.desc":"브러시 목록에서 미리 설치된 브러시를 길게 눌러 「복제」를 선택하면 이를 바탕으로 나만의 커스텀 브러시가 만들어집니다. 복제한 브러시는 굵기・불투명도・경도・회전・밀도・분산・흐림 반경 등의 파라미터를 자유롭게 편집할 수 있으며, 필요 없어지면 삭제할 수도 있습니다（미리 설치된 브러시 자체는 편집・삭제할 수 없습니다）. 캔버스의 슬라이더로 바꾼 굵기와 불투명도는 브러시마다 저장됩니다. 미리 설치된 브러시도 마찬가지이며, 목록의 메뉴에서 기본값으로 되돌릴 수 있습니다. 폴더로 분류하거나 별 아이콘으로 즐겨찾기 등록도 할 수 있습니다.","help.entry19.title":"브러시 접힘","help.entry19.desc":"브러시 설정에서 「외곽선」을 켜면 「접힘 모드」를 사용할 수 있습니다. 끄면 일반 외곽선 펜과 동일하게 그립니다. 켜면 그린 스트로크의 방향과 굽은 정도에 따라 외곽선 펜의 선 자체가 접히거나 말립니다. 물결을 자동으로 만드는 기능이 아닙니다. 굽은 곳마다 안쪽 윤곽에서 갈라져 구부러지다가 사라지는 접힘선이 들어갑니다. 같은 방향으로 계속 돌면 270°마다 은은한 접힘선이 들어갑니다. 접힘 유형은 5가지입니다. 「웨이브 (위에서 보기)」는 먼저 그린 쪽을, 「웨이브 (아래에서 보기)」는 나중에 그린 쪽을 앞으로 보냅니다. 「오른쪽 컬」은 진행 방향의 오른쪽으로, 「왼쪽 컬」은 왼쪽으로 말려 들어가듯 앞뒤를 정합니다. 기준은 화면 방향이 아니라 그린 방향입니다. 「초승달 컬」은 그린 C자 곡선을 따라 초승달이 이어지는 모양으로 다듬습니다. 「접힘 길이」는 접힘선의 길이(브러시 크기에 연동), 「접힘 각도」는 스트로크 커브를 따르는 강도(50%에서 자연스럽게 연동), 「접힘선 커브 시작 위치」는 소재의 보이는 두께(0%에서는 갈라지는 위치에서 바로 구부러짐)를 조정합니다. 외곽선 펜에서 필압과 페이드(들어가기·빠지기)는 외곽선을 포함한 전체 모양만 바꾸며, 외곽선의 굵기와 색의 진하기는 변하지 않습니다. 「외곽선」의 「겹침 유지」를 끄면 겹친 획은 이음매에 외곽선을 그리지 않고 이어지며(겹친 곳에는 접힘선도 그리지 않습니다), 전체의 바깥쪽에만 외곽선을 그립니다. 「외곽선」의 「강약」을 켜면 획의 곡선 꼭짓점으로 갈수록 외곽선이 두꺼워집니다(곡선의 시작과 끝은 외곽선 두께 그대로이고 꼭짓점에서 「꼭짓점의 외곽선 두께」가 되도록 서서히 두꺼워지며, 펜을 떼면 반영됩니다).","help.entry20.title":"레이어","help.entry20.desc":"하나의 캔버스를 여러 개의 투명한 「층」으로 나누어 그릴 수 있는 구조입니다. 선화・채색・배경 등을 각각 다른 레이어에 나누어 그리면, 나중에 색만 다시 칠하거나 선화를 지우지 않고 배경만 교체할 수 있습니다. 화면상에서는 위에 겹쳐진 레이어일수록 앞쪽에 표시됩니다. 각 레이어 행의 아이콘에서 원탭으로 삭제・아래 레이어와의 결합을 할 수 있으며, 레이어 패널 상단 아이콘에서 표시 중인 모든 레이어를 한꺼번에 결합할 수도 있습니다.","help.entry21.title":"블렌드 모드","help.entry21.desc":"레이어의 합성 방법을 바꾸는 기능입니다. 스크린톤이나 색상 효과를 레이어로 겹칠 때 자주 사용됩니다.\n표준: 그대로 겹칩니다.\n곱하기: 아래 레이어와 곱해 어둡게 합니다. 그림자, 음영 표현의 정석입니다.\n스크린: 밝기를 더해 밝게 합니다. 빛 표현에 적합합니다.\n오버레이: 어두운 부분은 더 어둡게, 밝은 부분은 더 밝게 해 대비를 강조합니다.\n더하기(발광): 색을 단순히 더합니다. 빛 효과선 등에 적합합니다.\n빼기: 색을 뺀 값으로, 어둡게 가라앉은 효과가 됩니다.\n어둡게 비교: 위아래 레이어 중 어두운 쪽 색을 채택합니다.\n밝게 비교: 위아래 레이어 중 밝은 쪽 색을 채택합니다.\n색상 번: 아래 색을 어둡게 가라앉히며 진하게 발색시킵니다.\n색상 닷지: 아래 색을 밝게 날리며 발색시킵니다.\n하드 라이트: 오버레이보다 강하게 대비가 붙습니다.\n소프트 라이트: 오버레이보다 부드럽게 대비가 붙습니다. 부드러운 음영에 적합합니다.\n차이: 위아래 색의 차이를 표시합니다. 색상 어긋남 확인 등에 씁니다.\n색조, 채도, 색상, 광도: 각각 색조, 채도, 색감, 밝기만을 아래 레이어에 반영합니다.\n선형 번: 두 색을 더한 뒤 기준값을 빼 강하게 어둡게 합니다.\n선형 닷지: 두 색을 선형으로 더해 밝게 합니다. 더하기(발광)와는 별도의 블렌드 모드로, 레이어가 반투명할 때는 더하기(발광) 쪽이 더 밝아집니다.\n비비드 라이트: 위 색에 따라 번과 닷지를 전환해 매우 강한 대비를 만듭니다.\n선형 라이트: 위 색을 기준으로 밝기를 선형으로 높이거나 낮춥니다.\n핀 라이트: 위 색에 따라 더 어두운 쪽 또는 더 밝은 쪽으로 바꿉니다.\n하드 믹스: 비비드 라이트 결과를 임계값으로 나눠 강한 원색 분리를 만듭니다.\n제외: 차이보다 부드러운 반전·차이 효과입니다.\n나누기: 아래 색을 위 색으로 나누어 밝기 보정이나 색 차이 강조에 사용합니다.\n블렌드 모드 목록에서는 각 모드 옆에 빨강·노랑·파랑·흰색·검정을 어두운 색부터 밝은 색 위에 겹친 견본이 표시됩니다(견본의 아래쪽은 반투명으로 겹친 모습입니다).","help.entry22.title":"클리핑","help.entry22.desc":"바로 아래에 있는 레이어의 불투명한 픽셀 범위 안에만 그려지도록 하는 기능입니다. 선화를 벗어나지 않게 채색하고 싶을 때, 선화 레이어 위에 채색용 레이어를 만들고 클리핑을 활성화하면 선화 바깥으로 실수로 삐져나가 그릴 걱정이 없어집니다.","help.entry23.title":"공통 레이어","help.entry23.desc":"일반 레이어는 프레임마다 독립되어 있지만, 공통 레이어는 여러 프레임・씬에서 같은 내용을 공유하는 레이어입니다. 배경처럼 프레임이 바뀌어도 움직이지 않는 요소를 프레임마다 다시 그릴 필요 없이 한 번만 그리면 됩니다. 타임라인에서는 전용 트랙으로 표시됩니다. 일반 레이어를 공통 레이어（여러 프레임에 같은 내용을 계속 표시하는 레이어）로 변환할 수 있는 기능입니다. 표시 중인 레이어를 복제해 한 장으로 통합한 뒤 공통화할 수도 있습니다. 배경처럼 매 프레임 같은 내용을 재사용하고 싶을 때 다시 그리는 수고를 줄일 수 있습니다.","help.entry24.title":"레이어 다중 선택・일괄 조작","help.entry24.desc":"레이어 패널의 선택 모드를 사용하면 여러 레이어를 체크박스로 한꺼번에 선택해 병합하거나 일괄 삭제할 수 있습니다. 병합은 일반・자동 채색용 선화・자동 채색 레이어끼리만 가능합니다（공통 레이어・폴더・타임라인 소재는 병합 대상 아님）.","help.entry25.title":"레이어 폴더","help.entry25.desc":"여러 레이어를 폴더로 정리할 수 있는 기능입니다. 파츠 수가 많은 일러스트에서도 레이어 패널을 보기 쉽게 유지할 수 있습니다. 클리핑은 폴더를 넘어서 적용할 수 없으므로, 클리핑을 사용할 경우 같은 폴더 안에 모아두면 안전합니다.","help.entry26.title":"자동 채색","help.entry26.desc":"자동 채색용 선화 레이어 아래에 자동 채색 레이어를 만들고, 미리 만들어 둔 「자동 채색 설정」（부위별 색・스크린톤 조합）을 바탕으로 색을 자동으로 채우는 기능입니다. 선화를 다 그린 후 한 번에 채색할 수 있어, 같은 캐릭터를 여러 번 그리는 손그림 애니메이션에서 채색 작업을 크게 줄일 수 있습니다. 선화를 다시 그리면 타임라인・레이어 패널에 업데이트 표시가 나타나 자동 채색을 다시 실행해야 함을 알려줍니다. 타임라인 화면의 점 3개 메뉴에서 「자동 채색 실행」을 선택하면, 업데이트 표시가 붙은 자동 채색 레이어를 한꺼번에 다시 계산할 수 있습니다. 선화를 다시 그린 뒤 레이어 패널에서 한 장씩 실행하는 수고를 덜 수 있습니다. 자동 채색 설정의 각 부위에는 선화 색을 어떻게 처리할지에 대한 설정（지정 색・채색 색과 동일・색 트레이스）이 있습니다. 색 트레이스（선화 어우러짐）를 선택하면 선화 색을 채색 색에 맞춰 HSL 이동시켜, 선이 튀지 않고 자연스럽게 어우러집니다. 설정이 늘어나면 부위 할당 시 목록이 길어져 고르기 어려워집니다. 프로젝트 설정（또는 레이어 패널의 부위 할당 대화 상자）에서 이 프로젝트에서 사용하는 설정만 필터링해두면 목록이 깔끔해져 고르기 쉬워집니다. 「선화와 채색 사이의 틈 메우기」를 높이면 선의 옅은 가장자리 아래까지 칠해져, 윤곽선이나 채색과 같은 선화 색을 쓸 때 보이는 선화와 채색 사이의 틈이 작아집니다.","help.entry27.title":"그라데이션 채색（자동 채색 설정）","help.entry27.desc":"자동 채색 설정의 각 부위에는 단색뿐 아니라 그라데이션도 설정할 수 있습니다. 드래그로 이동할 수 있는 대칭 핸들로 그라데이션의 범위・각도를 직관적으로 조정할 수 있습니다. 각 부위에는 「지정 색상으로 테두리」도 설정할 수 있습니다. 체크하면 채색 범위의 가장 바깥쪽（선화와 맞닿는 부분）에 지정한 색상・두께의 선이 그려집니다. 테두리 색은 컬러 피커로 자유롭게 선택할 수 있고, 두께는 슬라이더・±버튼・숫자 직접 입력 중 어느 방법으로도 조정할 수 있습니다. 설정 항목 바로 위에 미리보기가 표시되어, 실제로 자동 채색을 실행하기 전에 색상과 두께를 확인할 수 있습니다.","help.entry28.title":"장면 조작","help.entry28.desc":"타임라인의 장면 탭에서는 장면 추가・복제・삭제・이름 변경・순서 바꾸기를 할 수 있습니다. 다중 선택 모드로 하면 여러 장면을 한꺼번에 이동・복제・삭제하는 것도 가능합니다.","help.entry29.title":"어니언 스킨","help.entry29.desc":"현재 편집 중인 프레임의 앞뒤 프레임을 반투명하게 겹쳐 표시하여, 움직임의 흐름을 확인하며 그릴 수 있게 하는 기능입니다. 성능 설정에서 표시할 매수（앞뒤로 몇 장까지）나 색・투명도를 조정할 수 있습니다.","help.entry30.title":"자","help.entry30.desc":"직선・원・타원・투시자（소실점을 이용한 투시도법용 자） 등, 프리핸드로는 그리기 어려운 정확한 선을 보조하는 기능입니다. 배치한 자를 따라 펜 끝이 자동으로 스냅되므로, 자가 없으면 어려운 원근감 있는 구도도 그리기 쉬워집니다. 자는 핸들을 조작하여 이동・회전・크기 변경을 할 수 있습니다. 어안 투시자는 렌즈 원 안에서 가로・세로 선이 호를 그리고 깊이 방향의 선이 중심으로 모이는 5점 곡선 투시입니다. 그리기 시작한 방향에 맞는 선을 따라 그려지며, 핸들로 중심 이동・반경 변경（원 오른쪽의 점）・기울기 변경（원 위쪽의 점）을 할 수 있습니다.","help.entry31.title":"페이드","help.entry31.desc":"스트로크의 들어가기(시작점)와 빠지기(끝점)의 값과 거리를 각각 독립적으로 설정하는 브러시 기능입니다. 시작만, 끝만 또는 비대칭으로 설정하여 양 끝의 굵기와 불투명도를 따로 조절할 수 있습니다. 외곽선 펜에서는 전체 모양(굵기)만 바뀌고 불투명도는 바뀌지 않습니다.","help.entry32.title":"스트로크 감쇠","help.entry32.desc":"페이드와 비슷하지만, 이쪽은 「잉크가 줄어드는」 듯한 표현에 가까워, 계속 그릴수록 색이 옅어지거나 흐려지는 효과입니다. 붓이나 마커로 계속 그렸을 때 잉크가 떨어지는 듯한 질감을 재현합니다.","help.entry33.title":"혼색","help.entry33.desc":"브러시로 칠할 때, 브러시 바로 아래에 이미 있는 색과 지금 칠하려는 선택 색을 섞으면서 그리는 기능입니다. 브러시 설정의 혼색 모드에서 섞지 않고 칠하는 디지털, 물감처럼 섞이며 묻어난 색을 끌어서 늘이는 유화풍 혼색, 투명한 물감을 겹치고 마르면 가장자리에 색이 고이는 수채화풍 혼색을 고를 수 있습니다.","help.entry34.title":"필압 곡선","help.entry34.desc":"펜 입력 설정에 있는 기능으로, 실제 필압의 세기와 브러시의 굵기・불투명도에 반영되는 방식의 관계를 그래프로 자유롭게 조정할 수 있습니다. 약한 필압에서도 굵게 나오길 원하는 사람, 반대로 강하게 눌러야만 굵어지길 원하는 사람 등, 필기 습관에 맞춰 그리는 느낌을 세밀하게 커스터마이즈할 수 있습니다. 설정 변경 후에는 그 자리에서 시험 삼아 그려보며 확인할 수 있습니다.","help.entry35.title":"스크린톤 채색","help.entry35.desc":"버킷 도구 설정에서 단색 채우기를 스크린톤 채우기로 바꾸면 선택한 망점・선 무늬 등의 스크린톤 패턴으로 채울 수 있습니다. 픽셀 모드 전용 체크무늬・격자무늬 스크린톤도 준비되어 있어, 도트 그림 질감을 살린 채색이 가능합니다. 프릴이나 니트, 타이츠 등 손그림으로는 손이 많이 가는 세밀한 무늬도 간단히 그릴 수 있습니다. 오리지널 스크린톤을 직접 만들어 추가하거나 다른 사용자와 공유할 수도 있습니다.","help.entry36.title":"픽셀 모드","help.entry36.desc":"브러시・폰트・스탬프 각각에 준비된 설정으로, 켜면 안티에일리어싱을 제거해 또렷한 도트 그림풍 윤곽으로 그려집니다. 일부러 옛날 게임 같은 질감을 내고 싶을 때나 저해상도 느낌을 연출하고 싶을 때 사용합니다. 색상 모드는 「색을 지정하지 않음」「색을 지정함」「색 수를 지정함」「팔레트에서 선택」의 4가지 중에서 고를 수 있으며, 도트 그림 전용 팔레트도 사용할 수 있습니다.","help.entry37.title":"작화 영역","help.entry37.desc":"내보내기 범위보다 넓은 범위까지 그려둘 수 있는 설정입니다. 캔버스 위에는 내보내기 범위를 나타내는 빨간 테두리가 표시되며, 테두리 밖으로 삐져나온 부분은 내보내지지 않지만, 팬・줌 같은 카메라 워크로 보여줄 범위를 나중에 조정할 여지를 남길 수 있습니다. 새 프로젝트 만들기 시 배율을 설정합니다.","help.entry38.title":"캔버스 배경색","help.entry38.desc":"프로젝트의 캔버스 배경색을 설정할 수 있습니다. 투명 내보내기（투명 WebM）를 사용할 경우 배경색은 내보내기에 영향을 주지 않지만, 작업 중 보기 편하도록 원하는 색으로 바꿀 수 있습니다.","help.entry39.title":"타임라인","help.entry39.desc":"애니메이션의 시간축을 관리하는 화면입니다. 프레임（정지 화면 1컷）을 나열하여 플립북처럼 재생하면 애니메이션이 됩니다. 텍스트・이미지・동영상・오디오 소재 트랙, 공통 레이어 트랙, 카메라 키프레임도 같은 타임라인에서 관리합니다. 텍스트・이미지・동영상과 프레임 일러스트의 앞뒤 관계는 「겹침 순서」에서 장면 전체 또는 지정한 프레임 범위별로 바꿀 수 있습니다. 항목을 길게 눌러 여러 개를 선택하고 한꺼번에 옮길 수도 있습니다.","help.entry40.title":"씬","help.entry40.desc":"하나의 프로젝트（동영상 한 편） 안을 장면（컷）별로 나누어 관리하는 기능입니다. 폴더가 프로젝트 단위의 정리라면, 신은 한 편의 동영상 안에서 장면 전환을 표현하는 데 사용합니다. 타임라인의 신 탭에서는 신 추가・복제・삭제・이름 변경・순서 변경이 가능합니다. 다중 선택 모드로 전환하면 여러 신을 한 번에 이동・복제・삭제할 수도 있습니다.","help.entry41.title":"프레임 조작","help.entry41.desc":"프레임 목록에서는 새로 추가・복제・삭제할 수 있고, 다중 선택 모드에서는 여러 프레임을 한꺼번에 이동・복제・삭제할 수 있습니다. 보유 셀 수를 늘리면 같은 프레임을 여러 칸에 걸쳐 계속 표시할 수 있어（이른바 「멈춤」）, 움직임이 적은 컷에서 매수를 절약할 수 있습니다.","help.entry42.title":"소재 클립（텍스트・이미지・동영상・오디오）","help.entry42.desc":"타임라인의 텍스트・이미지・동영상・오디오 트랙에 배치한 클립입니다. 클립 본체를 길게 눌러 드래그하면 표시 시작 위치를 옮길 수 있고, 좌우 끝의 손잡이를 드래그하면 사용 범위（길이）를 바꿀 수 있습니다. 같은 시간에 겹치는 소재는 자동으로 다른 줄에 놓입니다. 텍스트・이미지・동영상 클립을 탭하면 미리보기 아래에 편집 패널이 열립니다. 글자 내용・글꼴・색・외곽선, 위치・크기・X축／Y축／Z축 회전・불투명도（미리보기에서 드래그해도 움직일 수 있고, 키프레임을 추가하면 움직임이 됩니다）, 마스크（사각형・타원・흐림・반전）, 배치할 줄을 바꿀 수 있으며 복제・삭제도 여기서 할 수 있습니다. 오디오 클립은 상세 시트에서 음량・페이드를 조정합니다.","help.entry43.title":"소재 목록","help.entry43.desc":"프로젝트에서 사용 중인 이미지・동영상・오디오 소재를 한꺼번에 확인할 수 있는 화면입니다. 타임라인에 배치한 소재의 원본 파일이 여기에 모입니다.","help.entry44.title":"음량 조절","help.entry44.desc":"타임라인에 배치한 오디오 클립은 상세 시트에서 음량・페이드인・페이드아웃 시간을 조정할 수 있습니다. 효과음이나 배경음악의 음량 균형을 맞추거나, 곡의 시작・끝을 부드럽게 만들 수 있습니다.","help.entry45.title":"카메라 키프레임","help.entry45.desc":"타임라인 상의 특정 위치에 카메라의 위치・확대율・회전을 기록해 두는 기능입니다. 키프레임 사이는 자동으로 부드럽게 보간되므로, 팬（좌우 이동）이나 줌인・줌아웃 같은 카메라 워크를 쉽게 넣을 수 있습니다.","help.entry46.title":"연출 필터","help.entry46.desc":"씬이나 프레임에 적용할 수 있는 영상 효과（블러・색조 보정・글로우・픽셀 아트 등）입니다. 손그림 자체는 바꾸지 않고, 연출로서 화면 전체의 느낌을 조정하고 싶을 때 사용합니다. 그리기 필터 중 톤 커브(프리셋과 강도)・레벨 보정・선명하게・언샤프 마스크・비네트(색・범위・농도)・수채 경계도 여러 프레임에 같은 효과를 한 번에 줄 수 있도록 연출 필터에 들어 있습니다. 픽셀 아트는 배색 방식（색을 지정하지 않음・색을 지정함・색 수를 지정함・팔레트에서 선택）도 고를 수 있습니다. 색을 제한하면, 한 가지 색으로는 원래 색과 먼 곳을 사용할 수 있는 색 중 두세 가지를 규칙적으로 배치해(디더링) 원래 색에 가깝게 하며, 이 배치는 프레임이 바뀌어도 움직이지 않습니다. 윤곽 부분은 또렷하게 유지합니다. 디더링은 스위치로 켜고 끌 수 있으며, 끄면 가장 가까운 한 가지 색으로 칠합니다. 연출 필터는 여러 개를 겹쳐서 적용할 수 있으며, 그 적용 순서는 타임라인상의 배열 순서를 따릅니다. 필터 목록을 드래그로 재배열하면 실제로 화면에 반영되는 순서도 바뀝니다. 필름의 입자감 같은 노이즈를 프레임마다 변화시키며 적용하는 연출 필터입니다. 강도・양（노이즈가 올라가는 밀도）・입자 크기를 슬라이더로 조정할 수 있습니다. 같은 프레임으로 돌아오면 같은 입자 모양이 되므로 스크러빙 중에는 깜빡이지 않고, 재생하면 입자가 움직이는 것처럼 보입니다. 화면에 내리는 비를 표현하는 연출 필터입니다. 내리는 정도（빗방울 수）・속도・빗방울 크기・바람 방향 각도를 슬라이더로 조정할 수 있습니다. 각 빗방울은 프레임이 진행될수록 일정한 속도로 계속 내리므로 자연스러운 비의 움직임이 됩니다.","help.entry47.title":"그리기 필터","help.entry47.desc":"선택한 레이어에 직접 적용하는 필터입니다(연출 필터가 타임라인 전체나 장면 단위로 적용되는 것과 달리 그리기 필터는 레이어 단위로 작동합니다). 제공되는 26종은 가우시안 흐림, 렌즈 흐림, 애니메이션풍, 톤 커브, 레벨 보정, 윤곽선, 선명하게, 언샤프 마스크, 비네트, 레트로 애니메이션, 브라운관, 이진화, 어안 렌즈, 색수차, 안경 단면, 도트 그림, 질감 변경, 배경 어우러짐, 먹물 고임, 자동 선화, 프리즘, 색상 반전, 모자이크, 노이즈, 구체 음영, 수채 경계입니다. 수채 경계는 작업 레이어에 칠한 부분의 가장자리에 색을 고이게 하고 안쪽을 비치게 하여, 마른 수채화처럼 만듭니다(「색 경계에도 적용」을 켜면 이웃한 색의 경계에도 가장자리가 생깁니다). 애니메 스타일은 색 수를 줄이고, 이웃한 색의 차이가 「색 차이 임계값」 이상인 경계에 「경계선 굵기」의 선을 어두운 쪽으로 긋습니다(선화의 선은 굵어지지 않습니다). 프리즘은 레이어에 그린 모양마다 무지개 6색(빨강·초록·하늘색·파랑·보라·빨강)으로 칠해 흐리게 하고, 레이어를 선형 닷지로 바꿉니다. 어두운 색의 가늘고 작은 잎 같은 모양을 별도의 레이어에 먼저 그린 뒤 사용하면 그림 위에 은은한 무지갯빛 줄기가 들어갑니다(블러 양은 일반적인 가우스 블러와 같은 기준). 구체 음영은 타원형 빛의 안쪽에 빛 색을, 바깥쪽에 그림자 색을 그려진 곳에만 겹칩니다(빛은 캔버스 위에서도 드래그할 수 있습니다). 윤곽선은 원본 레이어를 다시 쓰지 않고 결과만 새 레이어에 그립니다. 안경 단면은 패널의「펜」「페인트통」으로 캔버스에 칠한 범위（「지우개」로 수정）에만 강한 안경 렌즈 같은 국소 왜곡을 적용합니다（선택 범위나 선택 레이어가 있으면 그 범위에서 시작합니다）. 캔버스에 선택 범위가 있으면 그리기 필터는 그 안에만 적용됩니다. 픽셀 아트는 배색 방식(제한 없음, 색 지정, 색 수 지정, 팔레트 선택)도 고를 수 있습니다. 색을 제한하면, 한 가지 색으로는 원래 색과 먼 곳을 사용할 수 있는 색 중 두세 가지를 규칙적으로 배치해(디더링) 원래 색에 가깝게 합니다. 윤곽 부분은 섞지 않고 또렷하게 유지합니다. 색 수를 지정하면 그림의 많은 부분을 차지하는 색에서 고릅니다. 디더링은 스위치로 켜고 끌 수 있으며, 끄면 가장 가까운 한 가지 색으로 칠합니다. 크기는 「블록 크기 지정」(1~100의 100단계)과 「도트 수 지정」(가로・세로 도트 수 슬라이더. 왼쪽 끝은 1, 오른쪽 끝은 캔버스 크기) 중에서 바꿀 수 있으며, 그림의 가로세로 비율을 유지한 채 가로와 세로가 함께 바뀝니다. 두 지정 방식도 서로 연동됩니다. 어느 쪽이든 도트는 정사각형 그대로이고 반투명한 테두리가 생기지 않습니다. 자동 선화에서는 필터를 적용하기 전에 임시 Vector 제어점을 직접 편집할 수 있습니다. 점을 드래그하면 해당 점만 이동합니다. 「적용」 오른쪽의 「제어점 추가」를 고르고 선을 탭하면 제어점을 추가하고, 「제어점 삭제」를 고르고 점을 탭하면 삭제할 수 있습니다(둘 다 고르지 않았을 때 점을 탭하면 확인한 뒤 삭제합니다). 편집한 형상이 그대로 적용 결과에 사용되며, 제어점의 이동・추가・삭제도 필터 편집의 실행 취소・다시 실행으로 하나씩 되돌릴 수 있습니다. 톤 커브는 곡선의 빈 곳을 탭하면 점을 추가하고, 점을 드래그하면 이동하며, 길게 누르면 삭제할 수 있습니다. R·G·B 색마다의 곡선은 RGB 곡선 다음에 적용됩니다. 레벨 보정도 R·G·B마다 따로 조정할 수 있고, 감마로 중간 밝기를 바꿀 수 있습니다. 테두리의 「안쪽으로 파고들기」로 원래 윤곽의 안쪽까지 테두리를 넓힐 수 있으며, 테두리의 새 레이어는 원래 레이어 바로 아래에 만들어집니다. 색수차는 어긋남을 X(가로)·Y(세로)·Z(중심에서 바깥쪽)에 얼마나 나눌지 지정할 수 있습니다. 어안 렌즈의 중심과 반지름은 캔버스 위의 ＋와 원의 손잡이를 드래그해서도 바꿀 수 있습니다. 비네트는 캔버스 전체의 네 모서리를 부드럽게 어둡게 합니다(그리지 않은 투명한 곳에도 그림자가 집니다). 「범위」로 네 모서리에서 중심 쪽으로 어디까지 어둡게 할지, 「농도」로 네 모서리의 어두운 정도를 조정할 수 있습니다. 안경 렌즈 왜곡은 실제 도수가 높은 안경처럼, 렌즈 너머의 풍경을 렌즈 중심 쪽으로 고르게 줄이거나(음수 값, 근시용) 넓히며(양수 값, 원시용), 렌즈 가장자리에서 윤곽이 계단처럼 어긋납니다. 먹물 고임은 선이 「최대 각도」 이하로 만나는 곳(초기값 90°에서는 예각과 직각: V자, 교차의 좁은 쪽, T자, 네모난 모서리)의 각 안쪽에만 고이며, 그보다 넓은 각에는 고이지 않습니다. 만나는 점에서 선의 가장자리로부터 「중앙 두께」, 그로부터 「범위」 끝을 향해 곧게 가늘어져 끝에서 0px이 되며 매끄럽게 뾰족해집니다. 「중앙 두께」를 크게 해도 양쪽 먹물 고임의 끝을 잇는 직선 바깥으로는 부풀지 않으며, 가장 두꺼워도 가운데는 평평합니다. 범위 도중에 선이 끊기면 그 선에서는 끊긴 곳을 끝으로 삼아 0px까지 가늘어집니다(선마다 길이가 달라집니다). 이때도 두 먹물 고임은 각의 한가운데에서 어느 선으로부터나 같은 두께로 만납니다(긴 쪽 선의 먹물 고임은 거기서부터 범위 끝까지 가늘어집니다). 자동 선화는 밑그림 선의 중심을 따라 가는 선으로 그립니다. 가까이 붙은 선도 사이가 조금이라도 비어 있으면 두 줄 그대로 그리고, 선 안의 작은 흰 점만 메웁니다. 두 선이 가까워져 붙는 곳은 가운데에 한 줄을 긋지 않고, 밑그림처럼 두 선이 서서히 가까워지며 합쳐집니다. 선이 교차하거나 겹친 곳도 밑그림 그대로 각 선이 이어집니다(교차점으로 꺾이거나, 겹친 두 선이 한 줄로 녹아들지 않습니다). 비스듬히 얕게 교차하는 선도 교차한 채 곧게 이어지며, 맞닿기만 하는 선(머리를 따라 그린 머리카락 윤곽 등)은 각자 자기 쪽을 지나는 별개의 선으로 남습니다. 눈 같은 점은 채운 점 그대로 그립니다. 「러프 선 굵기」보다 짧은 가지는 그리지 않습니다. 「선 끝 테이퍼」는 스위치로 켜고 끌 수 있으며, 끄면 선 끝까지 같은 굵기가 됩니다. 배경 어우러짐은 배경의 빛과 그림자를 블렌드 모드 「하드 라이트」로 겹칩니다(그림자 색은 검정이나 회색이 아니라 배경의 그림자 부분 색을 어둡게 한 것). 주변의 색은 「오버레이」로 전체에 겹쳐 색의 방향을 맞추고, 아래에서 올라오는 반사광과 주변의 반사는 「스크린」으로, 네온 같은 강한 색광은 「더하기(발광)」로 윤곽에 넣습니다. 「배경의 밝기·색감에 맞추기」는 배경보다 너무 밝거나 선명한 색을 배경의 범위로 가져오고, 어두운 곳·중간·밝은 곳을 각각 같은 밝기의 배경 색감 쪽으로 맞춥니다(선화의 검정은 그대로). 「흐림 정도」는 색을 가져올 배경을 흐리게 하는 양입니다.","help.entry48.title":"사용자 지정 자동 작업(동작 기록)","help.entry48.desc":"캔버스나 타임라인에서 지원되는 동작을 이름이 있는 순서로 기록해 반복 실행하는 기능입니다. 자동 작업에서 새 항목을 추가해 기록을 시작하고, 중지 후 검토 화면에서 순서를 바꾸거나 단계를 삭제한 뒤 저장합니다. 저장한 자동 작업은 이름 변경, 다시 기록, 삭제, 즐겨찾기 필터링이 가능하며 JSON 파일로 내보내고 가져올 수도 있습니다. 캔버스 동작만 같은 한 프레임 안에서 기록한 자동 작업은 실행할 때 현재 프레임, 지정한 프레임 범위, 모든 프레임 중에서 선택할 수 있습니다. 타임라인 자동 작업이나 여러 프레임에 걸친 기록에는 프레임 범위 선택이 표시되지 않습니다.","help.entry49.title":"레이어 키프레임（파츠 단위 애니메이션）","help.entry49.desc":"각 레이어의 위치・확대축소・회전을 프레임마다 지정하면 키프레임 사이가 자동으로 보간되는 기능입니다. 카메라 키프레임이 화면 전체를 움직이는 것과 달리, 이것은 개별 레이어만 움직입니다. 자동 채색의 각 파츠는 각각 독립된 레이어로 생성되므로, 파츠 단위 애니메이션（팔만 움직이기, 입만 여닫기 등）에 그대로 사용할 수 있습니다. 각 키프레임에는 「등속」「천천히 시작」「천천히 종료」「천천히 시작하고 종료」「튕김」이라는 이징（다음 키프레임으로의 연결 방식）을 개별적으로 설정할 수 있어, 단조로운 등속 이동뿐 아니라 튕기는 듯한 움직임도 표현할 수 있습니다. 레이어 패널의 점 3개 메뉴 「애니메이션（키프레임）」에서 설정합니다. 레이어의 그림 자체는 바뀌지 않고 표시 위치만 바뀌는 비파괴적인 변형입니다. 이 기능은 타임라인의 표시（미리보기・내보내기）에만 영향을 주며, 캔버스 모드에서의 실제 작화에는 영향을 주지 않습니다.","help.entry50.title":"레이어 그룹（여러 파츠를 한꺼번에 움직이기）","help.entry50.desc":"여러 레이어를 하나의 키프레임 흐름으로 한꺼번에 움직이는 기능입니다. 예를 들어 「팔」이 피부・소매 2장의 자동 채색 파츠로 이루어져 있다면, 이 2장을 그룹화해두면 한 번의 키프레임 조작으로 함께 움직일 수 있습니다. 레이어 패널에서 여러 개를 선택（체크박스）한 상태로 하단 바의 「그룹화」 아이콘에서 만듭니다. 그룹의 움직임은 각 레이어 자체의 키프레임（설정되어 있다면）에 겹쳐서 적용되므로, 그룹 전체의 움직임과 개별 레이어의 미세 조정을 함께 사용할 수도 있습니다. 하나의 레이어는 동시에 하나의 그룹에만 속할 수 있습니다.","help.entry51.title":"EndCard（엔드 로고）","help.entry51.desc":"동영상 내보내기 시, 본편이 끝난 후 자동으로 추가되는 NIARIM 로고의 짧은 영상（약 5초）입니다. 무료판에서는 숨기거나 삭제할 수 없지만, 프리미엄 회원이 되면 표시 ON/OFF・길이 변경・교체가 가능해집니다.","help.entry52.title":"자동 저장","help.entry52.desc":"충돌이나 파일 손상이 발생했을 때를 위한 복원 전용 저장입니다. 그리기 등의 변경이 있을 때마다 자동으로 저장되며, 최대 3개까지 오래된 순서로 덮어씌워집니다. 수동 저장（세이브 슬롯・세이브 트리）과는 완전히 별도로 관리되며, 일반 저장을 대체하지는 않습니다. 앱이 비정상 종료된 후 재시작할 때만 복원할지 묻습니다.","help.entry53.title":"세이브 슬롯","help.entry53.desc":"정해진 수의 저장 칸（슬롯）에, 직접 저장 위치를 선택하며 저장하는 방식입니다. 슬롯 수는 설정（저품질 5개・중품질 10개）으로 정해집니다. 덮어쓸 칸을 매번 직접 선택하므로, 「이 시점의 상태는 남겨두고 싶다」는 관리가 쉬운 방식입니다.","help.entry54.title":"세이브 트리","help.entry54.desc":"저장할 때마다 새로운 저장 지점이 만들어지고, 과거의 저장 지점에서 분기하여 다른 히스토리를 만들 수 있는（가지가 나뉘는） 저장 방식입니다. 개수 제한이 없어, 「그때 그 버전으로 돌아가서 다른 전개를 시도해 보고 싶다」는 사용법에 적합합니다. 화면에는 저장 지점이 아래에서 위로 뻗어나가는 나무 모양 도표로 표시됩니다.","help.entry55.title":"폴더","help.entry55.desc":"프로젝트（작품）를 그룹화하여 정리하는 기능입니다. 여러 계층을 지원하므로, 같은 작품의 여러 화차나 시리즈물을 함께 관리하는 용도로도 사용할 수 있습니다（예: 「작품명」 폴더 안에 「제1화」「제2화」…처럼 프로젝트를 나열）. 하나의 동영상 안에서 장면을 나누어 만들고 싶을 때는 폴더가 아니라 캔버스 화면의 「씬」 기능을 이용해 주세요.","help.entry56.title":"휴지통","help.entry56.desc":"삭제한 프로젝트가 임시로 이동하는 곳입니다. 완전히 삭제되기 전까지는 여기서 복원할 수 있습니다. 설정에서 자동 삭제까지의 일수（끔/30일/60일/90일）를 지정할 수 있습니다.","help.entry57.title":"공유（.niashare）","help.entry57.desc":"프로젝트를 다른 사람（또는 자신의 다른 기기）에게 전달하기 위한 공유 전용 파일 형식입니다. 받은 쪽이 이 파일을 열면 복제되어 자신의 프로젝트 목록에 추가됩니다. 공유 원본인 .niashare 파일 자체는 변경되지 않습니다.","help.entry58.title":"데이터 이전（.niatra）","help.entry58.desc":"설정・소재・브러시・자동 채색 설정・테마・팔레트(컬러 피커・도트 그림 전용) 등 앱 전체 환경을 다른 기기로 한꺼번에 이전하는 기능입니다. 이전할 항목은 체크박스로 개별 선택할 수 있으며, 제작 중인 프로젝트도 선택해서 포함할 수 있습니다(선택한 프로젝트는 소재・글꼴까지 통째로 이전됩니다). 개별 프로젝트만 전달하고 싶을 때는 「공유（.niashare）」도 사용할 수 있습니다.","help.entry59.title":"동영상 내보내기（MP4・WebM・GIF・AVI）","help.entry59.desc":"작품을 범용 MP4 동영상으로 내보냅니다. 무료 버전은 내보낼 수 있는 길이에 제한(90초)이 있으며, 동영상 끝에 엔드카드(앱 로고)가 자동으로 추가됩니다. 알파 채널（배경의 투명 부분）을 유지한 채 내보낼 수 있는 동영상 형식입니다. 지원하는 재생 환경에서만 투명하게 재생됩니다. 다른 앱의 소재로 겹쳐서 사용하고 싶을 때 적합합니다. 애니메이션 GIF로 내보냅니다. 자동으로 반복 재생되는 형식이라 SNS 공유 등 가볍게 공유하고 싶을 때 적합합니다. 호환성을 중시한다면 AVI（Motion JPEG）로도 내보낼 수 있습니다. 알파 채널（투명）은 지원하지 않으며, 기기에 따라 앱 내 미리보기가 되지 않을 수 있습니다（그 경우에도 「공유」에서 외부 플레이어로 재생할 수 있습니다）. 무료 회원은 프로젝트 길이에 90초까지의 상한이 있습니다（프리미엄 회원은 2시간）. 프레임 추가・복제로 상한을 넘어설 것 같으면 버튼을 탭한 순간 주의 대화상자가 표시되어, 실제로 90초를 넘지 않도록 되어 있습니다.","help.entry60.title":"내보내기 화면","help.entry60.desc":"'프리셋'에서 '표준', '고화질', '커스텀'를 선택할 수 있습니다. '커스텀'에서는 FPS를 조정할 수 있습니다. 동영상・이미지를 내보내는 동안 진행 상황이 표시되며, 도중에 취소할 수도 있습니다. 내보내기에 걸리는 시간은 기기 성능에 따라 달라집니다.","help.entry61.title":"작품 광장","help.entry61.desc":"애니메이션・일러스트 작품을 YouTube 동영상으로 커뮤니티에 게시하고, 다른 사용자의 작품을 둘러볼 수 있는 기능입니다. 「신작」・「랭킹」・「팔로잉」 탭을 전환할 수 있으며, 작품 제목 또는 게시자 이름으로 검색할 수 있습니다. 태그 검색 모드로 전환하면 태그로 작품을 좁혀볼 수 있으며, 태그는 게시자 외의 사용자도 자유롭게 추가・삭제할 수 있습니다（게시자가 잠근 태그는 게시자 본인만 해제할 수 있습니다）. 태그를 탭하기만 해도 같은 태그의 작품으로 좁혀집니다. 작품 카드를 탭하면 드래그・크기 조절이 가능한 플로팅 미리보기 창이 열려 다른 화면을 조작하면서도 계속 시청할 수 있습니다. 「상세보기」 버튼으로 작품의 상세 화면（게시자・게시일・태그 편집・북마크・리포스트 등）을 열 수 있습니다. 게시자 이름 옆의 「팔로우」 버튼을 누르면 팔로우가 되어, 「팔로잉」 탭에서 그 작가의 게시물만 최신순으로 모아 볼 수 있습니다. 누군가 나를 팔로우하면 화면 오른쪽 위 종 모양 아이콘의 알림 목록에 표시됩니다. 자신의 팔로잉/팔로워 목록을 다른 사용자에게 공개할지 여부를 설정할 수 있으며（기본값은 비공개）, 공개로 설정한 다른 사용자의 목록도 볼 수 있습니다. 다른 사람의 작품（자신의 게시물은 제외）은 「리포스트」 버튼으로 재게시할 수 있으며, 팔로우 중인 작가가 누군가의 작품을 리포스트하면 그 작품도 「게시일」과 「리포스트한 날짜」 중 더 최근인 쪽을 기준으로 「팔로잉」 탭에 섞여 표시됩니다（카드에 「○○님이 리포스트함」이라고 표시）. 북마크한 작품은 홈 화면의 「북마크됨」 탭에 모아서 표시되며, 게시자별 작품 목록 화면의 「북마크」 탭에서도 확인할 수 있습니다. 자신의 북마크 목록을 다른 사용자에게 공개할지 여부를 설정할 수 있으며（기본값은 비공개）, 공개로 설정한 다른 사용자의 북마크 목록도 볼 수 있습니다. 부적절한 작품은 사유를 첨부해 신고할 수 있으며, 신고 후에는 해당 게시자를 차단할지 선택할 수 있습니다. 세로로 긴 동영상은 「세로 화면 모드」에서 연속 재생으로 시청할 수 있습니다. 하루에 게시할 수 있는 작품 수에는 상한이 있으며, 무료 회원은 하루 1개, 프리미엄 회원은 하루 3개까지입니다. 화면 오른쪽 위의 표시 필터 버튼（사선이 그어진 눈 아이콘）으로 보고 싶지 않은 작품을 숨길 수 있습니다. 「생성형 AI 이미지·동영상 포함」 작품을 숨기는 설정 외에도, 작품 제목만을 대상으로 하는 숨길 제목 키워드과 작품 광장에서 작품에 붙은 태그만을 대상으로 하는 숨길 태그를 「새로 추가」로 하나씩 등록하고 연필 아이콘으로 수정하거나 휴지통 아이콘으로 삭제할 수 있습니다. 쉼표나 #은 필요하지 않습니다. 이 필터는 신착・랭킹・팔로잉（리포스트 포함）・세로 화면 모드・게시자 페이지・작품 상세・북마크에 적용됩니다. 「생성형 AI 이미지·동영상 포함」은 게시할 때 게시자가 직접 표시하는 항목이며, 게시한 후에도 게시자 본인만 변경할 수 있습니다（「내 게시물」 또는 작품 상세 화면에서 변경）.","help.entry62.title":"워터마크 재편집","help.entry62.desc":"타임라인의 공통 레이어 트랙에 배치한 워터마크를 탭하면 각도・크기・불투명도・표시 범위（루프 표시）를 언제든지 다시 편집할 수 있습니다. 등록할 때뿐 아니라 실제로 프로젝트 안에서 사용할 때 세밀하게 조정할 수 있습니다.","help.entry63.title":"워터마크","help.entry63.desc":"내보낸 동영상・이미지에 자신의 서명이나 로고를 워터마크로 넣을 수 있는 프리미엄 전용 기능입니다. 위치・크기・불투명도를 조정할 수 있습니다. 타임라인의 공통 레이어 트랙에 배치한 워터마크를 탭하면 각도・크기・불투명도・표시 범위（루프 표시）를 언제든지 다시 편집할 수 있습니다. 등록할 때뿐 아니라 실제로 프로젝트에서 사용할 때도 세세하게 조정할 수 있습니다. 워터마크를 추가하려면 타임라인의 '소재 추가' 메뉴에서 '＋워터마크'를 선택하세요.","help.entry64.title":"프리미엄","help.entry64.desc":"프리미엄 회원이 되면 무료 버전에서 90초로 제한된 동영상 길이가 최대 2시간까지 늘어나고, 모든 동영상 끝에 자동 추가되는 엔드카드(앱 로고)를 삭제할 수 있습니다. 광고도 숨겨지며, 워터마크, 톤 커브, 레벨 보정 기능도 사용할 수 있게 됩니다.","help.entry65.title":"홈 화면","help.entry65.desc":"앱을 실행하면 처음 표시되는 화면으로, 프로젝트・공유・작품 목록・휴지통 각 탭을 전환하며 볼 수 있습니다. 오른쪽 위 검색 아이콘으로 프로젝트 이름으로 좁혀 검색할 수도 있습니다. 프로젝트 탭에서는 화면 오른쪽 아래의 ＋ 버튼으로 새 프로젝트 만들기와 새 폴더 만들기를 선택할 수 있습니다.","help.entry66.title":"새 프로젝트 만들기","help.entry66.desc":"캔버스 크기・fps・길이（초 단위. 이후 타임라인에서의 프레임 증감과도 연동）・그리기 영역（내보내기 범위보다 넓게 그려둘 수 있는 설정）・사용할 자동 채색 설정 등을 한꺼번에 지정한 뒤 프로젝트를 만듭니다.","help.entry67.title":"프로젝트 상세 화면","help.entry67.desc":"프로젝트 이름・썸네일・즐겨찾기 등록・사용할 자동 채색 설정의 필터링 등 프로젝트별 설정을 한곳에서 확인・편집할 수 있는 화면입니다. 세이브 트리로 가는 입구도 여기에 있습니다.","help.entry68.title":"테마 설정","help.entry68.desc":"앱 전체의 색상 배합을 테마 목록에서 고르거나, 포인트 컬러를 자유롭게 커스터마이즈할 수 있는 화면입니다. 제목・항목명용 폰트와 설명문용 폰트가 나뉘어 있어, 가독성을 유지하면서 꾸미기를 즐길 수 있습니다.","help.entry69.title":"워크스페이스 설정","help.entry69.desc":"왼손잡이 모드（도킹 패널 좌우 반전）, PC/DeX 모드 수동 전환, 손바닥 도구 표시 조건 등을 한꺼번에 설정할 수 있는 화면입니다. 사용하는 기기와 주로 쓰는 손에 맞춰 작업하기 쉬운 레이아웃으로 조정할 수 있습니다.","help.entry70.title":"제스처 설정","help.entry70.desc":"두 손가락 탭・세 손가락 탭・두 손가락 스와이프・길게 누르기에 실행 취소/다시 실행・프레임 이동・스포이트 등의 동작을 할당할 수 있는 설정입니다. 펜 버튼（지원 스타일러스 사용 시）에도 별도로 동작을 할당할 수 있습니다. 도구를 바꾸지 않고 자주 쓰는 동작을 한 번에 불러오고 싶을 때 편리합니다.","help.entry71.title":"펜 설정","help.entry71.desc":"타블렛・액정 타블렛의 필압 곡선과 더불어, 펜 옆면 버튼（지원 스타일러스 사용 시）에 지우개 전환이나 스포이트 등의 동작을 할당할 수 있는 설정 화면입니다.","help.entry72.title":"기울기 감지","help.entry72.desc":"지원 스타일러스의 기울기 정보를 사용해, 펜촉을 눕혔을 때 선을 굵게・얇게 하는 등 실제 필기구에 가까운 필기감을 재현하는 설정입니다. 성능 설정에서 켜고 끌 수 있습니다.","help.entry73.title":"성능 설정","help.entry73.desc":"기기 성능에 따라 저품질・중품질・고품질 프리셋 중에서 선택하거나, 각 항목을 개별로 설정（커스텀）할 수 있습니다. 저장 방식・동작 속도・어니언 스킨・기울기 감지 외에도, 실행 취소 횟수나 휴지통 자동 삭제 등 앱의 용량・동작 부담에 영향을 주는 설정도 여기에 모여 있습니다.","help.entry74.title":"버킷 채우기 세부 설정","help.entry74.desc":"설정 화면의 「버킷 채우기」에서 허용 오차（클릭한 위치의 색에서 어디까지의 색 차이를 같은 영역으로 볼지）・확장 px（채운 영역을 경계 바깥쪽으로 넓혀 선화와의 틈을 메우는 정도）・선 아래까지 파고들기（확장분을 선화 위에 덮어쓰지 않고, 선의 모양은 유지한 채 뒤쪽으로 채우기 색을 합성）를 조정할 수 있습니다. 선화에 작은 틈이 있거나 덜 칠해진 부분이 신경 쓰일 때 조정하면 마무리가 안정됩니다.","help.entry75.title":"실행 취소 횟수 설정","help.entry75.desc":"성능 설정에서 실행 취소로 되돌릴 수 있는 동작 횟수를 조정할 수 있습니다. 횟수를 늘릴수록 안심하고 시행착오를 할 수 있지만 메모리 사용량도 늘어나므로, 저사양 기기에서는 횟수를 줄이면 동작이 가벼워집니다.","help.entry76.title":"폰트 가져오기","help.entry76.desc":"기기 내의 폰트 파일을 직접 불러와 사용할 수 있게 하는 기능입니다. 설정 화면의 폰트 관리 「가져오기」 탭에서 추가할 수 있습니다. 배포되지 않은 자작 폰트나 구매한 상업용 폰트를 사용하고 싶을 때 이용합니다.","help.entry77.title":"용량 확보","help.entry77.desc":"기기에서 NIARIM이 사용하는 용량과, NIARIM 내부(프로젝트, 소재, 내보낸 파일, 커스텀 브러시/스크린톤/스탬프/폰트, 캐시, 휴지통)의 세부 내역을 원 그래프로 확인할 수 있습니다. 캐시 삭제, 모든 프로젝트의 미사용 소재 일괄 삭제, 휴지통 비우기, 프로젝트 정리, 모든 데이터 삭제(초기화)를 수행할 수 있습니다.","help.entry78.title":"홈 화면 위젯","help.entry78.desc":"휴대폰 홈 화면에 배치할 수 있는 3종류의 위젯(작품의 한 컷 표시(시작 화면)·「작품 만들기」·「작품 광장」) 설정입니다. 위젯 자체는 앱 안이 아니라 홈 화면을 길게 눌러서 추가합니다. 「작품 선택」에서는 프로젝트 목록 탭과 동일한 정렬·보기 방식·검색·즐겨찾기 필터를 사용해 작품을 고른 뒤, 재생 컨트롤이 있는 미리보기로 표시할 프레임까지 선택할 수 있습니다. 「작품 만들기」・「작품 광장」 위젯은 배경색을 앱 테마에 맞출지 직접 지정할지 선택할 수 있습니다.","help.lead":"앱 내 도움말과 동일한 79개 항목을 검색하고 카테고리별로 확인할 수 있습니다."},"fr":{"help.category.tool":"Outils","help.category.brush":"Pinceau","help.category.penInput":"Saisie au stylet","help.category.drawing":"Dessin","help.category.layer":"Calques","help.category.animation":"Animation","help.category.save":"Enregistrement","help.category.projectManagement":"Gestion de projet","help.category.export":"Export","help.category.community":"Communauté","help.category.premium":"Premium","help.category.settings":"Réglages","help.entry0.title":"Commandes de base (appui, appui long, balayage)","help.entry0.desc":"Une simple pression sur une icône de la barre d’outils bascule vers cet outil. Appuyez longuement sur cette icône, ou faites-la glisser vers le haut, pour ouvrir ses réglages détaillés. Derrière cet appui long ou ce balayage se trouvent : pinceau, trame, tampon ou remplissage au lasso pour le stylo ; remplissage uni ou tramé pour le pot ; rectangle, lasso ou sélection automatique pour l’outil de sélection ; flou ou mosaïque pour l’outil doigt ; et la liste des outils enregistrés pour le changement rapide. Un double appui sur une icône affiche une brève description en bas de l’écran.\\nSur le canevas, pincez à deux doigts pour zoomer, faites glisser à deux doigts pour vous déplacer, touchez à deux doigts pour annuler et à trois doigts pour rétablir. Appuyez deux fois sur le bord gauche ou droit de l’écran pour passer à l’image précédente ou suivante.\\nAvec une souris ou une tablette graphique, la molette zoome et le glissement avec le bouton central déplace la vue.","help.entry1.title":"Outil plume","help.entry1.desc":"L'outil de base pour dessiner des lignes sur le canevas. Un appui long permet de changer le type, la taille et la couleur du pinceau (un double appui affiche un résumé rapide). Il prend en charge la pression et l'inclinaison des tablettes/stylets, et ajuster la courbe de pression dans Réglages > Saisie au stylet permet de personnaliser finement la façon dont la pression influence la taille et l'opacité. En changeant de sous-outil de plume, vous pouvez appliquer des trames ou placer des tampons avec le même outil.","help.entry2.title":"Outil gomme","help.entry2.desc":"L'équivalent de l'outil plume, utilisé pour effacer ce que vous avez dessiné. Comme un pinceau, vous pouvez ajuster sa taille et son opacité, et les réglages de pinceau comme le fondu et l'atténuation de trait s'y appliquent aussi. Plutôt que d'« ajouter » aux parties transparentes d'un calque, il « retire » le dessin existant, si bien que le calque en dessous devient visible à travers.","help.entry3.title":"Outil pot de peinture","help.entry3.desc":"Remplit une zone fermée en une seule fois. Appuyez à l'intérieur d'une zone entourée par un trait et toute la zone est remplie avec la couleur (ou la trame) sélectionnée. S'il y a des espaces dans le trait, le remplissage peut déborder sur des zones non voulues ; assurez-vous donc que le trait est bien fermé avant de l'utiliser. Vous pouvez basculer entre remplissage uni et remplissage en trame dans les réglages. Les réglages détaillés (tolérance, extension en px, passer sous les traits) sont accessibles depuis « Pot de peinture » dans les réglages.","help.entry4.title":"Remplissage lasso","help.entry4.desc":"Tracez avec votre doigt pour former une zone polygonale, puis remplissez l'intérieur en une seule fois. Contrairement au pot de peinture, vous pouvez définir la zone vous-même même là où le trait n'est pas fermé, ce qui le rend idéal pour les formes complexes ou les zones avec des lignes interrompues. Avec « Remplir la zone fermée » activé, toutes les zones fermées par des traits à l’intérieur du lasso sont remplies d’un coup, quel que soit leur nombre, comme avec le pot de peinture (l’espace entre le lasso et le dessin reste tel quel).","help.entry5.title":"Outil pipette","help.entry5.desc":"Prélève la couleur à l'endroit où vous appuyez et la définit comme couleur de dessin. Il échantillonne le rendu composité de tous les calques tel qu'affiché à l'écran, ce qui permet de récupérer précisément la « couleur telle que vue » même là où plusieurs calques se superposent.","help.entry6.title":"Outil de sélection","help.entry6.desc":"Sélectionne une partie du canevas afin de pouvoir déplacer, faire pivoter ou redimensionner uniquement cette zone. Un appui long permet de choisir parmi trois méthodes de sélection : « Sélection rectangulaire », « Sélection au lasso » (contour libre), ou « Sélection automatique » (baguette magique — regroupe automatiquement les zones de couleur similaire). Pendant une sélection, un contour marque la zone sélectionnée sur le canevas, et la même zone reste fixée sur toutes les images et tous les calques jusqu'à ce que vous désélectionniez. En sélection au lasso, activer « Magnétiser aux lignes » examine les zones que le dessin au trait découpe dans la toile, comme le fait le pot de peinture, et ne sélectionne que les zones situées en majeure partie dans le lasso. Le bord de la sélection suit exactement le bord extérieur du dessin au trait : les traits qui entourent ces zones et ceux à l’intérieur sont sélectionnés avec elles (un trait qui continue hors du contour est coupé là où il le quitte). Les couleurs remplies comptent comme des zones à part entière, comme pour le pot de peinture : un calque avec des aplats et des traits se sélectionne lui aussi selon la forme du dessin. Les interruptions d’un trait jusqu’à la largeur de « Tolérance des espaces » sont considérées comme fermées. S’il n’y a pas de dessin au trait dans le lasso, le lasso est sélectionné tel que tracé. Les traits sont pris dans la référence de sélection (« Calque de travail uniquement » / « Tous les calques visibles »).","help.entry7.title":"Outil doigt (déformation)","help.entry7.desc":"Déforme les pixels en les poussant dans la direction où vous faites glisser votre doigt, comme si vous étaliez de la peinture humide avec un doigt. Il sert moins aux corrections précises qu'à déformer de manière organique des lignes déjà dessinées pour leur donner plus d'expression.","help.entry8.title":"Outil forme","help.entry8.desc":"Dessine des formes précises comme des lignes, des rectangles et des cercles en un seul geste. Faire glisser du point de départ au point d'arrivée affiche un aperçu en direct, et la forme est finalisée lorsque vous relâchez le doigt. Pratique lorsque vous avez besoin de lignes droites ou de cercles parfaits difficiles à réaliser à main levée.","help.entry9.title":"Outil texte","help.entry9.desc":"Place du texte sur le canevas. Vous pouvez choisir la police, la taille, la couleur et le sens d'écriture vertical/horizontal. L'écriture verticale prend en charge la rotation automatique des caractères alphanumériques demi-chasse, le tate-chu-yoko (garder les nombres à l'horizontale dans un texte vertical) et le rubi (furigana). Le texte placé est également gravé en pixels lors de l'export. Un écran où vous pouvez ajouter, rechercher et supprimer des polices disponibles dans l'outil texte. Les polices gratuites supplémentaires au-delà de celles fournies par défaut sont téléchargées à la demande depuis ici, afin de réduire la taille d'installation initiale.","help.entry10.title":"Gestion des outils rapides","help.entry10.desc":"Enregistrez un ensemble d'outils fréquemment utilisés pour les faire défiler d'un seul appui. Ouvrez le popup de gestion par un appui long ou un glissement vers le haut pour modifier les outils enregistrés et leur ordre.","help.entry11.title":"Outil rapide","help.entry11.desc":"Enregistrez des combinaisons de pinceaux et d'outils que vous utilisez souvent, et faites défiler entre elles d'une simple pression sur un bouton. Faites un appui long ou balayez vers le haut sur le bouton ↺ du canevas pour ouvrir une fenêtre de gestion où ajouter, réorganiser et supprimer des entrées. Faites glisser pour changer leur ordre.","help.entry12.title":"Outil tampon","help.entry12.desc":"Place une image enregistrée sur la toile comme un pinceau afin de réutiliser lignes de vitesse, motifs de fond et petits objets sans les redessiner. En mode pixel, les tampons utilisent le même traitement Pixel Art que le filtre pixel art, en conservant des bords de transparence nets pendant la pixellisation et la réduction des couleurs. Mosaïque est un effet distinct et n’est pas utilisé par le mode pixel du tampon. Le panneau permet aussi de régler la rotation et la taille.","help.entry13.title":"Stylet","help.entry13.desc":"Un appui long sur l'outil stylet le fait passer du dessin normal aux sous-outils de remplissage en trame ou de placement de tampon. Permet de passer d'une tâche à l'autre avec le même stylet sans changer d'outil sans arrêt.","help.entry14.title":"Transformer une sélection","help.entry14.desc":"Une zone délimitée avec l'outil de sélection se transforme en choisissant Déplacer, Redimensionner ou Pivoter dans les boutons en bas à gauche du canevas, puis en faisant glisser à l'intérieur de la sélection. Pratique pour repositionner une partie dessinée par erreur, ou pour agrandir une seule zone afin de la mettre en valeur. Le bouton Tout sélectionner de la même barre sélectionne tout le calque courant : vous pouvez donc déplacer, pivoter et redimensionner un calque entier de la même façon (l'ancien outil de transformation a été fusionné ici). Pour déformer plus librement en faisant glisser individuellement les points de la grille, utilisez Transf. libre ou Maillage sur la même barre.","help.entry15.title":"Transformation libre / Déformation maillée","help.entry15.desc":"Un outil de transformation pour tout le calque, accessible depuis le menu édition/réglages en haut à droite du canevas. Contrairement à la transformation d'une sélection, aucune sélection n'est nécessaire : faites glisser les coins ou des points de la grille individuellement avec le doigt pour un résultat libre. Le curseur de densité du panneau de contrôle peut subdiviser la grille jusqu'à 10×10, et pincer deux points différents avec deux doigts à la fois offre un moyen intuitif de pivoter ou redimensionner.","help.entry16.title":"Sélecteur de couleur","help.entry16.desc":"Un selecteur de couleur qui permet de basculer entre HSV et RGB sur un seul ecran. La fonction palette permet d'enregistrer et de rappeler l'ensemble de couleurs utilise. Les palettes peuvent aussi être partagées avec d'autres appareils via l'export de fichier ou un code QR.","help.entry17.title":"Pinceaux favoris","help.entry17.desc":"Touchez l’icône étoile d’un pinceau dans la liste pour le mettre en favori ou l’en retirer (la même interaction que pour les favoris dans le reste de l’app — réglages de remplissage automatique, tampons, polices, filtres de dessin, etc.). L’icône étoile en haut de la liste permet aussi de filtrer pour n’afficher que les favoris. Un pinceau en favori ne peut pas être supprimé par erreur.","help.entry18.title":"Pinceaux personnalisés","help.entry18.desc":"Appuyez longuement sur un pinceau préinstallé dans la liste et choisissez « Dupliquer » pour créer votre propre pinceau personnalisé à partir de celui-ci. Les pinceaux dupliqués peuvent être librement modifiés (épaisseur, opacité, dureté, rotation, densité, dispersion, rayon de flou, etc.) et supprimés lorsqu’ils ne sont plus utiles (les pinceaux préinstallés eux-mêmes ne peuvent être ni modifiés ni supprimés). L’épaisseur et l’opacité réglées avec les curseurs du canevas sont mémorisées pour chaque pinceau, y compris les pinceaux préinstallés, que vous pouvez rétablir à leurs valeurs par défaut depuis le menu du pinceau dans la liste. Vous pouvez aussi les classer dans des dossiers et les marquer comme favoris avec l’icône étoile.","help.entry19.title":"Replis du pinceau","help.entry19.desc":"Activez Contour dans les réglages du pinceau pour utiliser le Mode pliage. Désactivé, le pinceau dessine exactement comme le stylo de contour normal. Activé, le trait du stylo de contour lui-même se plie et s’enroule selon la direction et les courbes du trait que vous dessinez ; il ne génère pas d’ondulations automatiquement. À chaque courbe, une ligne de pli part du bord intérieur, se courbe puis s’efface. Un trait qui continue de tourner dans le même sens reçoit une ligne de pli plus discrète tous les 270°. Il existe cinq types de pliage. Ondulation en plongée place devant la partie dessinée en premier, Ondulation en contre-plongée celle dessinée ensuite. Boucle à droite choisit l’avant et l’arrière comme si le trait s’enroulait vers la droite de son sens de dessin, Boucle à gauche vers la gauche ; ils suivent le trait, pas l’écran. Boucle en croissant suit les courbes en C que vous dessinez pour former des croissants enchaînés. Longueur du pli règle la longueur de la ligne de pli (elle suit la taille du pinceau), Angle du pli règle la force avec laquelle il suit la courbe du trait (à 50 %, il la suit naturellement) et Début de la courbe de la ligne de pli règle l’épaisseur apparente de la matière (à 0 %, elle se courbe dès son point de départ). Avec le stylo de contour, la pression et le Fondu (entrée et sortie) ne modifient que la forme d'ensemble, contour compris ; le contour garde son épaisseur et la couleur ne pâlit jamais. Désactivez Conserver les chevauchements sous Contour pour fusionner les traits qui se chevauchent : leurs jonctions ne sont pas contournées et aucune ligne de pli n'est tracée là où ils se chevauchent ; seul l'extérieur de la forme combinée est contourné. Activez Variation d'épaisseur sous Contour pour épaissir le contour vers le sommet de chaque courbe : il garde la largeur du contour là où la courbe commence et finit, et atteint progressivement la Largeur du contour au sommet (appliqué quand vous levez le stylet).","help.entry20.title":"Calques","help.entry20.desc":"Un système qui permet de dessiner sur un même canevas réparti en plusieurs « calques » transparents. En dessinant l'encrage, la coloration et les arrière-plans sur des calques séparés, vous pouvez refaire uniquement la coloration plus tard ou changer l'arrière-plan sans effacer l'encrage. Les calques empilés plus haut apparaissent devant à l'écran. Chaque ligne de calque dispose de boutons en un geste pour le supprimer ou le fusionner avec le calque du dessous, et un bouton en haut du panneau des calques permet de fusionner tous les calques visibles à la fois.","help.entry21.title":"Mode de fusion","help.entry21.desc":"Modifie la facon dont un calque se combine avec les calques en dessous. Souvent utilise pour superposer des trames ou des effets de couleur.\nNormal : superpose tel quel.\nProduit : assombrit en multipliant avec le calque du dessous. Le choix classique pour les ombres.\nSuperposition (Ecran) : eclaircit en ajoutant de la lumiere. Bon pour les effets lumineux.\nIncrustation : assombrit les zones sombres et eclaircit les zones claires, augmentant le contraste.\nAddition (lueur) : additionne simplement les couleurs. Bon pour les traits de lumiere.\nSoustraction : soustrait les couleurs, donnant un aspect sombre et etouffe.\nAssombrir : conserve la couleur la plus sombre entre les deux calques.\nEclaircir : conserve la couleur la plus claire entre les deux calques.\nDensite couleur -: assombrit et sature la couleur du dessous.\nDensite couleur +: eclaircit et sature la couleur du dessous.\nLumiere crue : une version plus intense du contraste d'Incrustation.\nLumiere douce : une version plus douce du contraste d'Incrustation. Bonne pour des ombrages doux.\nDifference : affiche la difference entre les deux couleurs. Utile pour verifier un decalage de couleur.\nTeinte / Saturation / Couleur / Luminosite : applique uniquement cette propriete (teinte, saturation, couleur ou luminosite) de ce calque sur celui du dessous.\nDensité linéaire + : additionne les deux couleurs puis retire la valeur de base pour assombrir fortement.\nDensité linéaire - : additionne linéairement les deux couleurs pour éclaircir. Ce mode est distinct d’Addition (lueur) : lorsque le calque est semi-transparent, Addition (lueur) donne un résultat plus clair.\nLumière vive : alterne entre densité et éclaircissement selon la couleur supérieure pour un contraste très fort.\nLumière linéaire : augmente ou réduit linéairement la luminosité selon la couleur supérieure.\nLumière ponctuelle : remplace vers le côté sombre ou clair selon la couleur supérieure.\nMélange maximal : applique un seuil au résultat de Lumière vive pour une séparation très franche des couleurs.\nExclusion : effet d’inversion et de différence plus doux que Différence.\nDivision : divise la couleur inférieure par la couleur supérieure, utile pour éclaircir et accentuer les écarts de couleur.\nDans la liste des modes de fusion, chaque mode affiche un aperçu du rouge, du jaune, du bleu, du blanc et du noir posés sur des couleurs allant du sombre au clair (le bas de l’aperçu les montre semi-transparents).","help.entry22.title":"Écrêtage","help.entry22.desc":"Restreint le dessin aux seuls pixels opaques du calque directement en dessous. Lorsque vous voulez colorer sans dépasser du trait, activer l'écrêtage sur un calque de coloriage placé au-dessus d'un calque de trait supprime le risque de dessiner accidentellement en dehors des lignes.","help.entry23.title":"Calque commun","help.entry23.desc":"Les calques ordinaires sont indépendants par image, mais un calque commun partage le même contenu sur plusieurs images et scènes. Les éléments qui ne bougent pas d'une image à l'autre, comme les fonds, peuvent être dessinés une seule fois au lieu d'être redessinés à chaque image. Il apparaît comme une piste dédiée dans la chronologie. Convertit un calque normal en calque commun (qui continue d'afficher le même contenu sur plusieurs images). Vous pouvez aussi fusionner les calques actuellement visibles en un seul avant la conversion. Vous évite de redessiner un élément comme un arrière-plan qui reste identique à chaque image.","help.entry24.title":"Sélection multiple et actions groupées sur les calques","help.entry24.desc":"Le mode de sélection du panneau des calques permet de cocher plusieurs calques à la fois pour les fusionner ou les supprimer en masse. La fusion ne fonctionne qu'entre calques normaux, de trait de remplissage automatique et de remplissage automatique (les calques communs, dossiers et matériels de timeline ne peuvent pas être fusionnés).","help.entry25.title":"Dossiers de calques","help.entry25.desc":"Permet d'organiser plusieurs calques dans un dossier. Garde le panneau des calques lisible même pour des illustrations avec beaucoup de parties. Le détourage ne peut pas traverser les limites d'un dossier, donc si vous l'utilisez, gardez les calques concernés dans le même dossier.","help.entry26.title":"Coloriage automatique","help.entry26.desc":"Crée un calque de coloriage automatique sous le calque de trait pour coloriage automatique et le colore automatiquement selon un « réglage de coloriage automatique » préétabli (une combinaison de couleurs et de trames par partie). Comme vous pouvez tout colorer en une fois après avoir terminé le trait, cela réduit considérablement l’effort de coloriage dans une animation dessinée à la main où le même personnage est dessiné à répétition. Si vous redessinez le trait, une marque de mise à jour apparaît sur la chronologie et le panneau de calques pour vous indiquer que le coloriage automatique doit être réappliqué. Choisir « Exécuter le remplissage automatique » dans le menu à trois points de l’écran timeline recalcule d’un coup tous les calques de remplissage automatique marqués de l’indicateur de mise à jour . Vous évite de le relancer calque par calque dans le panneau des calques après avoir retracé le trait. Chaque partie d’un réglage de remplissage automatique a un réglage pour la gestion de la couleur du trait — une couleur spécifiée, identique à la couleur de remplissage, ou calque de couleur. Choisir le calque de couleur décale la teinte du trait pour correspondre à la couleur de remplissage, afin que le trait ne ressorte pas et se fonde naturellement. À mesure que les réglages s’accumulent, la liste affichée lors de l’attribution des parties s’allonge et devient difficile à parcourir. Depuis les réglages du projet (ou la boîte de dialogue d’attribution des parties dans le panneau des calques), vous pouvez la limiter aux seuls réglages utilisés dans ce projet, gardant la liste claire et facile à choisir. En augmentant « Combler l’écart entre traits et aplat », l’aplat passe plus loin sous le bord adouci des traits et l’écart entre le trait et l’aplat, visible avec un contour ou une couleur de trait identique à l’aplat, se réduit.","help.entry27.title":"Remplissage en dégradé (réglages de remplissage automatique)","help.entry27.desc":"Chaque partie d’un réglage de remplissage automatique peut utiliser un dégradé au lieu d’une couleur unie. Des poignées symétriques déplaçables par glisser permettent d’ajuster intuitivement l’étendue et l’angle du dégradé. Chaque partie peut aussi activer « Contour avec une couleur définie ». Une fois coché, un trait de la couleur et de l’épaisseur choisies est dessiné tout au bord extérieur de la zone remplie (juste contre le dessin au trait). La couleur du contour se choisit librement dans le sélecteur de couleur, et l’épaisseur s’ajuste via le curseur, les boutons ± ou en touchant le nombre pour le saisir directement. Un aperçu s’affiche juste au-dessus des réglages, permettant de vérifier la couleur et l’épaisseur avant d’exécuter le remplissage automatique.","help.entry28.title":"Opérations sur les scènes","help.entry28.desc":"L'onglet scènes de la timeline permet d'ajouter, dupliquer, supprimer, renommer et réorganiser les scènes. Le mode sélection multiple permet de déplacer, dupliquer ou supprimer plusieurs scènes à la fois.","help.entry29.title":"Papier calque","help.entry29.desc":"Superpose en semi-transparence les images avant et après celle que vous éditez actuellement, afin que vous puissiez dessiner en vérifiant comment le mouvement s'enchaîne. Vous pouvez ajuster le nombre d'images affichées (avant et après) ainsi que leur couleur et leur opacité dans les réglages de performance.","help.entry30.title":"Règle","help.entry30.desc":"Un guide pour dessiner des lignes précises difficiles à réaliser à main levée, y compris des règles droites, circulaires, elliptiques et de perspective (utilisant des points de fuite pour le dessin en perspective). La pointe du stylet s'aligne automatiquement sur la règle placée, rendant même les compositions avec une profondeur difficile plus faciles à dessiner que sans règle. Les règles peuvent être déplacées, pivotées et redimensionnées à l'aide de leurs poignées. La règle de perspective fish-eye est une perspective curviligne à cinq points : les lignes horizontales et verticales se courbent en arcs dans le cercle de l'objectif et les lignes de profondeur se rejoignent au centre. Chaque trait suit la ligne qui correspond à la direction dans laquelle vous commencez à dessiner ; faites glisser les poignées pour déplacer le centre, changer le rayon (le point à droite du cercle) et l'incliner (le point du haut).","help.entry31.title":"Fondu","help.entry31.desc":"Une fonction de pinceau qui permet de régler indépendamment la valeur et la distance de l’entrée (début du trait) et de la sortie (fin du trait). Vous pouvez effiler uniquement le début, uniquement la fin, ou utiliser des réglages asymétriques pour contrôler séparément l’épaisseur et l’opacité à chaque extrémité. Avec le stylo de contour, seule la forme d'ensemble (l'épaisseur) change, jamais l'opacité.","help.entry32.title":"Atténuation de trait","help.entry32.desc":"Similaire au fondu, mais plus proche de l'effet d'un « encre qui s'épuise » — la couleur s'estompe ou devient irrégulière plus vous continuez à dessiner. Il reproduit la texture d'un pinceau ou d'un marqueur qui manque d'encre à mesure que vous l'utilisez.","help.entry33.title":"Mélange de couleurs","help.entry33.desc":"En peignant avec un pinceau, mélange la couleur déjà présente sous le pinceau avec la couleur que vous êtes sur le point d'appliquer. Dans le mode de mélange des réglages du pinceau, choisissez Numérique pour peindre sans mélanger, Mélange façon huile pour mélanger comme de la peinture et étirer la couleur ramassée, ou Mélange façon aquarelle pour superposer des lavis transparents dont la couleur s'accumule sur le bord en séchant.","help.entry34.title":"Courbe de pression","help.entry34.desc":"Une fonctionnalité des réglages de saisie au stylet qui permet d'ajuster librement, via un graphique, la relation entre la pression réelle du stylet et son effet sur la taille et l'opacité du pinceau. Que vous vouliez des lignes épaisses même avec une légère pression, ou l'inverse — nécessitant une pression ferme pour obtenir des lignes épaisses —, vous pouvez personnaliser finement la sensation pour l'adapter à vos habitudes. Vous pouvez essayer de dessiner directement pour vérifier l'effet après avoir modifié les réglages.","help.entry35.title":"Remplissage en trame","help.entry35.desc":"Passer le réglage de l'outil seau du remplissage uni au remplissage en trame permet de remplir avec une trame de demi-teintes ou de lignes choisie. Des trames en damier et en grille réservées au mode pixel sont aussi disponibles, pour des remplissages assortis à une texture pixel art. Idéal pour les volants, le tricot, les collants et autres motifs fins fastidieux à dessiner à la main. Vous pouvez aussi créer et ajouter vos propres trames personnalisées, ou les partager avec d'autres utilisateurs.","help.entry36.title":"Mode pixel","help.entry36.desc":"Un réglage disponible séparément sur les pinceaux, les polices et les tampons. L'activer supprime l'anticrénelage pour des contours nets façon pixel art. À utiliser pour un rendu volontairement rétro ou basse résolution. Vous pouvez choisir parmi quatre modes de couleur : sans limite de couleur, couleurs spécifiées, nombre de couleurs spécifié, ou choix depuis une palette, y compris une palette dédiée au pixel art.","help.entry37.title":"Zone de dessin","help.entry37.desc":"Permet de dessiner au-delà des limites d'export. Un cadre rouge sur le canevas marque la zone d'export — ce qui est dessiné en dehors n'est pas exporté, mais cela laisse de la marge pour ajuster plus tard ce qui est montré via des mouvements de caméra comme le panoramique et le zoom. Définissez l'échelle à la création d'un nouveau projet.","help.entry38.title":"Couleur de fond du canevas","help.entry38.desc":"Permet de définir la couleur de fond du canevas du projet. Elle n'affecte pas les exports transparents (WebM transparent), mais vous pouvez la changer pour celle qui vous convient le mieux pour travailler.","help.entry39.title":"Chronologie","help.entry39.desc":"L'écran de gestion de l'axe temporel de votre animation. Organiser des images (des images fixes individuelles) et les lire comme un folioscope crée l'animation. Les pistes de matériaux texte, image, vidéo et audio, les pistes de calques communs et les images clés de caméra sont toutes gérées sur la même chronologie. Ce qui passe devant parmi les textes, les images, les vidéos et le dessin de l'image se règle dans « Ordre d'empilement », pour toute la scène ou pour une plage d'images. Vous pouvez aussi appuyer longuement sur un élément pour en sélectionner plusieurs et les déplacer ensemble.","help.entry40.title":"Scène","help.entry40.desc":"Divise l'intérieur d'un projet (une vidéo) en scènes (plans) pour les gérer séparément. Alors que les dossiers organisent au niveau du projet, les scènes représentent des changements de scène au sein d'une même vidéo. Dans l'onglet des scènes de la timeline, vous pouvez ajouter, dupliquer, supprimer, renommer et réorganiser les scènes. Passer en mode de sélection multiple permet de déplacer, dupliquer ou supprimer plusieurs scènes à la fois.","help.entry41.title":"Opérations sur les fotogrammes","help.entry41.desc":"Dans la liste des fotogrammes, vous pouvez ajouter, dupliquer et supprimer des fotogrammes, et en mode sélection multiple en déplacer, dupliquer ou supprimer plusieurs à la fois. Augmenter le nombre de maintien garde un même fotogramme affiché sur plusieurs cellules (un « maintien »), économisant du travail de dessin sur les plans avec peu de mouvement.","help.entry42.title":"Clips de matériel (texte / image / vidéo / audio)","help.entry42.desc":"Clips placés sur les pistes texte, image, vidéo et audio de la timeline. Un appui long avec glisser sur le corps du clip déplace sa position de départ, et glisser les poignées à chaque extrémité change la portion utilisée. Les matériaux affichés en même temps sont placés automatiquement sur des pistes distinctes. Toucher un clip texte, image ou vidéo ouvre son panneau d'édition sous l'aperçu : le texte, la police, la couleur et le contour ; la position, l'échelle, la rotation sur les axes X/Y/Z et l'opacité (on peut aussi le faire glisser sur l'aperçu, et ajouter des images clés le fait bouger) ; son masque (rectangle ou ellipse, adouci, inversé) ; et la piste où il se trouve. On peut aussi le dupliquer ou le supprimer. Le volume et les fondus d'un clip audio se règlent dans sa fiche détaillée.","help.entry43.title":"Liste des matériels","help.entry43.desc":"Un écran qui rassemble les images, vidéos et audios utilisés dans un projet. Il regroupe les fichiers source de tout ce qui est placé sur la timeline.","help.entry44.title":"Volume","help.entry44.desc":"Un clip audio placé sur la timeline peut avoir son volume et ses durées de fondu d'entrée et de sortie ajustés depuis sa fiche détaillée. Utile pour équilibrer le volume des effets sonores et de la musique, ou adoucir le début et la fin d'un morceau.","help.entry45.title":"Image clé de caméra","help.entry45.desc":"Enregistre la position, le niveau de zoom et la rotation de la caméra à un point précis de la chronologie. Comme les valeurs sont automatiquement interpolées en douceur entre les images clés, vous pouvez facilement ajouter des mouvements de caméra tels que des panoramiques ou des zooms avant/arrière.","help.entry46.title":"Filtre d'effet","help.entry46.desc":"Un effet visuel (flou, correction des couleurs, lueur, pixellisation, etc.) que vous pouvez appliquer à une scène ou une image. Utilisez-le lorsque vous voulez ajuster l'apparence globale de l'écran comme une touche de mise en scène, sans changer le dessin fait main lui-même. Parmi les filtres de dessin, Courbe de tons (un préréglage et son intensité), Niveaux, Netteté, Masque flou, Vignettage (couleur, étendue et densité) et Bord aquarelle existent aussi en filtres d’effet, pour appliquer le même effet à plusieurs images d’un coup. Le filtre pixel art permet aussi de choisir un mode de couleur (sans limite, couleurs spécifiées, nombre de couleurs spécifié, ou choix depuis une palette). Quand les couleurs sont limitées, les zones dont aucune couleur permise n’est proche sont faites de deux ou trois couleurs permises selon un motif régulier (tramage) qui reste en place d’une image à l’autre ; les contours restent nets. Le tramage peut être désactivé pour remplir chaque point de la couleur la plus proche. Plusieurs filtres d'effet peuvent être superposés, et ils s'appliquent dans l'ordre où ils apparaissent sur la timeline. Glisser pour réorganiser la liste des filtres change aussi l'ordre réellement appliqué à l'écran. Un filtre d'effet qui applique un bruit façon grain de pellicule, en le faisant changer image par image. Intensité, quantité (densité du bruit) et taille du grain se règlent avec des curseurs. Revenir à la même image reproduit le même grain (pas de scintillement en scrubbing), tandis que la lecture donne l'impression que le grain bouge. Un filtre d'effet qui fait tomber de la pluie à l'écran. Intensité (nombre de gouttes), vitesse, taille des gouttes et angle du vent se règlent avec des curseurs. Chaque goutte continue de tomber à une vitesse constante à mesure que l'image avance, pour un mouvement de pluie naturel.","help.entry47.title":"Filtres de dessin","help.entry47.desc":"Filtres appliqués directement au calque sélectionné (contrairement aux filtres d’effet, qui s’appliquent à toute la timeline ou à une scène, les filtres de dessin agissent par calque). Les 26 filtres inclus sont Flou gaussien, Flou d'objectif, Style anime, Courbe de tons, Niveaux, Contour, Netteté, Masque flou, Vignettage, Anime rétro, Tube cathodique, Seuil, Œil de poisson, Aberration chromatique, Distorsion optique, Pixel art, Changement de texture, Fondu d'arrière-plan, Accumulation d’encre, Trait automatique, Prisme, Inverser les couleurs, Mosaïque, Bruit, Ombrage sphérique et Bord aquarelle. Bord aquarelle accumule la couleur sur les bords de ce qui est peint sur le calque de travail et rend l'intérieur translucide, comme une aquarelle sèche (avec « Aussi aux limites de couleur », les limites entre couleurs voisines reçoivent aussi un bord). Style anime réduit les couleurs et trace un trait de l’« Épaisseur de bordure » du côté le plus sombre de chaque limite où les couleurs voisines diffèrent d’au moins le « Seuil de différence de couleur » (les traits du dessin ne s’épaississent pas). Prisme peint chaque forme du calque avec les six couleurs de l’arc-en-ciel (rouge, vert, cyan, bleu, violet, rouge), la floute et passe le calque en mode Densité linéaire -. Dessinez d’abord sur leur propre calque de petites formes fines comme des feuilles, d’une couleur sombre : vous obtenez de doux reflets arc-en-ciel sur votre dessin (l’Intensité du flou se mesure comme un flou gaussien ordinaire). L’Ombrage sphérique applique une couleur de lumière à l’intérieur d’une lumière elliptique et une couleur d’ombre à l’extérieur, uniquement sur le dessin (la lumière peut aussi être déplacée sur le canevas). Contour ne réécrit pas le calque d’origine : il dessine seulement le résultat sur un nouveau calque. Distorsion optique applique une déformation localisée, comme à travers un verre de lunettes puissant, uniquement sur la zone peinte sur le canevas avec le « Pinceau » et le « Pot de peinture » du panneau (corrigée avec la « Gomme » ; elle part de la sélection ou du calque de sélection s’il y en a un). Lorsque le canevas comporte une sélection, les filtres de dessin ne s’appliquent qu’à l’intérieur. Pixel art permet aussi de choisir un mode de couleur (sans limite, couleurs définies, nombre de couleurs ou palette). Quand les couleurs sont limitées, les zones dont aucune couleur permise n’est proche sont faites de deux ou trois couleurs permises disposées selon un motif régulier (tramage) qui se rapproche davantage de l’original ; les contours restent nets. Avec un nombre de couleurs, celles-ci sont prises parmi ce qui compose la plus grande partie de l’image. Le tramage peut être désactivé pour remplir chaque point de la couleur la plus proche. Sa taille se règle par la taille des blocs (100 crans, de 1 à 100) ou par des curseurs de points en largeur et en hauteur (1 tout à gauche, la taille du canevas tout à droite) ; déplacer l’un déplace l’autre en gardant les proportions du dessin, et les deux réglages restent liés. Dans les deux cas, les points restent carrés, sans bord semi-transparent. Le Trait automatique permet de modifier les points de contrôle vectoriels temporaires avant d’appliquer le filtre. Faites glisser un point pour déplacer uniquement ce point. Choisissez « Ajouter un point de contrôle » à côté d’Appliquer et touchez une ligne pour ajouter un point, ou choisissez « Supprimer un point de contrôle » et touchez un point pour le supprimer (sans aucun des deux choisi, toucher un point demande confirmation avant de le supprimer). La géométrie modifiée est utilisée directement dans le résultat appliqué, et le déplacement, l’ajout ou la suppression de points peuvent être annulés et rétablis un par un avec Annuler et Rétablir de l’éditeur de filtres. Sur la Courbe de tons, touchez une zone vide pour ajouter un point, faites glisser un point pour le déplacer et appuyez longuement dessus pour le supprimer ; les courbes R, G et B s’appliquent après la courbe RGB. Les Niveaux se règlent aussi séparément pour R, G et B, et le Gamma modifie les tons moyens. L’« Empiètement vers l’intérieur » du contour élargit le bord vers l’intérieur de la forme d’origine, et le nouveau calque du contour est placé juste sous le calque d’origine. L’aberration chromatique permet de répartir le décalage entre X (horizontal), Y (vertical) et Z (vers l’extérieur depuis le centre). Le centre et le rayon de l’œil de poisson se déplacent aussi sur le canevas, avec le + et la poignée du cercle. Vignettage assombrit doucement les quatre coins de toute la toile (les zones transparentes non dessinées reçoivent aussi l’ombre). La « Portée » règle jusqu’où il s’étend des coins vers le centre, et l’« Intensité » à quel point les coins s’assombrissent. Distorsion de lentille fonctionne comme de vraies lunettes à forte correction : ce que l’on voit à travers le verre rétrécit uniformément vers son centre (valeurs négatives, pour la myopie) ou s’agrandit (valeurs positives, pour l’hypermétropie), et le contour se décale en marche au bord du verre. Accumulation d’encre ne se forme qu’à l’intérieur des angles où les traits se rejoignent à l’« Angle maximal » ou moins (à 90°, la valeur initiale, les angles aigus et droits : un V, le côté étroit d’un croisement, une jonction en T, un coin carré), jamais dans les angles plus ouverts : au point de rencontre elle a l’« Épaisseur centrale » depuis le bord du trait, puis s’affine en ligne droite jusqu’à disparaître en une pointe douce au bout de la « Plage » (même avec une grande « Épaisseur centrale », elle ne bombe jamais au-delà de la droite qui relie les extrémités des deux accumulations : au maximum, le milieu reste plat) ; si un trait s’arrête avant, l’accumulation le long de ce trait s’affine jusqu’à disparaître là où il s’arrête, si bien que chaque trait peut avoir sa propre longueur, et les deux accumulations se rejoignent tout de même au milieu de l’angle, aussi épaisses depuis l’un que depuis l’autre trait (celle du trait le plus long continue ensuite de s’affiner jusqu’au bout de la plage). Encrage automatique suit le milieu des traits du brouillon et les dessine fins. Les traits proches l’un de l’autre restent des traits distincts tant qu’un espace les sépare ; seules les petites taches de papier à l’intérieur d’un trait sont comblées. Là où deux traits se rejoignent, ils se rapprochent peu à peu comme dans le brouillon, au lieu de devenir un seul trait au milieu. Là où des traits se croisent ou se superposent, chacun continue comme dans le brouillon (il ne se plie pas vers le croisement et deux traits superposés ne se fondent pas en un seul). Les traits qui se croisent en biais continuent tout droit à travers le croisement, et ceux qui ne font que se toucher (comme le contour des cheveux tracé le long de la tête) restent des traits distincts, chacun de son côté. Les points, comme les yeux, restent des points pleins. Les branches plus courtes que l’« Épaisseur du brouillon » ne sont pas dessinées. « Effiler les extrémités » peut être activé ou désactivé ; désactivé, les traits gardent la même épaisseur jusqu’à leurs extrémités. Fondu d’arrière-plan superpose la lumière et l’ombre de l’arrière-plan avec le mode de fusion « Lumière crue » (la couleur de l’ombre n’est ni noire ni grise, mais celle des ombres de l’arrière-plan lui-même, assombrie). La couleur de l’environnement est superposée à tout le dessin en « Incrustation » pour en fixer la teinte générale, la lumière renvoyée par le sol et par les alentours s’ajoute en « Écran », et une lumière colorée intense comme un néon brille le long du contour en « Addition (lueur) ». « Accorder aux tons de l’arrière-plan » ramène dans sa plage les couleurs plus claires ou plus vives que l’arrière-plan, et donne aux tons sombres, moyens et clairs la dominante des tons de l’arrière-plan de même luminosité (le noir du trait ne change pas). « Intensité du flou » indique combien l’arrière-plan est flouté avant d’en prendre les couleurs.","help.entry48.title":"Automatisations personnalisées (enregistrement d’actions)","help.entry48.desc":"Enregistrez les actions prises en charge sur le canevas ou la timeline sous forme de séquence nommée à réexécuter. Ajoutez un élément depuis Automatisations pour lancer l’enregistrement, puis réordonnez ou supprimez des étapes dans l’écran de vérification avant de sauvegarder. Vous pouvez renommer, réenregistrer, supprimer, filtrer par favoris, exporter et importer les automatisations enregistrées sous forme de fichiers JSON. Pour une automatisation limitée au canevas et entièrement enregistrée dans une seule image, vous pouvez l’exécuter sur l’image actuelle, une plage précise ou toutes les images. Le choix de la plage n’apparaît pas pour les automatisations de timeline ni pour les enregistrements couvrant plusieurs images.","help.entry49.title":"Images clés de calque (animation par partie)","help.entry49.desc":"Définissez la position, l'échelle et la rotation de chaque calque par image ; les images clés sont interpolées automatiquement. Là où les images clés de caméra déplacent tout l'écran, celles-ci ne déplacent qu'un seul calque. Comme chaque partie du remplissage automatique est générée comme un calque distinct, cela fonctionne directement pour l'animation par partie — bouger seulement un bras, ouvrir et fermer seulement une bouche, etc. Chaque image clé peut aussi avoir son propre easing (uniforme, entrée douce, sortie douce, entrée et sortie douces, ou rebond) qui détermine comment elle se raccorde à l'image clé suivante, pour que le mouvement ne soit pas toujours à vitesse constante. Se configure depuis « Animation (images clés) » dans le menu à trois points de chaque calque, dans le panneau des calques. Le dessin du calque lui-même ne change pas : c'est une transformation non destructive de son emplacement d'affichage. Cela n'affecte que l'affichage de la timeline (aperçu / export) et n'a aucun effet sur le dessin réel en mode canevas.","help.entry50.title":"Groupes de calques (déplacer plusieurs parties ensemble)","help.entry50.desc":"Déplace plusieurs calques ensemble avec un seul flux d'images clés. Par exemple, si un « bras » est composé de deux parties de remplissage automatique — peau et manche —, les grouper permet de déplacer les deux avec une seule opération d'image clé. Créez un groupe en sélectionnant plusieurs calques (cases à cocher) dans le panneau des calques puis en appuyant sur l'icône « Grouper » de la barre inférieure. Le mouvement du groupe se superpose aux images clés propres à chaque calque membre (si elles existent), ce qui permet de combiner le mouvement global du groupe avec des ajustements fins par calque. Un calque ne peut appartenir qu'à un seul groupe à la fois.","help.entry51.title":"EndCard (logo de fin)","help.entry51.desc":"Une courte vidéo (environ 5 secondes) avec le logo NIARIM, ajoutée automatiquement à la fin du contenu principal lors de l'export d'une vidéo. La version gratuite ne peut pas le masquer ni le supprimer, mais les membres Premium peuvent l'activer/le désactiver, changer sa durée ou le remplacer.","help.entry52.title":"Enregistrement automatique","help.entry52.desc":"Un enregistrement dédié à la récupération en cas de plantage ou de corruption de fichier. Il s'enregistre automatiquement à chaque modification, comme le dessin, et écrase le plus ancien des 3 enregistrements maximum. Il est géré complètement séparément des enregistrements manuels (emplacements de sauvegarde et arbre de sauvegarde) et ne remplace pas l'enregistrement habituel. On ne vous demande de le restaurer que lors du redémarrage de l'application après une fermeture anormale.","help.entry53.title":"Emplacement de sauvegarde","help.entry53.desc":"Une méthode d'enregistrement dans un nombre fixe d'emplacements de sauvegarde, où vous choisissez à chaque fois l'emplacement à utiliser. Le nombre d'emplacements est déterminé par les réglages (5 pour la qualité basse, 10 pour la qualité moyenne). Comme vous choisissez à chaque fois l'emplacement à écraser, c'est un moyen simple de gérer la conservation de l'état d'un moment particulier.","help.entry54.title":"Arbre de sauvegarde","help.entry54.desc":"Une méthode d'enregistrement où un nouveau point de sauvegarde est créé à chaque fois que vous enregistrez, et vous pouvez créer une branche à partir d'un point de sauvegarde passé pour créer un historique différent. Il n'y a pas de limite au nombre d'enregistrements, ce qui le rend bien adapté à des cas d'usage comme « je veux revenir à cette version et essayer une direction différente ». À l'écran, les points de sauvegarde sont affichés sous forme d'un diagramme en arbre qui pousse du bas vers le haut.","help.entry55.title":"Dossier","help.entry55.desc":"Une fonctionnalité pour regrouper et organiser vos projets (œuvres). Elle prend en charge plusieurs niveaux d'imbrication, vous pouvez donc aussi l'utiliser pour gérer ensemble plusieurs épisodes ou une série de la même œuvre (par exemple, en organisant les projets « Épisode 1 », « Épisode 2 », etc. dans un dossier nommé d'après l'œuvre). Si vous voulez diviser une seule vidéo en scènes distinctes, utilisez la fonctionnalité « Scène » de l'écran du canevas plutôt que des dossiers.","help.entry56.title":"Corbeille","help.entry56.desc":"L'endroit où les projets supprimés sont temporairement déplacés. Vous pouvez les restaurer d'ici jusqu'à ce qu'ils soient définitivement supprimés. Vous pouvez définir le nombre de jours avant la suppression automatique (désactivé/30/60/90 jours) dans les réglages.","help.entry57.title":"Partage (.niashare)","help.entry57.desc":"Un format de fichier dédié pour remettre un projet à quelqu'un d'autre (ou à un autre appareil de vous-même). Lorsque le destinataire ouvre ce fichier, il est dupliqué et ajouté à sa propre liste de projets. Le fichier .niashare d'origine lui-même n'est pas modifié.","help.entry58.title":"Transfert (.niatra)","help.entry58.desc":"Une fonctionnalité permettant de transférer tout l’environnement de l’application — réglages, matériaux, pinceaux, réglages de remplissage automatique, thème, palettes (sélecteur de couleurs et pixel art), et plus — vers un autre appareil en une seule fois. Vous pouvez choisir les éléments individuels à transférer avec des cases à cocher, et inclure en option des projets en cours (les projets sélectionnés sont transférés en entier, avec leurs matériaux et polices). Si vous voulez seulement remettre un projet individuel, vous pouvez aussi utiliser « Partage (.niashare) ».","help.entry59.title":"Export vidéo (MP4, WebM, GIF, AVI)","help.entry59.desc":"Exporte votre oeuvre au format video MP4 standard. La version gratuite a une limite de duree (90 secondes) et ajoute automatiquement une carte de fin (logo de l'application) a la fin de la video. Un format vidéo qui peut être exporté en conservant le canal alpha (les parties transparentes du fond). La lecture transparente ne fonctionne que dans les environnements de lecture compatibles. Idéal pour superposer comme matériau dans d'autres applications. Exporte au format GIF anime. Comme il boucle automatiquement, il convient bien au partage decontracte sur les reseaux sociaux. Si la compatibilité prime, vous pouvez aussi exporter au format AVI (Motion JPEG). Il ne prend pas en charge le canal alpha (transparence), et l'aperçu dans l'application peut ne pas fonctionner sur tous les appareils (vous pouvez tout de même le lire via un lecteur externe depuis Partager). Les comptes gratuits sont limités à 90 secondes de durée de projet (les comptes Premium ont 2 heures). Si ajouter ou dupliquer des images vous ferait dépasser la limite, une alerte apparaît dès que vous appuyez sur le bouton, donc vous ne dépassez jamais réellement 90 secondes.","help.entry60.title":"Écran d'export","help.entry60.desc":"Dans « Préréglage », choisissez « Standard », « Haute qualité » ou « Personnalisé ». Le mode « Personnalisé » permet de régler les images par seconde (FPS). Affiche la progression pendant l'export d'une vidéo ou d'une image, et permet d'annuler en cours de route. Le temps nécessaire dépend des performances de l'appareil.","help.entry61.title":"Place des œuvres","help.entry61.desc":"Publiez vos animations et illustrations dans la communauté sous forme de vidéos YouTube, et parcourez les œuvres des autres utilisateurs. Basculez entre les onglets « Nouveautés », « Classement » et « Abonnements », et effectuez une recherche par titre d’œuvre ou nom du créateur. Passez en mode recherche par tag pour filtrer les œuvres par tag : n’importe quel utilisateur (pas seulement le créateur) peut ajouter ou retirer des tags, mais un tag verrouillé par le créateur ne peut être retiré que par lui, et toucher un tag filtre instantanément les œuvres correspondantes. Toucher une carte d’œuvre ouvre une fenêtre d’aperçu flottante déplaçable et redimensionnable, pour continuer à naviguer sur d’autres écrans pendant la lecture. Le bouton « Voir les détails » ouvre l’écran de détails de l’œuvre (créateur, date de publication, modification des tags, mise en favori, republication, etc.). Toucher le bouton « Suivre » à côté du nom d’un créateur l’ajoute à vos abonnements : l’onglet « Abonnements » regroupe alors uniquement les publications de ce créateur, triées par date. Lorsque quelqu’un vous suit, cela apparaît dans la liste de notifications sous l’icône de cloche en haut de l’écran. Vous pouvez choisir si vos listes d’abonnements/abonnés sont visibles par les autres utilisateurs (privées par défaut), et consulter les listes des autres utilisateurs si elles sont publiques. Vous pouvez repartager l’œuvre de n’importe qui d’autre (sauf la vôtre) avec le bouton « Repartager » ; lorsqu’un créateur que vous suivez repartage l’œuvre de quelqu’un d’autre, cette œuvre apparaît aussi dans votre onglet « Abonnements », triée selon la date la plus récente — sa date de publication d’origine ou sa date de republication (la carte affiche « Repartagé par… »). Les œuvres mises en favori apparaissent regroupées dans l’onglet « Favoris » de l’écran d’accueil, ainsi que dans l’onglet « Favoris » de l’écran des œuvres d’un créateur. Vous pouvez choisir si votre propre liste de favoris est visible par les autres utilisateurs (privée par défaut), et consulter la liste de favoris des autres utilisateurs si elle est rendue publique. Vous pouvez signaler une œuvre en indiquant un motif, et après l’envoi, il vous sera demandé si vous souhaitez bloquer ce créateur. Les vidéos verticales peuvent être visionnées en « mode vertical », qui les enchaîne comme un flux de vidéos courtes. Le nombre de publications par jour est limité : 1 par jour pour les membres gratuits, 3 par jour pour les membres Premium. Le bouton des filtres d’affichage en haut à droite (l’icône d’œil barré) permet de masquer les œuvres que vous ne souhaitez pas voir. Vous pouvez masquer les œuvres marquées « Contient des images ou vidéos générées par IA », et ajouter des titres masqués (comparés uniquement au titre de l’œuvre) et des tags masqués (comparés uniquement aux tags de la Place des œuvres), un par un avec « Ajouter ». Modifiez avec le crayon ou supprimez avec la corbeille ; aucune virgule ni # nécessaire. Ces filtres s’appliquent aux onglets « Nouveautés », « Classement » et « Abonnements » (repartages compris), au mode vertical, aux pages des créateurs, aux détails des œuvres et aux favoris. La mention « Contient des images ou vidéos générées par IA » est déclarée par l’auteur au moment de la publication, et lui seul peut la modifier ensuite (depuis « Mes publications » ou l’écran de détails de l’œuvre).","help.entry62.title":"Rééditer un filigrane","help.entry62.desc":"Toucher un filigrane placé sur la piste de calque commun de la timeline permet de rééditer à tout moment son angle, sa taille, son opacité et sa plage d'affichage (boucle). Vous pouvez l'ajuster finement non seulement à l'enregistrement, mais chaque fois que vous l'utilisez réellement dans un projet.","help.entry63.title":"Filigrane","help.entry63.desc":"Une fonctionnalité réservée aux membres premium qui permet d'ajouter votre propre signature ou logo en filigrane sur les vidéos et images exportées. Vous pouvez ajuster sa position, sa taille et son opacité. Touchez le filigrane placé sur la piste de calque commun de la timeline pour modifier à tout moment son angle, sa taille, son opacité et sa plage d'affichage (bouclage) — pas seulement lors de son enregistrement, mais chaque fois que vous l'utilisez dans un projet. Pour ajouter un filigrane, ouvrez « Ajouter un matériau » dans la timeline, puis choisissez « + Filigrane ».","help.entry64.title":"Premium","help.entry64.desc":"L'abonnement premium porte a 2 heures maximum la limite de 90 secondes de la version gratuite et permet de retirer la carte de fin (logo de l'application) ajoutee automatiquement a la fin de chaque video. Les publicites sont egalement masquees, et vous accedez au filigrane, a la courbe de tons et a la correction des niveaux.","help.entry65.title":"Écran d'accueil","help.entry65.desc":"Le premier écran affiché au lancement de l'app, avec les onglets Projets, Partagés, Œuvres et Corbeille. L'icône de recherche en haut à droite permet de filtrer les projets par nom. Sur l'onglet Projets, le bouton flottant permet de choisir entre créer un nouveau projet ou un nouveau dossier.","help.entry66.title":"Nouveau projet","help.entry66.desc":"Définissez la taille du canevas, les fps, la durée (en secondes — ensuite maintenue synchronisée avec les changements d’images faits dans la timeline), la zone de dessin (permet de dessiner au-delà des limites d’export) et les réglages de remplissage automatique à utiliser, le tout avant de créer le projet.","help.entry67.title":"Écran des détails du projet","help.entry67.desc":"Un écran pour consulter et modifier au même endroit les réglages propres au projet — nom, miniature, statut favori, et quels réglages de remplissage automatique sont activés. L’accès à l’arbre de sauvegarde se trouve aussi ici.","help.entry68.title":"Réglages de thème","help.entry68.desc":"Choisissez la palette de couleurs globale de l'app dans la liste des thèmes, ou personnalisez librement la couleur d'accent. Les titres/libellés et le texte courant utilisent des polices distinctes, ce qui permet de changer l'apparence de l'app tout en gardant une bonne lisibilité.","help.entry69.title":"Réglages de l'espace de travail","help.entry69.desc":"Regroupe des réglages comme le mode gaucher (inverse les panneaux ancrés), le basculement manuel du mode PC/DeX, et les conditions d'affichage de l'outil main. Ajustez la disposition selon votre appareil et votre main dominante.","help.entry70.title":"Réglages des gestes","help.entry70.desc":"Permet d'associer des actions — annuler/rétablir, déplacement de fotogramme, pipette et plus — à un appui à deux doigts, un appui à trois doigts, un glissement à deux doigts ou un appui long. Les boutons du stylet (sur les modèles compatibles) peuvent aussi être associés séparément. Pratique pour déclencher des actions fréquentes d'un seul geste sans changer d'outil.","help.entry71.title":"Réglages du stylet","help.entry71.desc":"En plus de la courbe de pression pour tablettes et écrans à stylet, cet écran permet d'associer des actions — comme basculer la gomme ou la pipette — aux boutons latéraux d'un stylet compatible.","help.entry72.title":"Détection d'inclinaison","help.entry72.desc":"Un réglage qui utilise les données d'inclinaison d'un stylet compatible pour épaissir ou affiner le trait quand vous couchez la pointe, reproduisant une sensation plus proche d'un vrai outil de dessin. Activez-le ou désactivez-le depuis les réglages de performance.","help.entry73.title":"Réglages de performance","help.entry73.desc":"Choisissez parmi les préréglages de qualité basse, moyenne ou haute selon les capacités de votre appareil, ou configurez chaque élément individuellement (personnalisé). En plus de la méthode d'enregistrement, des performances, du papier calque et de la détection d'inclinaison, les réglages qui affectent la taille de l'application et sa fluidité — comme la longueur de l'historique d'annulation et la suppression automatique de la corbeille — sont également regroupés ici.","help.entry74.title":"Réglages détaillés du seau de peinture","help.entry74.desc":"Depuis la section « Seau de peinture » des réglages, vous pouvez ajuster la tolérance (quelle différence de couleur par rapport au pixel cliqué compte encore comme la même zone), l'extension en px (de combien la zone remplie dépasse la bordure pour combler les écarts du trait) et le remplissage sous le trait (compose le remplissage étendu derrière les pixels existants au lieu de peindre par-dessus le trait, préservant son apparence). Les ajuster aide quand le trait a de petits écarts ou que le remplissage semble incomplet.","help.entry75.title":"Longueur de l'historique d'annulation","help.entry75.desc":"Dans les réglages de performance, vous pouvez ajuster le nombre d'actions que l'annulation peut remonter. Un nombre plus élevé donne plus de liberté pour expérimenter, mais utilise aussi plus de mémoire — réduisez-le sur les appareils bas de gamme pour rester fluide.","help.entry76.title":"Import de polices","help.entry76.desc":"Permet de charger un fichier de police directement depuis le stockage de l'appareil. Ajoutez-le depuis l'onglet « Importer » de la gestion des polices, dans les réglages. Pratique pour utiliser une police personnalisée non distribuée, ou une police commerciale achetée.","help.entry77.title":"Libérer de l'espace","help.entry77.desc":"Consultez l'espace utilisé par NIARIM sur votre appareil, ainsi qu'une répartition de son contenu (projets, matériaux, fichiers exportés, brosses/trames/tampons/polices personnalisés, cache et corbeille) sous forme de graphiques circulaires. Vous pouvez vider le cache, supprimer les matériaux inutilisés dans tous les projets, vider la corbeille, organiser vos projets ou effacer toutes les données (réinitialiser).","help.entry78.title":"Widgets de l’écran d’accueil","help.entry78.desc":"Réglages des trois types de widgets à placer sur l’écran d’accueil du téléphone : une image d’une œuvre (écran de démarrage), le widget de création et le widget de la place. Les widgets eux-mêmes s’ajoutent par appui long sur l’écran d’accueil, pas depuis l’application. « Choisir une œuvre » reprend le même tri, mode d’affichage, recherche et filtre des favoris que l’onglet des projets, puis permet de choisir l’image exacte à afficher dans un aperçu doté de commandes de lecture. Les widgets de création et de la place permettent de choisir si le fond suit le thème de l’application ou utilise une couleur définie par vous.","help.lead":"Les 79 rubriques et descriptions de l'aide de l'application, accessibles par recherche ou catégorie."},"es":{"help.category.tool":"Herramientas","help.category.brush":"Pincel","help.category.penInput":"Entrada de lápiz","help.category.drawing":"Dibujo","help.category.layer":"Capas","help.category.animation":"Animación","help.category.save":"Guardado","help.category.projectManagement":"Gestión de proyectos","help.category.export":"Exportación","help.category.community":"Comunidad","help.category.premium":"Premium","help.category.settings":"Ajustes","help.entry0.title":"Controles básicos (toque, pulsación larga, deslizamiento)","help.entry0.desc":"Un toque simple en un icono de la barra de herramientas cambia a esa herramienta. Mantén pulsado ese icono, o deslízalo hacia arriba, para abrir sus ajustes detallados. Tras esa pulsación larga o ese deslizamiento encontrarás: pincel, trama, sello o relleno con lazo para la pluma; relleno sólido o con trama para el bote; rectángulo, lazo o selección automática para la herramienta de selección; desenfoque o mosaico para la herramienta de dedo; y la lista de herramientas registradas para el cambio rápido. Al tocar dos veces un icono aparece una breve descripción en la parte inferior de la pantalla.\\nEn el lienzo, pellizca con dos dedos para ampliar o reducir, arrastra con dos dedos para desplazar, toca con dos dedos para deshacer y con tres para rehacer. Toca dos veces el borde izquierdo o derecho de la pantalla para ir al fotograma anterior o siguiente.\\nSi tienes conectado un ratón o una tableta gráfica, la rueda amplía y el arrastre con el botón central desplaza.","help.entry1.title":"Herramienta de pluma","help.entry1.desc":"La herramienta básica para dibujar líneas en el lienzo. Mantén pulsado para cambiar el tipo, tamaño y color del pincel (un doble toque muestra un resumen rápido). Es compatible con la presión y la inclinación de tabletas/lápices ópticos, y ajustar la curva de presión en Ajustes > Entrada de lápiz permite personalizar con precisión cómo la presión afecta al tamaño y la opacidad. Al cambiar de subherramienta de pluma, puedes aplicar tramas o colocar sellos con la misma herramienta.","help.entry2.title":"Herramienta goma de borrar","help.entry2.desc":"La contraparte de la herramienta de pluma, usada para borrar lo que has dibujado. Al igual que un pincel, puedes ajustar su tamaño y opacidad, y los ajustes de pincel como el desvanecido y la atenuación de trazo también se aplican. En lugar de \"añadir\" a las partes transparentes de una capa, \"elimina\" el dibujo existente, por lo que la capa de abajo se vuelve visible a través de ella.","help.entry3.title":"Herramienta cubo de pintura","help.entry3.desc":"Rellena un área cerrada de una sola vez. Toca dentro de un área rodeada por líneas y toda el área se rellena con el color (o trama) seleccionado. Si hay huecos en las líneas, el relleno puede extenderse a áreas no deseadas, así que asegúrate de que las líneas estén bien cerradas antes de usarlo. Puedes alternar entre relleno plano y relleno de trama en los ajustes. Los ajustes detallados (tolerancia, expansión en px, pasar por debajo de las líneas) se pueden configurar desde «Cubo de pintura» en los ajustes.","help.entry4.title":"Relleno de lazo","help.entry4.desc":"Traza con el dedo para formar un área poligonal y luego rellena el interior de una sola vez. A diferencia del cubo de pintura, puedes definir el área tú mismo incluso donde las líneas no estén cerradas, lo que lo hace ideal para formas complejas o áreas con líneas interrumpidas. Con «Rellenar área cerrada» activado, todas las zonas cerradas por líneas dentro del lazo se rellenan de una vez, sean cuantas sean, como con el cubo de pintura (el espacio entre el lazo y el dibujo queda como está).","help.entry5.title":"Herramienta cuentagotas","help.entry5.desc":"Toma el color en la posición tocada y lo establece como color de dibujo. Muestrea el aspecto compuesto de todas las capas tal como se muestra en la pantalla, por lo que capta con precisión el \"color tal como se ve\" incluso donde se superponen varias capas.","help.entry6.title":"Herramienta de selección","help.entry6.desc":"Selecciona parte del lienzo para poder mover, rotar o escalar solo esa área. Mantén pulsado para elegir entre tres métodos de selección: \"Selección rectangular\", \"Selección de lazo\" (contorno libre), o \"Selección automática\" (varita mágica: agrupa automáticamente áreas de color similar). Mientras hay una selección activa, un contorno marca el área seleccionada en el lienzo, y la misma área permanece fija en todos los fotogramas y capas hasta que la deselecciones. En la selección de lazo, al activar \"Ajustar a las líneas\" se miran las zonas en que el dibujo de líneas divide el lienzo, igual que hace el bote de pintura, y se seleccionan solo las zonas que quedan mayormente dentro del lazo. El borde de la selección sigue exactamente el borde exterior del dibujo de líneas: las líneas que rodean esas zonas y las de su interior se seleccionan con ellas (una línea que sigue hacia fuera del contorno se corta donde lo deja). Los colores rellenos cuentan como zonas propias, igual que con el bote de pintura, así que una capa con rellenos y líneas también se selecciona según la forma del dibujo. Las interrupciones de una línea de hasta el ancho de \"Tolerancia de huecos\" se tratan como cerradas. Si no hay dibujo de líneas dentro del lazo, se selecciona el lazo tal como se trazó. Las líneas se toman de la referencia de selección (\"Solo capa de trabajo\" / \"Todas las capas visibles\").","help.entry7.title":"Herramienta de dedo (distorsión)","help.entry7.desc":"Distorsiona los píxeles empujándolos en la dirección en la que arrastras el dedo, como si untaras pintura húmeda con un dedo. Se usa menos para correcciones precisas y más cuando quieres distorsionar orgánicamente líneas ya dibujadas para darles más expresión.","help.entry8.title":"Herramienta de forma","help.entry8.desc":"Dibuja formas precisas como líneas, rectángulos y círculos con un solo gesto. Arrastrar desde el punto inicial hasta el punto final muestra una vista previa en vivo, y se finaliza al levantar el dedo. Útil cuando necesitas líneas rectas o círculos perfectos difíciles de dibujar a mano alzada.","help.entry9.title":"Herramienta de texto","help.entry9.desc":"Coloca texto en el lienzo. Puedes elegir la fuente, el tamaño, el color y la dirección de escritura vertical/horizontal. La escritura vertical admite la rotación automática de caracteres alfanuméricos de medio ancho, el tate-chu-yoko (mantener los números en horizontal dentro de texto vertical) y el rubi (furigana). El texto colocado también se graba como píxeles al exportar. Una pantalla donde puedes añadir, buscar y eliminar fuentes disponibles en la herramienta de texto. Las fuentes gratuitas adicionales más allá de las incluidas por defecto se descargan bajo demanda desde aquí, para mantener reducido el tamaño de instalación inicial.","help.entry10.title":"Gestión de herramientas rápidas","help.entry10.desc":"Registra un conjunto de herramientas usadas con frecuencia para alternar entre ellas con un solo toque. Abre el popup de gestión con una pulsación larga o un deslizamiento hacia arriba para editar las herramientas registradas y su orden.","help.entry11.title":"Herramienta rápida","help.entry11.desc":"Registra combinaciones de pinceles y herramientas que uses a menudo, y alterna entre ellas con un solo toque de botón. Mantén pulsado o desliza hacia arriba el botón ↺ del lienzo para abrir un panel de gestión donde añadir, reordenar y eliminar entradas. Arrastra para cambiar su orden.","help.entry12.title":"Herramienta de sello","help.entry12.desc":"Coloca una imagen registrada en el lienzo como si fuera un pincel para reutilizar líneas de velocidad, patrones de fondo y pequeños objetos sin volver a dibujarlos. En modo píxel, los sellos usan el mismo procesamiento Pixel Art que el filtro de arte píxel, conservando bordes de transparencia duros al pixelar y reducir colores. Mosaico es un efecto independiente y no se usa en el modo píxel del sello. El panel del sello también permite ajustar la rotación y el tamaño.","help.entry13.title":"Lápiz","help.entry13.desc":"Mantener pulsada la herramienta lápiz la cambia del dibujo normal a las subherramientas de relleno con tramas o colocación de sellos. Permite alternar entre varias tareas con el mismo lápiz sin cambiar de herramienta constantemente.","help.entry14.title":"Transformar una selección","help.entry14.desc":"Una zona delimitada con la herramienta de selección se puede transformar eligiendo Mover, Escalar o Rotar en los botones de la esquina inferior izquierda del lienzo y arrastrando dentro de la selección. Útil para reposicionar una parte dibujada por error, o para ampliar solo una zona para destacarla. Al pulsar Seleccionar todo en esa misma barra se selecciona la capa entera, así que puedes mover, rotar y escalar toda una capa del mismo modo (la antigua herramienta de transformación se ha integrado aquí). Si quieres deformar con más libertad arrastrando cada punto de la cuadrícula, usa Transf. libre o Malla en la misma barra.","help.entry15.title":"Transformación libre / Deformación de malla","help.entry15.desc":"Una herramienta de transformación para toda la capa, que se abre desde el menú de edición/ajustes en la esquina superior derecha del lienzo. A diferencia de transformar una selección, no hace falta seleccionar nada: arrastra las esquinas o puntos individuales de la cuadrícula con el dedo para un resultado libre. El control deslizante de densidad del panel puede subdividir la malla hasta 10×10, y pellizcar dos puntos distintos con dos dedos a la vez ofrece una forma intuitiva de rotar o escalar.","help.entry16.title":"Selector de color","help.entry16.desc":"Un selector de color que te permite alternar entre HSV y RGB en una sola pantalla. La funcion de paleta te permite guardar y recuperar el conjunto de colores que estas usando. Las paletas también se pueden compartir con otros dispositivos mediante exportación de archivo o código QR.","help.entry17.title":"Pinceles favoritos","help.entry17.desc":"Toca el icono de estrella de un pincel en la lista para marcarlo o desmarcarlo como favorito (la misma interacción que se usa para los favoritos en el resto de la app: ajustes de relleno automático, sellos, fuentes, filtros de dibujo, etc.). El icono de estrella en la parte superior de la lista también permite filtrar para mostrar solo los favoritos. Un pincel favorito no puede eliminarse por error.","help.entry18.title":"Pinceles personalizados","help.entry18.desc":"Mantén pulsado un pincel preinstalado en la lista y elige «Duplicar» para crear tu propio pincel personalizado basado en él. Los pinceles duplicados se pueden editar libremente (grosor, opacidad, dureza, rotación, densidad, dispersión, radio de desenfoque y más) y eliminar cuando ya no los necesites (los pinceles preinstalados no se pueden editar ni eliminar). El grosor y la opacidad que ajustas con los deslizadores del lienzo se recuerdan para cada pincel, incluidos los preinstalados, que puedes devolver a sus valores predeterminados desde el menú del pincel en la lista. También puedes organizarlos en carpetas y marcarlos como favoritos con el icono de estrella.","help.entry19.title":"Pliegues del pincel","help.entry19.desc":"Activa Contorno en los ajustes del pincel para usar el Modo de pliegue. Desactivado, el pincel dibuja igual que el lápiz de contorno normal. Activado, la propia línea del lápiz de contorno se pliega y se riza según la dirección y las curvas del trazo que dibujas; no genera ondas automáticamente. En cada curva, una línea de pliegue sale del borde interior, se curva y se desvanece. Si el trazo sigue girando en el mismo sentido, aparece una línea de pliegue más sutil cada 270°. Hay cinco tipos de pliegue. Onda (vista superior) pone delante la parte dibujada antes y Onda (contrapicado), la dibujada después. Rizo a la derecha decide qué queda delante como si se enrollara hacia la derecha de la dirección de dibujo, y Rizo a la izquierda, hacia la izquierda; siguen el trazo, no la pantalla. Rizo de media luna sigue las curvas en C que dibujas para formar medias lunas encadenadas. Longitud del pliegue ajusta la longitud de la línea de pliegue (se adapta al tamaño del pincel), Ángulo del pliegue ajusta cuánto sigue la curva del trazo (al 50 % la sigue de forma natural) e Inicio de la curva de la línea de pliegue ajusta el grosor aparente del material (al 0 % se curva justo desde donde se ramifica). En el lápiz de contorno, la presión y el Desvanecido (entrada y salida) solo cambian la forma general, contorno incluido; el contorno conserva su grosor y el color nunca se aclara. Desactiva Mantener superposiciones en Contorno para fusionar los trazos superpuestos: sus uniones no se contornean ni se dibujan líneas de pliegue donde se superponen; solo se contornea el exterior de la forma combinada. Activa Variación de grosor en Contorno para engrosar el contorno hacia el vértice de cada curva: conserva el ancho del contorno donde la curva empieza y termina, y alcanza poco a poco el Ancho del contorno en el vértice (se aplica al levantar el lápiz).","help.entry20.title":"Capas","help.entry20.desc":"Un sistema que te permite dibujar en un mismo lienzo repartido en varias \"capas\" transparentes. Al dibujar el lineart, el coloreado y los fondos en capas separadas, puedes rehacer solo el color más tarde o cambiar el fondo sin borrar el lineart. Las capas apiladas más arriba aparecen delante en pantalla. Cada fila de capa tiene botones de un toque para eliminarla o combinarla con la capa de abajo, y un botón en la parte superior del panel de capas permite combinar todas las capas visibles a la vez.","help.entry21.title":"Modo de fusión","help.entry21.desc":"Cambia como se combina una capa con las capas de debajo. Se usa a menudo al superponer tramas o efectos de color.\nNormal: superpone tal cual.\nMultiplicar: oscurece multiplicando con la capa inferior. La opcion clasica para sombras.\nTrama: aclara sumando luz. Bueno para efectos de brillo.\nSuperponer: oscurece las zonas oscuras y aclara las claras, aumentando el contraste.\nSuma (brillo): suma los colores directamente. Bueno para destellos de luz.\nRestar: resta colores, dando un aspecto oscuro y apagado.\nOscurecer: conserva el color mas oscuro entre ambas capas.\nAclarar: conserva el color mas claro entre ambas capas.\nSubexposicion de color: oscurece y satura el color inferior.\nSobreexposicion de color: aclara y satura el color inferior.\nLuz fuerte: una version mas intensa del contraste de Superponer.\nLuz suave: una version mas suave del contraste de Superponer. Buena para sombreados suaves.\nDiferencia: muestra la diferencia entre los dos colores. Util para comprobar desajustes de color.\nMatiz / Saturacion / Color / Luminosidad: aplica solo esa propiedad (matiz, saturacion, color o brillo) de esta capa sobre la de abajo.\nSubexposición lineal: suma ambos colores y resta el valor base para oscurecer con fuerza.\nSobreexposición lineal: suma linealmente ambos colores para aclarar. Es un modo distinto de Suma (brillo): con la capa semitransparente, Suma (brillo) resulta más claro.\nLuz intensa: alterna entre subexposición y sobreexposición según el color superior para crear un contraste muy fuerte.\nLuz lineal: aumenta o reduce linealmente el brillo según el color superior.\nLuz focal: sustituye hacia el lado más oscuro o más claro según el color superior.\nMezcla definida: aplica un umbral al resultado de Luz intensa para separar los colores con dureza.\nExclusión: efecto de inversión y diferencia más suave que Diferencia.\nDividir: divide el color inferior por el superior, útil para aclarar y destacar diferencias de color.\nEn la lista de modos de fusión, cada modo muestra un ejemplo de rojo, amarillo, azul, blanco y negro superpuestos sobre colores de oscuro a claro (la parte inferior del ejemplo los muestra semitransparentes).","help.entry22.title":"Recorte","help.entry22.desc":"Restringe el dibujo únicamente a los píxeles opacos de la capa situada justo debajo. Cuando quieras colorear sin salirte de las líneas, activar el recorte en una capa de coloreado colocada sobre una capa de líneas elimina el riesgo de dibujar accidentalmente fuera de las líneas.","help.entry23.title":"Capa común","help.entry23.desc":"Las capas normales son independientes por fotograma, pero una capa común comparte el mismo contenido en varios fotogramas y escenas. Los elementos que no se mueven entre fotogramas, como los fondos, se pueden dibujar una sola vez en lugar de volver a dibujarlos en cada fotograma. Se muestra como una pista dedicada en la línea de tiempo. Convierte una capa normal en una capa común (que sigue mostrando el mismo contenido en varios fotogramas). También puedes fusionar las capas visibles en una sola antes de convertirla. Te ahorra volver a dibujar algo como un fondo que se mantiene igual en cada fotograma.","help.entry24.title":"Selección múltiple y acciones masivas de capas","help.entry24.desc":"El modo de selección del panel de capas permite marcar varias capas a la vez para fusionarlas o eliminarlas en bloque. La fusión solo funciona entre capas normales, de línea de relleno automático y de relleno automático (las capas comunes, carpetas y materiales de línea de tiempo no se pueden fusionar).","help.entry25.title":"Carpetas de capas","help.entry25.desc":"Permite organizar varias capas en una carpeta. Mantiene el panel de capas manejable incluso en ilustraciones con muchas partes. El recorte no puede cruzar los límites de las carpetas, así que si lo usas, mantén las capas relevantes en la misma carpeta.","help.entry26.title":"Coloreado automático","help.entry26.desc":"Crea una capa de coloreado automático debajo de la capa de líneas para coloreado automático y la colorea automáticamente según un \"ajuste de coloreado automático\" ya creado (una combinación de colores y tramas por parte). Como puedes colorear todo de una vez después de terminar las líneas, reduce enormemente el esfuerzo de coloreado en animación dibujada a mano donde se dibuja repetidamente el mismo personaje. Si vuelves a dibujar las líneas, aparece una marca de actualización en la línea de tiempo y el panel de capas para indicarte que hay que volver a aplicar el coloreado automático. Elegir \"Ejecutar relleno automático\" en el menú de tres puntos de la pantalla de línea de tiempo recalcula de una vez todas las capas de relleno automático marcadas con el indicador de actualización . Te ahorra ejecutarlo capa por capa en el panel de capas tras volver a dibujar la línea. Cada parte de un ajuste de relleno automático tiene un ajuste sobre cómo tratar el color de la línea: un color especificado, igual al color de relleno, o calco de color. Elegir calco de color desplaza el HSL del color de línea para que coincida con el de relleno, de modo que la línea no destaque y se integre de forma natural. A medida que se acumulan ajustes, la lista mostrada al asignar partes se alarga y cuesta más recorrerla. Desde los ajustes del proyecto (o el diálogo de asignación de partes en el panel de capas) puedes limitarla a solo los ajustes usados en este proyecto, manteniendo la lista ordenada y fácil de elegir. Al subir «Cerrar el hueco entre líneas y relleno», el relleno llega más bajo el borde suave de las líneas y se reduce el hueco entre el dibujo lineal y el relleno que se ve con un contorno o un color de línea igual al relleno.","help.entry27.title":"Relleno degradado (ajustes de relleno automático)","help.entry27.desc":"Cada parte de un ajuste de relleno automático puede usar un degradado en lugar de un color sólido. Los tiradores simétricos que puedes arrastrar permiten ajustar de forma intuitiva el alcance y el ángulo del degradado. Cada parte también puede activar «Contorno con color especificado». Al marcarlo, se dibuja una línea del color y grosor elegidos justo en el borde más exterior del área rellenada (pegada al dibujo lineal). El color del contorno se puede elegir libremente con el selector de color, y el grosor se puede ajustar con el deslizador, los botones ± o tocando el número para escribirlo directamente. Justo encima de los ajustes aparece una vista previa, para poder comprobar el color y el grosor antes de ejecutar el relleno automático.","help.entry28.title":"Operaciones con escenas","help.entry28.desc":"La pestaña de escenas de la línea de tiempo permite añadir, duplicar, eliminar, renombrar y reordenar escenas. El modo de selección múltiple permite mover, duplicar o eliminar varias escenas a la vez.","help.entry29.title":"Papel cebolla","help.entry29.desc":"Superpone en semitransparencia los fotogramas anterior y posterior al que estás editando, para que puedas dibujar mientras compruebas cómo se conecta el movimiento. Puedes ajustar cuántos fotogramas se muestran (antes y después) y su color y opacidad en los ajustes de rendimiento.","help.entry30.title":"Regla","help.entry30.desc":"Una guía para dibujar líneas precisas difíciles de lograr a mano alzada, incluidas reglas rectas, circulares, elípticas y de perspectiva (que usan puntos de fuga para el dibujo en perspectiva). La punta del lápiz se ajusta automáticamente a la regla colocada, facilitando incluso composiciones con profundidad difícil de dibujar sin regla. Las reglas se pueden mover, rotar y redimensionar usando sus controladores. La regla de perspectiva de ojo de pez es una perspectiva curvilínea de cinco puntos: las líneas horizontales y verticales se curvan en arcos dentro del círculo de la lente y las líneas de profundidad se juntan en el centro. Cada trazo sigue la línea que coincide con la dirección en la que empiezas a dibujar; arrastra los controladores para mover el centro, cambiar el radio (el punto a la derecha del círculo) e inclinarla (el punto de arriba).","help.entry31.title":"Desvanecido","help.entry31.desc":"Una función del pincel que permite ajustar de forma independiente el valor y la distancia de entrada (inicio del trazo) y salida (final del trazo). Puedes afinar solo el inicio, solo el final o usar ajustes asimétricos para controlar por separado el grosor y la opacidad en cada extremo. En el lápiz de contorno solo cambia la forma general (el grosor), nunca la opacidad.","help.entry32.title":"Atenuación de trazo","help.entry32.desc":"Similar al desvanecido, pero más cercano al efecto de \"la tinta se agota\": el color se desvanece o se vuelve irregular cuanto más sigues dibujando. Reproduce la textura de un pincel o rotulador quedándose sin tinta a medida que lo usas.","help.entry33.title":"Mezcla de colores","help.entry33.desc":"Al pintar con un pincel, mezcla el color que ya hay justo debajo del pincel con el color que estás a punto de aplicar. En el modo de mezcla de los ajustes del pincel puedes elegir Digital para pintar sin mezclar, Mezcla estilo óleo para mezclar como la pintura y arrastrar el color recogido, o Mezcla estilo acuarela para superponer aguadas transparentes que, al secarse, acumulan color en el borde.","help.entry34.title":"Curva de presión","help.entry34.desc":"Una función en los ajustes de entrada de lápiz que permite ajustar libremente, mediante un gráfico, la relación entre la presión real del lápiz y cómo afecta al tamaño y la opacidad del pincel. Ya sea que quieras líneas gruesas incluso con poca presión, o lo contrario —necesitando presión firme para obtener líneas gruesas—, puedes personalizar finamente la sensación para adaptarla a tus hábitos. Puedes probar a dibujar en el momento para comprobar el efecto tras cambiar los ajustes.","help.entry35.title":"Relleno con tramas","help.entry35.desc":"Cambiar el ajuste de la herramienta de cubo de relleno sólido a relleno con tramas permite rellenar con una trama de semitonos o líneas elegida. También hay tramas de damero y cuadrícula exclusivas del modo píxel, para rellenos que combinan con una textura pixel art. Ideal para volantes, tejidos de punto, medias y otros patrones finos tediosos de dibujar a mano. También puedes crear y añadir tus propias tramas personalizadas, o compartirlas con otros usuarios.","help.entry36.title":"Modo píxel","help.entry36.desc":"Un ajuste disponible por separado en pinceles, fuentes y sellos. Al activarlo se elimina el suavizado, dando bordes nítidos al estilo pixel art. Úsalo cuando quieras un aire deliberadamente retro o de baja resolución. Puedes elegir entre cuatro modos de color: sin límite de color, especificar colores, especificar el número de colores o elegir desde una paleta, incluida una paleta específica para pixel art.","help.entry37.title":"Área de dibujo","help.entry37.desc":"Permite dibujar más allá de los límites de exportación. Un marco rojo en el lienzo señala el área de exportación: lo dibujado fuera de él no se exporta, pero deja margen para ajustar después qué se muestra con movimientos de cámara como paneo y zoom. Define la escala al crear un nuevo proyecto.","help.entry38.title":"Color de fondo del lienzo","help.entry38.desc":"Permite definir el color de fondo del lienzo del proyecto. No afecta a las exportaciones transparentes (WebM transparente), pero puedes cambiarlo al color que te resulte más cómodo para trabajar.","help.entry39.title":"Línea de tiempo","help.entry39.desc":"La pantalla para gestionar el eje temporal de tu animación. Organizar fotogramas (imágenes fijas individuales) y reproducirlos como un flipbook crea la animación. Las pistas de material de texto, imagen, vídeo y audio, las pistas de capas comunes y los fotogramas clave de cámara se gestionan todos en la misma línea de tiempo. Qué se muestra delante entre los textos, imágenes, vídeos y el dibujo del fotograma se ajusta en «Orden de apilado», para toda la escena o para un rango de fotogramas. También puedes mantener pulsado un elemento para seleccionar varios y moverlos a la vez.","help.entry40.title":"Escena","help.entry40.desc":"Divide el interior de un proyecto (un vídeo) en escenas (cortes) para gestionarlas por separado. Mientras que las carpetas organizan a nivel de proyecto, las escenas representan cambios de escena dentro de un mismo vídeo. En la pestaña de escenas de la línea de tiempo puedes añadir, duplicar, eliminar, renombrar y reordenar escenas. Al cambiar al modo de selección múltiple puedes mover, duplicar o eliminar varias escenas a la vez.","help.entry41.title":"Operaciones con fotogramas","help.entry41.desc":"En la lista de fotogramas puedes añadir, duplicar y eliminar fotogramas, y en modo de selección múltiple mover, duplicar o eliminar varios a la vez. Aumentar el número de retención mantiene un mismo fotograma mostrado durante varias celdas (una \"retención\"), ahorrando trabajo de dibujo en planos con poco movimiento.","help.entry42.title":"Clips de material (texto / imagen / vídeo / audio)","help.entry42.desc":"Clips colocados en las pistas de texto, imagen, vídeo y audio de la línea de tiempo. Mantén pulsado y arrastra el cuerpo del clip para mover su posición de inicio, o arrastra las asas de los extremos para cambiar cuánto se usa. Los materiales que se muestran al mismo tiempo se colocan automáticamente en filas propias. Al tocar un clip de texto, imagen o vídeo se abre su panel de edición bajo la vista previa: el texto, la fuente, el color y el contorno; la posición, la escala, la rotación en los ejes X/Y/Z y la opacidad (también se puede arrastrar en la vista previa, y al añadir fotogramas clave se mueve); su máscara (rectángulo o elipse, difuminada, invertida); y la fila en la que está. Ahí también se puede duplicar o eliminar. El volumen y los fundidos de un clip de audio se ajustan en su hoja de detalles.","help.entry43.title":"Lista de materiales","help.entry43.desc":"Una pantalla que reúne las imágenes, vídeos y audios usados en un proyecto. Recopila los archivos de origen de todo lo colocado en la línea de tiempo.","help.entry44.title":"Volumen","help.entry44.desc":"Un clip de audio colocado en la línea de tiempo puede tener su volumen y las duraciones de fundido de entrada y salida ajustados desde su hoja de detalles. Úsalo para equilibrar el volumen de efectos de sonido y música, o suavizar el inicio y el final de una pista.","help.entry45.title":"Fotograma clave de cámara","help.entry45.desc":"Registra la posición, el nivel de zoom y la rotación de la cámara en un punto específico de la línea de tiempo. Como los valores se interpolan automáticamente de forma suave entre fotogramas clave, puedes añadir fácilmente movimientos de cámara como paneos o zoom in/out.","help.entry46.title":"Filtro de efecto","help.entry46.desc":"Un efecto visual (desenfoque, corrección de color, resplandor, pixelado, etc.) que puedes aplicar a una escena o fotograma. Úsalo cuando quieras ajustar el aspecto general de la pantalla como un toque de dirección, sin cambiar el dibujo hecho a mano en sí. De los filtros de dibujo, Curva de tonos (un ajuste predefinido y su fuerza), Niveles, Enfoque, Máscara de enfoque, Viñeta (color, alcance y densidad) y Borde de acuarela también son filtros de efecto, para aplicar el mismo efecto a muchos fotogramas a la vez. El filtro de pixel art también permite elegir un modo de color (sin límite, especificar colores, especificar el número de colores o elegir desde una paleta). Cuando los colores están limitados, las zonas a las que ningún color permitido se acerca se forman con dos o tres colores permitidos en un patrón regular (tramado) que no se mueve de un fotograma a otro; los bordes se mantienen nítidos. El tramado se puede desactivar para rellenar cada punto con el color más cercano. Se pueden apilar varios filtros de efecto, y se aplican en el orden en que aparecen en la línea de tiempo. Arrastrar para reordenar la lista de filtros también cambia el orden en que se aplican realmente en pantalla. Un filtro de efecto que aplica un ruido tipo grano de película, cambiándolo fotograma a fotograma. La intensidad, la cantidad (densidad del ruido) y el tamaño del grano se pueden ajustar con controles deslizantes. Volver al mismo fotograma reproduce el mismo grano (sin parpadeo al desplazarte), mientras que al reproducir el grano parece moverse. Un filtro de efecto que muestra lluvia cayendo por la pantalla. La intensidad (número de gotas), la velocidad, el tamaño de gota y el ángulo del viento se pueden ajustar con controles deslizantes. Cada gota sigue cayendo a velocidad constante conforme avanza el fotograma, dando un movimiento de lluvia natural.","help.entry47.title":"Filtros de dibujo","help.entry47.desc":"Filtros aplicados directamente a la capa seleccionada (a diferencia de los filtros de efecto, que se aplican a toda la línea de tiempo o a una escena, los filtros de dibujo actúan por capa). Los 26 filtros incluidos son Desenfoque gaussiano, Desenfoque de lente, Estilo anime, Curva de tonos, Niveles, Contorno, Enfoque, Máscara de enfoque, Viñeta, Anime retro, Tubo de rayos catódicos, Umbral, Ojo de pez, Aberración cromática, Distorsión óptica, Pixel art, Cambio de textura, Mimetismo de fondo, Acumulación de tinta, Dibujo lineal automático, Prisma, Invertir colores, Mosaico, Ruido, Sombreado esférico y Borde de acuarela. Borde de acuarela acumula el color en los bordes de lo pintado en la capa de trabajo y vuelve translúcido el interior, como una acuarela seca (con «También en los límites de color», los límites entre colores vecinos también reciben un borde). Estilo anime reduce los colores y traza una línea del «Grosor del borde» por el lado más oscuro de cada borde donde los colores vecinos difieren al menos el «Umbral de diferencia de color» (las líneas del dibujo no se engrosan). Prisma pinta cada forma de la capa con los seis colores del arcoíris (rojo, verde, cian, azul, morado, rojo), la desenfoca y pone la capa en Sobreexposición lineal. Dibuja antes en su propia capa formas pequeñas y finas como hojas en un color oscuro y obtendrás suaves destellos de arcoíris sobre tu dibujo (la Cantidad de desenfoque se mide como un desenfoque gaussiano normal). Sombreado esférico aplica un color de luz dentro de una luz elíptica y un color de sombra fuera de ella, solo donde hay dibujo (la luz también se puede arrastrar en el lienzo). Contorno no reescribe la capa original: dibuja solo el resultado en una capa nueva. Distorsión óptica aplica una deformación localizada, como a través de una lente de gafas potente, únicamente al área pintada en el lienzo con el «Pincel» y el «Cubo de pintura» del panel (se corrige con la «Goma de borrar»; parte de la selección o de la capa de selección si la hay). Cuando el lienzo tiene una selección, los filtros de dibujo se aplican solo dentro de ella. Pixel art también permite elegir un modo de color (sin límite, colores específicos, número de colores o paleta). Cuando los colores están limitados, las zonas a las que ningún color permitido se acerca se forman con dos o tres colores permitidos dispuestos en un patrón regular (tramado) que se parece más al original; los bordes se mantienen nítidos. Con un número de colores, estos se toman de lo que forma la mayor parte de la imagen. El tramado se puede desactivar para rellenar cada punto con el color más cercano. Su tamaño puede fijarse con el tamaño de bloque (100 pasos, de 1 a 100) o con controles deslizantes de puntos a lo ancho y a lo alto (1 en el extremo izquierdo, el tamaño del lienzo en el derecho); al mover uno, el otro cambia conservando las proporciones del dibujo, y ambas formas de ajuste van a la par. En ambos casos los puntos siguen siendo cuadrados y sin bordes semitransparentes. En Dibujo lineal automático puedes editar los puntos de control vectoriales temporales antes de aplicar el filtro. Arrastra un punto para mover solo ese punto. Elige «Añadir punto de control» junto a Aplicar y toca una línea para añadir un punto, o elige «Eliminar punto de control» y toca un punto para eliminarlo (sin ninguno elegido, tocar un punto pide confirmación antes de eliminarlo). La geometría editada se usa directamente en el resultado aplicado, y mover, añadir o eliminar puntos se puede deshacer y rehacer de uno en uno con Deshacer y Rehacer del editor de filtros. En la Curva de tonos, toca una zona vacía para añadir un punto, arrastra un punto para moverlo y mantenlo pulsado para eliminarlo; las curvas R, G y B se aplican después de la curva RGB. Los Niveles también se pueden ajustar por separado para R, G y B, y la Gamma cambia los tonos medios. El «Alcance hacia dentro» del contorno extiende el borde hacia el interior de la forma original, y la nueva capa del contorno se coloca justo debajo de la capa original. La aberración cromática permite repartir el desplazamiento entre X (horizontal), Y (vertical) y Z (hacia fuera desde el centro). El centro y el radio del ojo de pez también se pueden arrastrar en el lienzo, con la + y el tirador del círculo. Viñeta oscurece suavemente las cuatro esquinas de todo el lienzo (las zonas transparentes sin dibujar también reciben la sombra). «Alcance» fija hasta dónde llega desde las esquinas hacia el centro, e «Intensidad», lo oscuras que quedan las esquinas. Distorsión de lente funciona como unas gafas graduadas reales: lo que se ve a través de la lente se encoge por igual hacia su centro (valores negativos, para la miopía) o se agranda (valores positivos, para la hipermetropía), y el contorno se desplaza en escalón en el borde de la lente. Acumulación de tinta se acumula solo en el interior de los ángulos donde las líneas se juntan con el «Ángulo máximo» o menos (con los 90° iniciales, los agudos y rectos: una V, el lado estrecho de un cruce, una unión en T, una esquina cuadrada), nunca en ángulos más abiertos: en el punto de encuentro tiene el «Grosor central» desde el borde de la línea y se afina en línea recta hasta desaparecer en una punta suave al final del «Rango» (por mucho que se aumente el «Grosor central», nunca se abomba más allá de la recta que une los extremos de las dos acumulaciones: en su máximo, el centro queda plano); si una línea termina antes, la acumulación a lo largo de esa línea se afina hasta desaparecer donde termina, así que cada línea puede tener su propio largo, y aun así las dos acumulaciones se encuentran en el centro del ángulo con el mismo grosor desde cada línea (la de la línea más larga sigue afinándose desde allí hasta el final del rango). Entintado automático sigue el centro de las líneas del boceto y las dibuja finas. Las líneas próximas entre sí siguen siendo líneas separadas mientras quede algún hueco entre ellas; solo se rellenan las pequeñas motas de papel dentro de un trazo. Donde dos líneas se juntan, se van acercando poco a poco como en el boceto, en lugar de convertirse en una sola línea por el centro. Donde las líneas se cruzan o se superponen, cada una sigue tal como está en el boceto (no se dobla hacia el cruce y dos líneas superpuestas no se funden en una). Las líneas que se cruzan en un ángulo poco pronunciado siguen rectas a través del cruce, y las que solo se tocan (como el contorno del pelo dibujado junto a la cabeza) quedan como líneas separadas, cada una por su lado. Los puntos, como los ojos, se dibujan como puntos rellenos. Las ramas más cortas que el «Grosor del boceto» no se dibujan. «Afinar los extremos» se puede activar o desactivar; si se desactiva, las líneas mantienen el mismo grosor hasta sus extremos. Mimetismo de fondo superpone la luz y la sombra del fondo en el modo de fusión «Luz fuerte» (el color de la sombra no es negro ni gris, sino el color de las sombras del propio fondo, oscurecido). El color del entorno se superpone a todo el dibujo en «Superponer» para fijar su tono general, la luz que rebota desde abajo y la que se refleja alrededor se añaden en «Trama», y una luz de color intensa, como un neón, brilla en el contorno en «Suma (brillo)». «Ajustar a los tonos del fondo» lleva los colores más claros o más vivos que el fondo de vuelta a su rango y da a los tonos oscuros, medios y claros el matiz de los tonos del fondo con la misma luminosidad (el negro del dibujo de líneas no cambia). «Intensidad de desenfoque» es cuánto se desenfoca el fondo antes de tomar sus colores.","help.entry48.title":"Automatizaciones personalizadas (grabación de acciones)","help.entry48.desc":"Graba las acciones compatibles del lienzo o la línea de tiempo como una secuencia con nombre que puedes volver a ejecutar. Añade un elemento en Automatizaciones para iniciar la grabación y, antes de guardarlo, reordena o elimina pasos en la pantalla de revisión. Puedes cambiar el nombre, volver a grabar, eliminar, filtrar por favoritos, exportar e importar automatizaciones guardadas como archivos JSON. Si una automatización solo usa el lienzo y se grabó íntegramente en un fotograma, puedes ejecutarla en el fotograma actual, en un intervalo especificado o en todos los fotogramas. Las opciones de intervalo no aparecen en automatizaciones de la línea de tiempo ni en grabaciones que abarcan varios fotogramas.","help.entry49.title":"Fotogramas clave de capa (animación por partes)","help.entry49.desc":"Define la posición, escala y rotación de cada capa por fotograma; los fotogramas clave se interpolan automáticamente. Mientras los fotogramas clave de cámara mueven toda la pantalla, esto mueve una sola capa. Como cada parte del relleno automático se genera como una capa independiente, esto funciona directamente para animar por partes: mover solo un brazo, abrir y cerrar solo una boca, etc. Cada fotograma clave también puede tener su propia interpolación (uniforme, entrada suave, salida suave, entrada y salida suaves, o rebote) que controla cómo se conecta con el siguiente fotograma clave, de modo que el movimiento no tiene por qué ser siempre a velocidad constante. Se configura desde \"Animación (fotogramas clave)\" en el menú de tres puntos de cada capa, en el panel de capas. El dibujo de la capa en sí no cambia: es una transformación no destructiva de dónde se muestra. Esto solo afecta a la visualización de la línea de tiempo (vista previa / exportación) y no afecta al dibujo real en el modo lienzo.","help.entry50.title":"Grupos de capas (mover varias partes juntas)","help.entry50.desc":"Mueve varias capas juntas con un único flujo de fotogramas clave. Por ejemplo, si un \"brazo\" está formado por dos partes de relleno automático —piel y manga—, agruparlas permite mover ambas con una sola operación de fotograma clave. Crea un grupo seleccionando varias capas (casillas) en el panel de capas y tocando el icono \"Agrupar\" en la barra inferior. El movimiento del grupo se superpone a los fotogramas clave propios de cada capa miembro (si los tiene), por lo que puedes combinar el movimiento general del grupo con ajustes finos por capa. Una capa solo puede pertenecer a un grupo a la vez.","help.entry51.title":"EndCard (logotipo final)","help.entry51.desc":"Un vídeo corto (unos 5 segundos) con el logotipo de NIARIM, añadido automáticamente al final del contenido principal al exportar un vídeo. La versión gratuita no puede ocultarlo ni eliminarlo, pero los miembros Premium pueden activarlo/desactivarlo, cambiar su duración o reemplazarlo.","help.entry52.title":"Guardado automático","help.entry52.desc":"Un guardado dedicado a la recuperación en caso de fallo o corrupción de archivo. Se guarda automáticamente cada vez que hay un cambio, como dibujar, y sobrescribe el más antiguo de un máximo de 3 guardados. Se gestiona de forma completamente separada de los guardados manuales (ranuras de guardado y árbol de guardado) y no sustituye al guardado habitual. Solo se te pregunta si quieres restaurarlo al reiniciar la aplicación tras un cierre anómalo.","help.entry53.title":"Ranura de guardado","help.entry53.desc":"Un método de guardado en un número fijo de ranuras, donde eliges qué ranura usar cada vez. El número de ranuras lo determinan los ajustes (5 para calidad baja, 10 para calidad media). Como eliges qué ranura sobrescribir cada vez, es una forma sencilla de gestionar la conservación del estado de un momento concreto.","help.entry54.title":"Árbol de guardado","help.entry54.desc":"Un método de guardado en el que se crea un nuevo punto de guardado cada vez que guardas, y puedes ramificar desde un punto de guardado pasado para crear un historial diferente. No hay límite en el número de guardados, lo que lo hace muy adecuado para casos como \"quiero volver a esa versión y probar un desarrollo diferente\". En la pantalla, los puntos de guardado se muestran como un diagrama de árbol que crece de abajo hacia arriba.","help.entry55.title":"Carpeta","help.entry55.desc":"Una función para agrupar y organizar tus proyectos (obras). Admite varios niveles de anidación, por lo que también puedes usarla para gestionar juntos varios episodios o una serie de la misma obra (por ejemplo, organizando los proyectos \"Episodio 1\", \"Episodio 2\", etc. dentro de una carpeta con el nombre de la obra). Si quieres dividir un solo vídeo en escenas separadas, usa la función \"Escena\" de la pantalla del lienzo en lugar de carpetas.","help.entry56.title":"Papelera","help.entry56.desc":"El lugar donde se mueven temporalmente los proyectos eliminados. Puedes restaurarlos desde aquí hasta que se eliminen permanentemente. Puedes establecer el número de días hasta la eliminación automática (desactivado/30/60/90 días) en los ajustes.","help.entry57.title":"Compartir (.niashare)","help.entry57.desc":"Un formato de archivo dedicado para entregar un proyecto a otra persona (o a otro dispositivo tuyo). Cuando el destinatario abre este archivo, se duplica y se añade a su propia lista de proyectos. El archivo .niashare original en sí no se modifica.","help.entry58.title":"Transferencia (.niatra)","help.entry58.desc":"Una función para transferir todo el entorno de la aplicación —ajustes, materiales, pinceles, ajustes de relleno automático, tema, paletas (selector de color y pixel art) y más— a otro dispositivo de una sola vez. Puedes elegir elementos individuales para transferir con casillas de verificación, e incluir opcionalmente proyectos en curso (los proyectos seleccionados se transfieren completos, con sus materiales y fuentes). Si solo quieres entregar un proyecto individual, también puedes usar \"Compartir (.niashare)\".","help.entry59.title":"Exportación de vídeo (MP4, WebM, GIF, AVI)","help.entry59.desc":"Exporta tu obra como un video MP4 estandar. La version gratuita tiene un limite de duracion (90 segundos) y anade automaticamente una tarjeta final (logotipo de la app) al final del video. Un formato de vídeo que se puede exportar conservando el canal alfa (las partes transparentes del fondo). La reproducción transparente solo funciona en entornos de reproducción compatibles. Ideal para superponer como material en otras aplicaciones. Exporta como GIF animado. Como se reproduce en bucle automaticamente, es ideal para compartir de forma casual en redes sociales. Si la compatibilidad es lo más importante, también puedes exportar como AVI (Motion JPEG). No admite canal alfa (transparencia), y la vista previa dentro de la app puede no funcionar en todos los dispositivos (aun así puedes reproducirlo con un reproductor externo mediante Compartir). Las cuentas gratuitas tienen un límite de 90 segundos de duración de proyecto (las cuentas Premium tienen 2 horas). Si añadir o duplicar fotogramas te haría superar el límite, aparece un aviso justo al tocar el botón, así que nunca llegas a superar los 90 segundos.","help.entry60.title":"Pantalla de exportación","help.entry60.desc":"En «Preajuste», elige «Estándar», «Alta calidad» o «Personalizado». Con «Personalizado» puedes ajustar los fotogramas por segundo (FPS). Muestra el progreso al exportar un vídeo o una imagen, y permite cancelar a mitad de camino. El tiempo que tarda depende del rendimiento del dispositivo.","help.entry61.title":"Plaza de Obras","help.entry61.desc":"Publica tus animaciones e ilustraciones en la comunidad como vídeos de YouTube y explora las obras de otros usuarios. Cambia entre las pestañas «Nuevas», «Ranking» y «Siguiendo», y busca por título de la obra o nombre del creador. Cambia al modo de búsqueda por etiquetas para filtrar obras por etiqueta: cualquier usuario (no solo el creador) puede añadir o quitar etiquetas, aunque las etiquetas bloqueadas por el creador solo él puede quitarlas, y tocar una etiqueta filtra al instante las obras con la misma etiqueta. Al tocar una tarjeta de obra se abre una ventana de vista previa flotante que se puede arrastrar y redimensionar, para seguir explorando otras pantallas mientras se reproduce. El botón «Ver detalles» abre la pantalla de detalles de la obra (creador, fecha de publicación, edición de etiquetas, marcador, republicación y más). Toca el botón «Seguir» junto al nombre de un creador para añadirlo a tus seguidos: la pestaña «Siguiendo» reúne entonces solo las publicaciones de ese creador, ordenadas por fecha. Cuando alguien te sigue, aparece en la lista de notificaciones bajo el icono de la campana en la parte superior de la pantalla. Puedes elegir si tus listas de seguidos/seguidores son visibles para otros usuarios (privadas por defecto), y puedes ver las listas de otros usuarios si las han hecho públicas. Puedes republicar la obra de cualquier otra persona (excepto la tuya propia) con el botón «Republicar»; cuando un creador al que sigues republica la obra de otra persona, esa obra también aparece en tu pestaña «Siguiendo», ordenada según lo que sea más reciente —su fecha de publicación original o su fecha de republicación— (la tarjeta muestra «Republicado por…»). Las obras marcadas aparecen juntas en la pestaña «Guardadas» de la pantalla de inicio, y también en la pestaña «Marcadores» de la pantalla de obras de un creador. Puedes elegir si tu propia lista de marcadores es visible para otros usuarios (privada de forma predeterminada), y puedes ver las listas de marcadores de otros usuarios si las han hecho públicas. Puedes denunciar una obra indicando un motivo, y tras enviarla se te preguntará si quieres bloquear a ese creador. Los vídeos verticales se pueden ver en «modo vertical», que los reproduce uno tras otro como un feed de vídeos cortos. Hay un límite diario de publicaciones: 1 al día para miembros gratuitos y 3 al día para miembros Premium. El botón de filtros de visualización de la parte superior derecha (el icono de un ojo tachado) te permite ocultar las obras que no quieras ver. Puedes ocultar las obras marcadas con «Contiene imágenes o vídeo de IA generativa» y añadir palabras ocultas del título (solo se comparan con el título de la obra) y etiquetas ocultas (solo se comparan con las etiquetas de la Plaza de Obras) de una en una con «Añadir nuevo». Edita con el lápiz o elimina con la papelera; no hacen falta comas ni #. Estos filtros se aplican a «Nuevas», «Ranking», «Siguiendo» (incluidas las republicaciones), el modo vertical, las páginas de los creadores, los detalles de las obras y los marcadores. «Contiene imágenes o vídeo de IA generativa» lo declara quien publica en el momento de publicar, y después solo esa persona puede cambiarlo (desde «Mis publicaciones» o la pantalla de detalles de la obra).","help.entry62.title":"Reeditar una marca de agua","help.entry62.desc":"Tocar una marca de agua colocada en la pista de capa común de la línea de tiempo permite reeditar en cualquier momento su ángulo, tamaño, opacidad y rango de visualización (bucle). Puedes ajustarla con precisión no solo al registrarla, sino siempre que la estés usando en un proyecto.","help.entry63.title":"Marca de agua","help.entry63.desc":"Una función exclusiva de la versión premium que te permite añadir tu propia firma o logotipo como marca de agua en los vídeos e imágenes exportados. Puedes ajustar su posición, tamaño y opacidad. Toca la marca de agua colocada en la pista de capa común de la línea de tiempo para reeditar en cualquier momento su ángulo, tamaño, opacidad y rango visible (bucle), no solo al registrarla, sino cada vez que la uses en un proyecto. Para añadir una marca de agua, abre «Añadir material» en la línea de tiempo y elige «+ Marca de agua».","help.entry64.title":"Premium","help.entry64.desc":"La membresia premium amplia hasta 2 horas el limite de 90 segundos de duracion de video de la version gratuita y te permite quitar la tarjeta final (logotipo de la app) que se anade automaticamente al final de cada video. Tambien se ocultan los anuncios y obtienes acceso a la marca de agua, la curva de tonos y la correccion de niveles.","help.entry65.title":"Pantalla de inicio","help.entry65.desc":"La primera pantalla que se muestra al abrir la app, con las pestañas Proyectos, Compartidos, Obras y Papelera. El icono de búsqueda arriba a la derecha permite filtrar proyectos por nombre. En la pestaña Proyectos, el botón flotante permite elegir entre crear un nuevo proyecto o una nueva carpeta.","help.entry66.title":"Nuevo proyecto","help.entry66.desc":"Configura el tamaño del lienzo, los fps, la duración (en segundos; luego se mantiene sincronizada con los cambios de fotogramas hechos en la línea de tiempo), el área de dibujo (permite dibujar más allá de los límites de exportación) y qué ajustes de relleno automático usar, todo antes de crear el proyecto.","help.entry67.title":"Pantalla de detalles del proyecto","help.entry67.desc":"Una pantalla para consultar y editar en un solo lugar los ajustes de cada proyecto: nombre, miniatura, estado de favorito y qué ajustes de relleno automático están activados. El acceso al árbol de guardado también está aquí.","help.entry68.title":"Ajustes de tema","help.entry68.desc":"Elige la paleta de colores general de la app de la lista de temas, o personaliza libremente el color de acento. Los títulos/etiquetas y el texto de cuerpo usan fuentes distintas, así que puedes cambiar el aspecto de la app manteniendo la legibilidad.","help.entry69.title":"Ajustes del espacio de trabajo","help.entry69.desc":"Reúne ajustes como el modo zurdo (invierte los paneles acoplados), el cambio manual entre modo PC/DeX y cuándo se muestra la herramienta de mano. Ajusta el diseño según tu dispositivo y tu mano dominante.","help.entry70.title":"Ajustes de gestos","help.entry70.desc":"Permite asignar acciones —deshacer/rehacer, mover fotograma, cuentagotas y más— a un toque con dos dedos, un toque con tres dedos, un deslizamiento con dos dedos o una pulsación larga. Los botones del lápiz (en lápices compatibles) también se pueden asignar por separado. Útil para activar acciones frecuentes con un solo toque sin cambiar de herramienta.","help.entry71.title":"Ajustes del lápiz","help.entry71.desc":"Junto con la curva de presión para tabletas y pantallas con lápiz, esta pantalla permite asignar acciones —como alternar el borrador o el cuentagotas— a los botones laterales de un lápiz compatible.","help.entry72.title":"Detección de inclinación","help.entry72.desc":"Un ajuste que usa los datos de inclinación de un lápiz compatible para engrosar o afinar la línea al tumbar la punta, recreando una sensación más cercana a una herramienta de dibujo real. Actívalo o desactívalo desde los ajustes de rendimiento.","help.entry73.title":"Ajustes de rendimiento","help.entry73.desc":"Elige entre los preajustes de calidad baja, media o alta según la capacidad de tu dispositivo, o configura cada elemento individualmente (personalizado). Además del método de guardado, el rendimiento, el papel cebolla y la detección de inclinación, aquí también se agrupan los ajustes que afectan al tamaño de la aplicación y a su fluidez, como la longitud del historial de deshacer y la eliminación automática de la papelera.","help.entry74.title":"Ajustes detallados de relleno con cubo","help.entry74.desc":"Desde la sección \"Relleno con cubo\" de los ajustes puedes ajustar la tolerancia (cuánta diferencia de color respecto al píxel pulsado sigue contando como la misma zona), la expansión en px (cuánto se extiende el área rellenada más allá del borde para cubrir huecos en la línea) y rellenar bajo la línea (compone el relleno expandido detrás de los píxeles existentes en lugar de pintar sobre la línea, manteniendo su aspecto intacto). Ajustarlos ayuda cuando la línea tiene pequeños huecos o el relleno queda incompleto.","help.entry75.title":"Longitud del historial de deshacer","help.entry75.desc":"En los ajustes de rendimiento puedes ajustar cuántas acciones puede retroceder deshacer. Un número mayor da más libertad para experimentar, pero también usa más memoria; redúcelo en dispositivos de gama baja para que todo vaya más fluido.","help.entry76.title":"Importar fuentes","help.entry76.desc":"Permite cargar un archivo de fuente directamente desde el almacenamiento del dispositivo. Añádela desde la pestaña \"Importar\" en la gestión de fuentes, en ajustes. Útil cuando quieres usar una fuente personalizada que no se distribuye en ningún sitio, o una fuente comercial que has comprado.","help.entry77.title":"Liberar espacio","help.entry77.desc":"Consulta cuánto espacio usa NIARIM en tu dispositivo y un desglose de su contenido interno (proyectos, materiales, archivos exportados, pinceles/tramas/sellos/fuentes personalizados, caché y papelera) en gráficos circulares. Puedes borrar la caché, eliminar materiales sin usar en todos los proyectos, vaciar la papelera, organizar proyectos o borrar todos los datos (restablecer).","help.entry78.title":"Widgets de la pantalla de inicio","help.entry78.desc":"Ajustes de los tres tipos de widget que puedes colocar en la pantalla de inicio del teléfono: un fotograma de una obra (arranque), el widget de crear obra y el widget de la plaza. Los widgets en sí se añaden manteniendo pulsada la pantalla de inicio, no desde dentro de la app. «Elegir una obra» usa el mismo orden, modo de visualización, búsqueda y filtro de favoritos que la pestaña de proyectos, y luego te deja elegir el fotograma exacto en una vista previa con controles de reproducción. Los widgets de crear obra y de la plaza permiten elegir si el fondo sigue el tema de la app o usa un color que tú especifiques.","help.lead":"Los mismos 79 temas y descripciones de ayuda de la aplicación, con búsqueda por palabra clave o categoría."}};var store=window.NIARIM_I18N_DICT||(window.NIARIM_I18N_DICT={});for(var lang in tables){if(!Object.prototype.hasOwnProperty.call(tables,lang))continue;store[lang]=Object.assign(store[lang]||{},tables[lang]);}})();
